    explodeCorpsesDummy = A.thunderClap({
        name = "Explode Corpses",
        buffs = {},
        apply = A.thunderClap.apply(function(a, level)
            a:setAttackSpeedReduction(level, 0)
            a:setMovementSpeedReduction(level, 0)
            -- a:setTargetType() -- dead
        end),
    }),
}]]

