P['data/generated/ability_factories.lua'] = [[local AbilityIds = require("vendor.assets.AbilityIds")
local AbilityBaseIds = require("data.abilityBaseIds")

---@class AbilityRowInput
---@field name? string
---@field levels? integer
---@field buffs? string[]
---@field autocastRange? number
---@field options? integer
---@field button? integer[]
---@field hotkey? string
---@field requirements? string
---@field manaCost? number|number[]
---@field art? { icon?: string, iconOff?: string, iconResearch?: string }
---@field order? string
---@field apply? fun(a: AbilityDefinition, level?: integer)

---@class AbilityRow : AbilityRowInput
---@field parent string

---@class AbilityFactory
---@field parent string
---@overload fun(data?: AbilityRowInput): AbilityRow

local function pack(parent, data)
    data = data or {}
    data.parent = parent
    return data
end

local function identity(fn)
    return fn
end

local callMt = {
    __call = function(self, data)
        return pack(self.parent, data)
    end,
}

---@class PresetFactory
---@overload fun(base: AbilityFactoryNeutralSpell, preset: AbilityRowInputNeutralSpell): AbilityFactoryNeutralSpell
---@overload fun(base: AbilityFactoryAuraCommandCreep, preset: AbilityRowInputAuraCommandCreep): AbilityFactoryAuraCommandCreep
---@overload fun(base: AbilityFactoryAnimateDead, preset: AbilityRowInputAnimateDead): AbilityFactoryAnimateDead
---@overload fun(base: AbilityFactoryAntimagicShell, preset: AbilityRowInputAntimagicShell): AbilityFactoryAntimagicShell
---@overload fun(base: AbilityFactoryTrueshotAura, preset: AbilityRowInputTrueshotAura): AbilityFactoryTrueshotAura
---@overload fun(base: AbilityFactoryDevotionAura1, preset: AbilityRowInputDevotionAura1): AbilityFactoryDevotionAura1
---@overload fun(base: AbilityFactoryBrillianceAura1, preset: AbilityRowInputBrillianceAura1): AbilityFactoryBrillianceAura1
---@overload fun(base: AbilityFactoryBreathofFireCreep, preset: AbilityRowInputBreathofFireCreep): AbilityFactoryBreathofFireCreep
---@overload fun(base: AbilityFactoryBreathofFrostCreep, preset: AbilityRowInputBreathofFrostCreep): AbilityFactoryBreathofFrostCreep
