Storage.ht = htApi.ht
Storage.GLOBAL = htApi.GLOBAL

return Storage]]

P['lib/storage/instance.lua'] = [[local htApi = require("lib.storage.ht")

local instances = {}

local PARENT_ACCESSORS = {
    {
        prefix = "Int",
        get = htApi.getInt,
        set = htApi.setInt,
    },
    {
        prefix = "Real",
        get = htApi.getReal,
        set = htApi.setReal,
    },
    {
        prefix = "Bool",
        get = htApi.getBool,
        set = htApi.setBool,
    },
    {
        prefix = "UnitHandle",
        get = htApi.getUnitHandle,
        set = htApi.setUnitHandle,
    },
}

local Storage = {}

function Storage.new(name, opts)
    opts = opts or {}
    if instances[name] then
        error("duplicate storage instance: " .. name)
    end

    local nsId = htApi.getOrAssignNsId(name)
    local mode = opts.mode or "raw"
    local activeRegistry = {}

    local instance = {
        name = name,
        nsId = nsId,
        mode = mode,
    }

    function instance:parent(key)
        return nsId * 1000000 + key
    end

    function instance:register(id)
        activeRegistry[id] = true
    end

    function instance:unregister(id)
        activeRegistry[id] = nil
    end

    function instance:eachActive(fn)
        for id in pairs(activeRegistry) do
            fn(id)
        end
    end

    function instance:clearActive()
        for id in pairs(activeRegistry) do
            activeRegistry[id] = nil
        end
    end

    function instance:unitParent(unit)
        return StringHash(name .. ":u:" .. tostring(GetHandleId(unit)))
    end

    function instance:flush(key)
        htApi.flushChild(self:parent(key))
    end

    function instance:hasSaved(parentKey, fieldKey)
        return htApi.haveSaved(self:parent(parentKey), fieldKey)
    end

    for _, accessor in ipairs(PARENT_ACCESSORS) do
        instance["get" .. accessor.prefix] = function(self, parentKey, fieldKey)
            return accessor.get(self:parent(parentKey), fieldKey)
        end
        instance["set" .. accessor.prefix] = function(self, parentKey, fieldKey, value)
            accessor.set(self:parent(parentKey), fieldKey, value)
        end
    end

    if mode == "record" or mode == "unit" or mode == "unitFields" then
        local slot = htApi.allocSlot(name)

        function instance:maxAlloc()
            return htApi.getInt(htApi.GLOBAL, slot)
        end

        function instance:alloc()
            local nextId = self:maxAlloc() + 1
            htApi.setInt(htApi.GLOBAL, slot, nextId)
            return nextId
        end
    end

    instances[name] = instance
    return instance
end

function Storage.initAll()
    for _, instance in pairs(instances) do
        if instance.init then
            instance:init()
        end
    end
end

return Storage]]

P['lib/storage/record.lua'] = [[local schema = require("lib.storage.schema")
local Storage = require("lib.storage.instance")

return function(name, recordSchema)
    local store = Storage.new(name, { mode = "record" })
    local fields = schema.buildFieldMap(recordSchema.fields)
    local existsField = recordSchema.existsField
    local indexMaps = {}

    if recordSchema.indexes then
        for indexName, fieldNames in pairs(recordSchema.indexes) do
            indexMaps[indexName] = {
                fieldNames = fieldNames,
                map = {},
            }
        end
    end

    local fieldIndexes = {}
    for _, index in pairs(indexMaps) do
        for _, fieldName in ipairs(index.fieldNames) do
            if fields[fieldName] and fields[fieldName].type == "unit" then
                local list = fieldIndexes[fieldName]
                if not list then
                    list = {}
                    fieldIndexes[fieldName] = list
                end
                list[#list + 1] = index
            end
        end
    end

    local function writeField(recordId, fieldName, value)
        local field = fields[fieldName]
        field.access.set(store:parent(recordId), field.child, value)
    end

    local function readField(recordId, fieldName)
        local field = fields[fieldName]
        return field.access.get(store:parent(recordId), field.child)
    end

    local function syncIndexedUnitField(recordId, fieldName, value)
        local indexes = fieldIndexes[fieldName]
        if not indexes then
            return
        end
        local oldUnit = readField(recordId, fieldName)
        for _, index in ipairs(indexes) do
            if oldUnit and index.map[oldUnit] == recordId then
                index.map[oldUnit] = nil
            end
            if value then
                local existing = index.map[value]
                if existing and existing ~= recordId then
                    error(name .. ": unit already indexed by record " .. existing)
                end
                index.map[value] = recordId
            end
        end
    end

    local function registerIndexes(recordId, data)
        for _, index in pairs(indexMaps) do
            for _, fieldName in ipairs(index.fieldNames) do
                local unit = data[fieldName]
                if unit then
                    index.map[unit] = recordId
                end
            end
        end
    end

    local function unregisterIndexes(recordId)
        for _, index in pairs(indexMaps) do
            for unit, mappedId in pairs(index.map) do
                if mappedId == recordId then
                    index.map[unit] = nil
                end
            end
        end
    end

    local function exists(recordId)
        if existsField then
            local field = fields[existsField]
            return field.access.have(store:parent(recordId), field.child)
        end
        for _, field in pairs(fields) do
            if field.access.have(store:parent(recordId), field.child) then
                return true
            end
        end
        return false
    end

    function store:has(recordId)
        return exists(recordId)
    end

    function store:read(recordId)
        if not exists(recordId) then
            return nil
        end
        local data = {}
        for fieldName in pairs(fields) do
            data[fieldName] = readField(recordId, fieldName)
        end
        return data
    end

    function store:create(recordId, data)
        if exists(recordId) then
            return false
        end
        for _, index in pairs(indexMaps) do
            for _, fieldName in ipairs(index.fieldNames) do
                local unit = data[fieldName]
                if unit and index.map[unit] then
                    return false
                end
            end
        end

        for fieldName, field in pairs(fields) do
            local value = data[fieldName]
            if value == nil then
                value = field.default
            end
            if value ~= nil then
                writeField(recordId, fieldName, value)
            end
        end

        registerIndexes(recordId, data)
        self:register(recordId)
        return true
    end

    local RECORD_MT = {
        __index = function(t, key)
            if fields[key] then
                return readField(t.id, key)
            end
        end,
        __newindex = function(t, key, value)
            if fields[key] then
                if fieldIndexes[key] then
                    syncIndexedUnitField(t.id, key, value)
                end
                writeField(t.id, key, value)
                return
            end
            error("unknown record field: " .. key)
        end,
    }

    function store:bind(recordId)
        if not exists(recordId) then
            return nil
        end
        return setmetatable({ id = recordId }, RECORD_MT)
    end

    function store:drop(recordId)
        if not exists(recordId) then
            return
        end
        unregisterIndexes(recordId)
        self:flush(recordId)
        self:unregister(recordId)
    end

    function store:find(unit)
        for _, index in pairs(indexMaps) do
            local recordId = index.map[unit]
            if recordId then
                return recordId
            end
        end
        return nil
    end

    function store:each(fn)
        self:eachActive(fn)
    end

    function store:init()
        for _, index in pairs(indexMaps) do
            for unit in pairs(index.map) do
                index.map[unit] = nil
            end
        end
        self:clearActive()

        local maxId = self:maxAlloc()
        for recordId = 1, maxId do
            local data = self:read(recordId)
            if data then
                self:register(recordId)
                registerIndexes(recordId, data)
            end
        end
    end

    return store
end]]

P['lib/storage/schema.lua'] = [[local htApi = require("lib.storage.ht")

local FIELD_TYPES = {
    int = {
        get = htApi.getInt,
        set = htApi.setInt,
        have = function(parent, child)
            return HaveSavedInteger(htApi.ht, parent, child)
        end,
    },
    real = {
        get = htApi.getReal,
        set = htApi.setReal,
        have = function(parent, child)
            return HaveSavedReal(htApi.ht, parent, child)
        end,
    },
    bool = {
        get = htApi.getBool,
        set = htApi.setBool,
        have = function(parent, child)
            return HaveSavedBoolean(htApi.ht, parent, child)
        end,
    },
    unit = {
        get = htApi.getUnitHandle,
        set = htApi.setUnitHandle,
        have = function(parent, child)
            return HaveSavedHandle(htApi.ht, parent, child)
        end,
    },
}

local function normalizeFieldSpec(spec)
    if type(spec) == "string" then
        return { type = spec }
    end
    return spec
end

local function buildFieldMap(schemaFields)
    local fields = {}
    for name, spec in pairs(schemaFields) do
        local normalized = normalizeFieldSpec(spec)
        local fieldType = FIELD_TYPES[normalized.type]
        if not fieldType then
            error("unknown field type '" .. tostring(normalized.type) .. "'")
        end
        fields[name] = {
            child = normalized.child or StringHash(name),
            type = normalized.type,
            default = normalized.default,
            access = fieldType,
        }
    end
    return fields
end

return {
    buildFieldMap = buildFieldMap,
}]]

P['lib/storage/storage.lua'] = [[return require("lib.storage.init")]]

P['lib/storage/unitFields.lua'] = [[local htApi = require("lib.storage.ht")
local schema = require("lib.storage.schema")
local Storage = require("lib.storage.instance")

---@param name string
---@param fieldSchema table
return function(name, fieldSchema)
    local store = Storage.new(name, { mode = "unitFields" })
    local fields = schema.buildFieldMap(fieldSchema)
    local units = {}
    local unitToId = {}

    local function requireField(fieldName)
        local field = fields[fieldName]
        if not field then
            error("unknown field '" .. fieldName .. "' on " .. name)
        end
        return field
    end

    local function hasData(unit)
        local parent = store:unitParent(unit)
        for _, field in pairs(fields) do
            if field.access.have(parent, field.child) then
                return true
            end
        end
        return false
    end

    local function trackUnit(unit)
        if unitToId[unit] then
            return
        end
        local id = store:alloc()
        store:setUnitHandle(id, htApi.FIELD_UNIT, unit)
        unitToId[unit] = id
    end

    local function readField(unit, fieldName)
        local field = requireField(fieldName)
        return field.access.get(store:unitParent(unit), field.child)
    end

    local function writeField(unit, fieldName, value)
        trackUnit(unit)
        units[unit] = true
        local field = requireField(fieldName)
        field.access.set(store:unitParent(unit), field.child, value)
    end

    function store:has(unit)
        return not not units[unit] or hasData(unit)
    end

    function store:get(unit, fieldName)
        if fieldName == nil then
            error("unitFields:get(unit, nil) is forbidden call")
        end
        return readField(unit, fieldName)
    end

    function store:set(unit, fieldName, value)
        writeField(unit, fieldName, value)
    end

    local UNIT_MT = {
        __index = function(t, key)
            if fields[key] then
                return readField(t._key, key)
            end
        end,
        __newindex = function(t, key, value)
            if fields[key] then
                writeField(t._key, key, value)
                return
            end
            error("unknown field '" .. key .. "' on " .. name)
        end,
    }

    function store:bind(unit)
        if not hasData(unit) then
            return nil
        end
        units[unit] = true
        return setmetatable({ _key = unit }, UNIT_MT)
    end

    function store:drop(unit)
        htApi.flushChild(self:unitParent(unit))
        local id = unitToId[unit]
        if id then
            self:flush(id)
            unitToId[unit] = nil
        end
        units[unit] = nil
    end

    function store:each(fn)
        for unit in pairs(units) do
            fn(unit)
        end
    end

    function store:init()
        for unit in pairs(units) do
            units[unit] = nil
        end
        for unit in pairs(unitToId) do
            unitToId[unit] = nil
        end

        local maxId = self:maxAlloc()
        for id = 1, maxId do
            if self:hasSaved(id, htApi.FIELD_UNIT) then
                local unit = self:getUnitHandle(id, htApi.FIELD_UNIT)
                if unit and hasData(unit) then
                    unitToId[unit] = id
                    units[unit] = true
                end
            end
        end
    end

    return store
end]]

P['lib/storage/unitSet.lua'] = [[local htApi = require("lib.storage.ht")
local Storage = require("lib.storage.instance")

return function(name)
    local store = Storage.new(name, { mode = "unit" })
    local units = {}
    local unitToId = {}

    function store:add(unit)
        local existingId = unitToId[unit]
        if existingId then
            return existingId
        end
        local id = self:alloc()
        self:setUnitHandle(id, htApi.FIELD_UNIT, unit)
        self:register(id)
        unitToId[unit] = id
        units[unit] = true
        return id
    end

    function store:has(unit)
        return not not unitToId[unit]
    end

    function store:drop(unit)
        local id = unitToId[unit]
        if not id then
            return
        end
        self:flush(id)
        self:unregister(id)
        unitToId[unit] = nil
        units[unit] = nil
    end

    function store:each(fn)
        for unit in pairs(units) do
            fn(unit)
        end
    end

    function store:init()
        for unit in pairs(units) do
            units[unit] = nil
        end
        for unit in pairs(unitToId) do
            unitToId[unit] = nil
        end
        self:clearActive()

        local maxId = self:maxAlloc()
        for id = 1, maxId do
            if self:hasSaved(id, htApi.FIELD_UNIT) then
                local unit = self:getUnitHandle(id, htApi.FIELD_UNIT)
                if unit then
                    self:register(id)
                    unitToId[unit] = id
                    units[unit] = true
                end
            end
        end
    end

    return store
end]]

P['lib/triggers/callbacks.lua'] = [[-- TODO:
-- - use conditions
-- - accept function instead of handle or {handle} -> pass event if function(handle) is true
local Storage = require("lib.storage.storage")
local Filter = require("lib.triggers.filter")

local Disable = Storage.unitFields("disable", {
    rooted = "bool",
    stunned = "bool",
})

local T = {
    callbacks = {},
    buffs = {
        root = {},
        stun = {},
    },
}

---@param event string
---@param callbackOptions TriggerDefinition
T.registerCallback = function(event, callbackOptions)
    Filter.compileTrigger(callbackOptions)
    local original = callbackOptions.action
    callbackOptions.action = function(...)
        Debug.try(original, ...)
    end
    if T.callbacks[event] == nil then
        T.callbacks[event] = {}
    end
    table.insert(T.callbacks[event], callbackOptions)
end

T.registerBuffs = function(tag, buffs)
    T.buffs[tag] = buffs
end

T.fireEvent = function(event, ctx)
    local callbacks = T.callbacks[event]
    if not callbacks then
        return
    end
    Filter.run(callbacks, ctx or {}, true)
end

T.onCustomEvent = function(_triggers) end

local function registerUnitEvent(event, triggers, ctxFn)
    local trig = CreateTrigger()
    TriggerRegisterAnyUnitEventBJ(trig, event)
    TriggerAddAction(trig, function()
        Filter.run(triggers, ctxFn())
    end)
end

T.onStun = function(_triggers)
    -- TODO: change to UNIT_TYPE_STUNNED
    Damage.register("After", function(info)
        local unit = info.target

        if not Disable:get(unit, "stunned") and (IsUnitType(unit, UNIT_TYPE_STUNNED)) then
            T.fireEvent("STUN", info)
            Disable:set(unit, "stunned", true)
        elseif Disable:get(unit, "stunned") and not IsUnitType(unit, UNIT_TYPE_STUNNED) then
            Disable:set(unit, "stunned", false)
        end

        if not Disable:get(unit, "rooted") and not Disable:get(unit, "stunned") then
            Disable:drop(unit)
        end
    end, 1.0)
end

T.onRoot = function(_triggers)
    Damage.register("After", function(info)
        local unit = info.target

        if not Disable:get(unit, "rooted") and (IsUnitType(unit, UNIT_TYPE_SNARED) or GetUnitPropWindow(unit) == 0) then
            T.fireEvent("ROOT", info)
            Disable:set(unit, "rooted", true)
        elseif
            Disable:get(unit, "rooted") and not (IsUnitType(unit, UNIT_TYPE_SNARED) or GetUnitPropWindow(unit) == 0)
        then
            Disable:set(unit, "rooted", false)
        end

        if not Disable:get(unit, "rooted") and not Disable:get(unit, "stunned") then
            Disable:drop(unit)
        end
    end, 1.0)
end

T.onAttack = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_ATTACKED, triggers, function()
        return { source = GetAttacker() }
    end)
end

T.onDeath = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_DEATH, triggers, function()
        return { target = GetDyingUnit() }
    end)
end

T.onSummon = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_SUMMON, triggers, function()
        return { target = GetSummonedUnit() }
    end)
end

T.onSpellCast = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_SPELL_CAST, triggers, function()
        return { spellId = GetSpellAbilityId() }
    end)
end

T.onSpellEffect = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_SPELL_EFFECT, triggers, function()
        return { spellId = GetSpellAbilityId() }
    end)
end

T.onSpellEndcast = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_SPELL_ENDCAST, triggers, function()
        return { spellId = GetSpellAbilityId() }
    end)
end

T.onSpellFinish = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_SPELL_FINISH, triggers, function()
        return { spellId = GetSpellAbilityId() }
    end)
end

local function registerFilteredDamageTriggers(phase, triggers)
    for _, trigger in ipairs(triggers) do
        Damage.register(phase, function(info)
            if Filter.matches(trigger, info) then
                trigger.action(info)
            end
        end, trigger.priority or 0)
    end
end

T.onPreDamage = function(triggers)
    registerFilteredDamageTriggers("Pre", triggers)
end

T.onDamage = function(triggers)
    registerFilteredDamageTriggers("On", triggers)
end

T.onLethalDamage = function(triggers)
    registerFilteredDamageTriggers("Lethal", triggers)
end

T.afterDamage = function(triggers)
    registerFilteredDamageTriggers("After", triggers)
end

T.onAnyOrder = function(triggers)
    local trig = CreateTrigger()
    TriggerRegisterAnyUnitEventBJ(trig, EVENT_PLAYER_UNIT_ISSUED_ORDER)
    TriggerRegisterAnyUnitEventBJ(trig, EVENT_PLAYER_UNIT_ISSUED_POINT_ORDER)
    TriggerRegisterAnyUnitEventBJ(trig, EVENT_PLAYER_UNIT_ISSUED_TARGET_ORDER)
    TriggerAddAction(trig, function()
        Filter.run(triggers, { source = GetTriggerUnit() })
    end)
end

T.onOrder = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_ISSUED_ORDER, triggers, function()
        return { source = GetTriggerUnit(), orderId = GetIssuedOrderId() }
    end)
end

T.onTargetOrder = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_ISSUED_TARGET_ORDER, triggers, function()
        return { source = GetTriggerUnit(), orderId = GetIssuedOrderId() }
    end)
end

T.onPointOrder = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_ISSUED_POINT_ORDER, triggers, function()
        return { source = GetTriggerUnit(), orderId = GetIssuedOrderId() }
    end)
end

T.onTrainStart = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_TRAIN_START, triggers, function()
        return { source = GetTriggerUnit() }
    end)
end

T.onTrain = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_TRAIN_FINISH, triggers, function()
        return { source = GetTriggerUnit(), target = GetTrainedUnit() }
    end)
end

T.onConstructFinish = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_CONSTRUCT_FINISH, triggers, function()
        return { source = GetTriggerUnit(), target = GetConstructedStructure() }
    end)
end

T.onSelect = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_SELECTED, triggers, function()
        return {}
    end)
end

T.onPickUpItem = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_PICKUP_ITEM, triggers, function()
        return {}
    end)
end

T.onDropItem = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_DROP_ITEM, triggers, function()
        return {}
    end)
end

T.onPawnItem = function(triggers)
    registerUnitEvent(EVENT_PLAYER_UNIT_DROP_ITEM, triggers, function()
        return {}
    end)
end

T.onCreate = function(triggers)
    local trig = CreateTrigger()
    TriggerRegisterEnterRectSimple(trig, GetWorldBounds())
    TriggerAddAction(trig, function()
        Filter.run(triggers, { target = GetEnteringUnit() })
    end)
end

T.onTimer = function(triggers)
    for _, timer in ipairs(triggers) do
        TimerStart(CreateTimer(), timer.delta, true, function()
            timer.action()
        end)
    end
end

T.registerEvents = function(callbacks)
    for event, triggers in pairs(callbacks) do
        T.methods[event](triggers)
    end
end

T.methods = {
    EVENT_PLAYER_UNIT_SELECTED = T.onSelect,
    EVENT_PLAYER_UNIT_ATTACKED = T.onAttack,
    EVENT_PLAYER_UNIT_SPELL_CAST = T.onSpellCast,
    EVENT_PLAYER_UNIT_SPELL_EFFECT = T.onSpellEffect,
    EVENT_PLAYER_UNIT_SPELL_ENDCAST = T.onSpellEndcast,
    EVENT_PLAYER_UNIT_SPELL_FINISH = T.onSpellFinish,
    EVENT_PLAYER_UNIT_TRAIN_START = T.onTrainStart,
    EVENT_PLAYER_UNIT_TRAIN_FINISH = T.onTrain,
    EVENT_PLAYER_UNIT_CONSTRUCT_FINISH = T.onConstructFinish,
    EVENT_PLAYER_UNIT_DEATH = T.onDeath,
    EVENT_PLAYER_UNIT_SUMMON = T.onSummon,
    EVENT_PLAYER_UNIT_ISSUED_ORDER = T.onOrder,
    EVENT_PLAYER_UNIT_ISSUED_POINT_ORDER = T.onPointOrder,
    EVENT_PLAYER_UNIT_ISSUED_TARGET_ORDER = T.onTargetOrder,
    EVENT_PLAYER_UNIT_DROP_ITEM = T.onDropItem,
    EVENT_PLAYER_UNIT_PAWN_ITEM = T.onPawnItem,
    EVENT_PLAYER_UNIT_PICKUP_ITEM = T.onPickUpItem,
    PRE_DAMAGE = T.onPreDamage,
    DAMAGE = T.onDamage,
    LETHAL_DAMAGE = T.onLethalDamage,
    AFTER_DAMAGE = T.afterDamage,
    TIMER = T.onTimer,
    ORDER = T.onAnyOrder,
    STUN = T.onStun,
    ROOT = T.onRoot,
    CREATE = T.onCreate,
    REVIVE = T.onCustomEvent,
    SOUL_USE = T.onCustomEvent,
}

return T]]

P['lib/triggers/filter.lua'] = [[---@class TriggerFilter
---@field source? integer|integer[]
---@field target? integer|integer[]
---@field isAttack? boolean
---@field isSpell? boolean

---@class TriggerDefinition
---@field trigger? string
---@field action fun(ctx?: any)
---@field spellId? integer|integer[]
---@field order? string
---@field delta? number
---@field priority? number
---@field filter? TriggerFilter
---@field _spellIds? table<integer, boolean>
---@field _sourceTypes? table<integer, boolean>
---@field _targetTypes? table<integer, boolean>
---@field _orderId? integer

local Filter = {}

local function assertFourCC(value, trigger, field)
    if type(value) == "string" then
        error(
            string.format(
                'trigger "%s" %s: expected FourCC id, got string %q — wrap with FourCC(...)',
                trigger,
                field,
                value
            )
        )
    end
    if type(value) ~= "number" then
        error(string.format('trigger "%s" %s: expected FourCC id (number), got %s', trigger, field, type(value)))
    end
    return value
end

local function toTypeSet(value, trigger, field)
    if value == nil then
        return nil
    end
    local set = {}
    if type(value) == "table" then
        for i, v in ipairs(value) do
            set[assertFourCC(v, trigger, field .. "[" .. i .. "]")] = true
        end
    else
        set[assertFourCC(value, trigger, field)] = true
    end
    return set
end

---@param set? table<integer, boolean>
---@param value? integer
local function inSet(set, value)
    return set == nil or set[value] == true
end

---@param expected? boolean
---@param actual? boolean
local function matchOptionalBool(expected, actual)
    if expected == nil then
        return true
    end
    return actual == expected
end

---@param trigger TriggerDefinition
---@param ctx { source?: unit, target?: unit, spellId?: integer, orderId?: integer, isAttack?: boolean, isSpell?: boolean }
function Filter.matches(trigger, ctx)
    ctx = ctx or {}
    if not inSet(trigger._spellIds, ctx.spellId) then
        return false
    end
    if trigger._orderId and ctx.orderId ~= trigger._orderId then
        return false
    end
    if not inSet(trigger._sourceTypes, ctx.source and GetUnitTypeId(ctx.source)) then
        return false
    end
    if not inSet(trigger._targetTypes, ctx.target and GetUnitTypeId(ctx.target)) then
        return false
    end
    local filter = trigger.filter
    if filter then
        if not matchOptionalBool(filter.isAttack, ctx.isAttack) then
            return false
        end
        if not matchOptionalBool(filter.isSpell, ctx.isSpell) then
            return false
        end
    end
    return true
end

---@param entry TriggerDefinition
function Filter.compileTrigger(entry)
    local triggerName = entry.trigger or "callback"
    local filter = entry.filter

    entry._spellIds = toTypeSet(entry.spellId, triggerName, "spellId")
    if entry.order then
        entry._orderId = String2OrderIdBJ(entry.order)
    end
    if filter then
        entry._sourceTypes = toTypeSet(filter.source, triggerName, "filter.source")
        entry._targetTypes = toTypeSet(filter.target, triggerName, "filter.target")
    end
end

---@param triggers TriggerDefinition[]
---@param ctx? { source?: unit, target?: unit, item?: item, spellId?: integer, orderId?: integer }
---@param passCtx? boolean
function Filter.run(triggers, ctx, passCtx)
    ctx = ctx or {}
    for _, trigger in ipairs(triggers) do
        if Filter.matches(trigger, ctx) then
            if passCtx then
                trigger.action(ctx)
            else
                trigger.action()
            end
        end
    end
end

return Filter]]

