P['scenario/common/mechanics/death.lua'] = [=[--[[
TODO:
- fire onDeath even on fake death ? most likely yes
- ! clean stale corpses data & hidden source units
- DOCS:
- - ADR for peon classification
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Slugs = require("lib.slugs")
local Units = require("lib.units")

local Storage = require("scenario.storage.death")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {},
        units = {},
        buffs = {
            exclude = Ids.buffs.forgeboneReveries,
        },
    },
    balance = {
        manacost = 5,
        radius = 500,
    },
})

local function shouldUseFakeDeath(target)
    if IsUnitType(target, UNIT_TYPE_STRUCTURE) or IsUnitType(target, UNIT_TYPE_SAPPER) then
        return false
    end

    local unitTypeId = GetUnitTypeId(target)
    if Slugs.unit(unitTypeId) then
        return Units.canRevive(unitTypeId)
    end

    for _, v in ipairs({ UNIT_TYPE_HERO, UNIT_TYPE_MECHANICAL }) do
        if IsUnitType(target, v) then
            return false
        end
    end

    return true
end

--- @param info damageInfo
local function onLethalDamage(info)
    local target = info.target

    if UnitHasBuffBJ(target, CONFIG.refs.buffs.exclude) then
        return
    end

    if not shouldUseFakeDeath(target) then
        return
    end

    local owner = GetOwningPlayer(target)
    local unitTypeId = GetUnitTypeId(target)
    local leavesCorpse = Slugs.unit(unitTypeId) and Units.leavesCorpse(unitTypeId) or true

    SetUnitInvulnerable(target, true)
    ShowUnitHide(target)
    SetUnitUseFood(target, false)
    SetUnitState(target, UNIT_STATE_LIFE, 1)
    Damage.life = 1
    info.damage = 0

    UnitRemoveBuffs(target, true, true)
    IssueImmediateOrder(target, "hold")
    SetUnitOwner(target, Player(PLAYER_NEUTRAL_PASSIVE), false)

    local isPeon = IsUnitType(target, UNIT_TYPE_PEON)
    if not isPeon then
        UnitAddType(target, UNIT_TYPE_PEON)
    end

    local storageUnit = target
    if leavesCorpse then
        storageUnit = CreateUnit(owner, unitTypeId, GetUnitX(target), GetUnitY(target), GetUnitFacing(target))
        KillUnit(storageUnit) -- CAUTION: onDeath triggers
    end

    Storage:set(storageUnit, "soulAvailable", true)
    Storage:set(storageUnit, "originalOwner", GetPlayerId(owner))
    Storage:set(storageUnit, "unit", target)
    Storage:set(storageUnit, "isPeon", isPeon)
    Storage:set(storageUnit, "reviveAfter", GetUnitState(target, UNIT_STATE_MAX_LIFE) // 500)
end

return {
    triggers = {
        {
            trigger = "LETHAL_DAMAGE",
            priority = -1000,
            action = onLethalDamage,
        },
    },
    export = {
        shouldUseFakeDeath = shouldUseFakeDeath,
    },
    config = CONFIG,
}]=]

P['scenario/common/mechanics/dispellMeter.lua'] = [[local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {},
        units = {
            dummy = Ids.units.dummyDispellMeter,
        },
    },
    balance = {
        radius = 600, -- TODO: connect with data. attributes
    },
})

--- @alias dispellMetricsCategory {mp: integer|nil, hp: integer|nil}
--- @alias dispellMeterResult {buff: integer|nil, unit: integer|nil}

--- Dummy abil must heritage Obsidian Destroyer's "Devour Magic", cost 0 mana
--- @param owner player
--- @param order {ability: integer, level: integer|nil, target: unit|Point}
--- @param per {buff: dispellMetricsCategory, unit: dispellMetricsCategory}
--- @param resultCallback function
local function dispellCount(owner, order, per, resultCallback)
    local dummy = Dummy.create(owner, order.target, order.ability, order.level, CONFIG.refs.units.dummy)
    Unit.applyTimedLife(dummy, 10)
    local manaBefore = Unit.getCurrentMana(dummy)
    local x, y = Generic.pointXY(order.target)
    Dummy.issuePoint(dummy, "devourmagic", x, y) -- TODO: check order string
    Timed.call(0.1, function()
        local manaAfter = Unit.getCurrentMana(dummy)
        local manaD = manaAfter - manaBefore
        --- @type dispellMeterResult
        local result = {}
        if per.buff and per.buff.mp then
            result.buff = manaD // per.buff.mp
        end
        if per.unit and per.unit.mp then
            result.unit = manaD // per.unit.mp
        end
        -- RemoveUnit(dummy)
        resultCallback(result)
    end)
end

return {
    triggers = {},
    api = {
        count = dispellCount,
    },
}]]

