]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")

local CONFIG = AbilityConfig.compile({
    refs = {
        buffs = {
            main = Ids.buffs.spiritLink, -- CHANGE slug
        },
    },
    balance = {
        damageReduceAmount = 6,
        minDamage = 3,
    },
})

local function onPreDamage(info)
