]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.counterattackCall")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.counterattackCall,
            dummy = Ids.abilities.counterattackCallDummy,
            bonus = Ids.abilities.counterattackCallBonus,
        },
        buffs = {
            main = Ids.buffs.counterattackCall,
        },
    },
    balance = {
        radius = 500,
        tick = 0.03,
    },
})

local function onSpell()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local level = GetUnitAbilityLevel(caster, CONFIG.refs.abilities.main)

    local targets = Unit.getAllyUnitsInRadius(caster, CONFIG.balance.radius, function(u)
        return IsUnitAliveBJ(u)
    end)

    for _, target in ipairs(targets) do
        Dummy.applyDummyOrder(owner, target, CONFIG.refs.abilities.dummy, "innerfire", level)
    end
end

local function onDummySpell()
    local target = GetSpellTargetUnit()
    Storage:add(target)
    local level = GetUnitAbilityLevel(target, CONFIG.refs.abilities.bonus)
    if level then
        UnitAddAbility(target, CONFIG.refs.abilities.bonus)
        SetUnitAbilityLevel(target, CONFIG.refs.abilities.bonus, level)
    end
end

local function onDamage(info)
    if not Storage:has(info.source) then
        return
    end
    if UnitHasBuffBJ(info.source, CONFIG.refs.buffs.main) then
        info.damage = info.damage + 20
    end
end

local function onTimer()
    -- optional: modify damage when debuff present
    -- iterate storage
    -- if buff faded - remove bonus damage ability
    Storage:each(function(u)
        if not UnitHasBuffBJ(u, CONFIG.refs.buffs.main) then
            UnitRemoveAbility(u, CONFIG.refs.abilities.bonus)
            Storage:drop(u)
        end
    end)
end

local function onDeath()
    local unit = GetDyingUnit()
    if not Storage:has(unit) then
        return
    end
    Storage:drop(unit)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.dummy,
            action = onDummySpell,
        },
        {
            trigger = "DAMAGE",
            filter = { source = CONFIG.refs.units.source },
            action = onDamage,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.tick,
            action = onTimer,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DEATH",
            action = onDeath,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/kyrian/abilities/dedication.lua'] = [[-- TODO
-- - test dispell removes both buffs
local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Type = require("utils.type")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.dedication")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.dedication,
            damageBuff = Ids.abilities.dedicationDamageBuff,
            attackSpeed = Ids.abilities.dedicationAttackSpeedBuff,
        },
        buffs = {
            main = Ids.buffs.dedication,
        },
    },
})

local function removeDedicationEffect(unit)
    UnitRemoveBuffBJ(CONFIG.refs.buffs.main, unit)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.attackSpeed)
    Storage:drop(unit)
end

local function onDedicationCast()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()

    Dummy.applyDummyOrder(GetOwningPlayer(caster), target, CONFIG.refs.abilities.damageBuff, "innerfire")
end

local function onDummyCast()
    local unit = GetSpellTargetUnit()

    UnitAddAbility(unit, CONFIG.refs.abilities.attackSpeed)

    Storage:set(unit, "target", nil)
end

local function onAttack()
    local unit = GetAttacker()
    local target = GetTriggerUnit()

    if not Storage:has(unit) then
        return
    elseif Storage:get(unit, "target") == nil then
        Storage:set(unit, "target", target)
    elseif target ~= Storage:get(unit, "target") then
        removeDedicationEffect(unit)
    end
end

local function onFrame()
    Storage:each(function(unit)
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            removeDedicationEffect(unit)
        end
    end)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onDedicationCast,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.damageBuff,
            action = onDummyCast,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_ATTACKED",
            action = onAttack,
        },
        {
            trigger = "TIMER",
            delta = 0.03,
            action = onFrame,
        },
    },
    config = CONFIG,
}]]

P['scenario/factions/kyrian/abilities/deepMeditation.lua'] = [[-- TODO:
-- - percentage regen
-- - make stun instant
local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local GetElapsedGameTime = require("scenario.common.timer")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.deepMeditation")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.deepMeditation,
            stunDummy = Ids.abilities.deepMeditationStunDummy,
            rejuvDummy = Ids.abilities.deepMeditationRejuvDummy,
        },
        buffs = {
            main = Ids.buffs.deepMeditation,
            stun = Ids.buffs.deepMeditationStun,
        },
    },
    balance = {
        duration = 8,
        damageThreshold = 50,
    },
})

local function removeEffects(target)
    UnitRemoveBuffBJ(CONFIG.refs.buffs.main, target)
    UnitRemoveBuffBJ(CONFIG.refs.buffs.stun, target)
    Storage:drop(target)
end

local function onCast()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local target = GetSpellTargetUnit()

    if Unit.isManaFull(target) then
        return
    end

    Dummy.applyDummyOrder(owner, target, CONFIG.refs.abilities.stunDummy, "thunderbolt")
    Dummy.applyDummyOrder(owner, target, CONFIG.refs.abilities.rejuvDummy, "rejuvination")
end

local function onDummyCast()
    local target = GetSpellTargetUnit()

    Storage:set(target, "damageReceived", 0)
end

local function onDamage(info)
    if not Storage:has(info.target) then
        return
    end

    local damageReceived = Storage:get(info.target, "damageReceived") + info.damage
    Storage:set(info.target, "damageReceived", damageReceived)

    if damageReceived > CONFIG.balance.damageThreshold then
        removeEffects(info.target)
    end
end

local function onTimer()
    Storage:each(function(target)
        dump("onTimer deepMeditation forEach", UnitHasBuffBJ(target, CONFIG.refs.buffs.main), Unit.isManaFull(target))
        if not UnitHasBuffBJ(target, CONFIG.refs.buffs.main) then
            removeEffects(target)
            return
        end

        if Unit.isManaFull(target) then
            removeEffects(target)
            return
        end
    end)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onCast,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.stunDummy,
            action = onDummyCast,
        },
        {
            trigger = "DAMAGE",
            action = onDamage,
        },
        {
            trigger = "TIMER",
            delta = 0.03,
            action = onTimer,
        },
    },
    config = CONFIG,
}]]

P['scenario/factions/kyrian/abilities/defenceProtocol.lua'] = [[local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local MechStorage = require("scenario.storage.mech")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.defenceProtocol,
            toggle = Ids.abilities.defenceProtocolToggle,
            buff = Ids.abilities.defenceProtocolBuff,
        },
        buffs = {
            main = Ids.buffs.defenceProtocol,
        },
        units = {
            carrier = Ids.units.praetor,
            protected = { Ids.units.steward, Ids.units.aspirant },
        },
    },
    balance = {
        radius = 600,
        cooldown = 5,
        manacost = 20,
    },
})

local function activateDefenceProtocol(event, unit)
    if IsUnitAlly(event.target, GetOwningPlayer(event.source)) then
        return
    end
    if not MechStorage:has(unit) then
        return
    end
    if not Unit.isOffCooldown(unit, CONFIG.refs.abilities.main) then
        return
    end
    local mana = GetUnitState(unit, UNIT_STATE_MANA)
    if mana < CONFIG.balance.manacost then
        return
    end
    BlzStartUnitAbilityCooldown(unit, CONFIG.refs.abilities.main, CONFIG.balance.cooldown)
    Dummy.applyDummyOrder(GetOwningPlayer(unit), unit, CONFIG.refs.abilities.buff, "bloodlust")
    SetUnitState(unit, UNIT_STATE_MANA, mana - CONFIG.balance.manacost)
end

local function onTurnOn()
    local unit = GetTriggerUnit()
    local mana = GetUnitState(unit, UNIT_STATE_MANA)
    SetUnitState(unit, UNIT_STATE_MANA, mana + CONFIG.balance.manacost)
    -- dump("onTurnOn defenceProtocol", mana, mana + CONFIG.balance.manacost)
    MechStorage:set(unit, "active", true)
end

local function onTurnOff()
    local unit = GetTriggerUnit()
    MechStorage:drop(unit)
end

local function onDeath()
    MechStorage:drop(GetDyingUnit())
end

local function onDamageEvent(info)
    local nearbyPraetors =
        Unit.getAllyUnitsOfTypeInRadius(info.target, CONFIG.refs.units.carrier, CONFIG.balance.radius)
    for _, unit in ipairs(nearbyPraetors) do
        activateDefenceProtocol(info, unit)
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.toggle,
            action = onTurnOn,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_ISSUED_ORDER",
            order = "unimmolation",
            action = onTurnOff,
        },
        {
            trigger = "DAMAGE",
            filter = { target = CONFIG.refs.units.protected },
            action = onDamageEvent,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DEATH",
            filter = { target = CONFIG.refs.units.carrier },
            action = onDeath,
        },
    },
    config = CONFIG,
}]]

P['scenario/factions/kyrian/abilities/formation.lua'] = [[-- todo: handle revive, etc.
