P['scenario/factions/kyrian/abilities/lastStand.lua'] = [[-- TODO
-- - hard cancelled like starfall (doesn't cancel on move)
-- - make aura apply instantly
local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.lastStand")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.lastStand,
            aura = Ids.abilities.lastStandAura,
            heal = Ids.abilities.lastStandHealDummy,
        },
        buffs = {
            main = Ids.buffs.lastStand,
        },
    },
    balance = {
        radius = 600,
        healOrder = 852273, -- TODO: find order id dumping it with listener event
    },
})

local function onChannelStart()
    local caster = GetTriggerUnit()
    UnitAddAbility(caster, CONFIG.refs.abilities.aura)
end

local function onChannelEnd()
    local caster = GetTriggerUnit()
    UnitRemoveAbility(caster, CONFIG.refs.abilities.aura)
    local dummy = Dummy.create(
        GetOwningPlayer(caster),
        caster,
        CONFIG.refs.abilities.heal,
        GetUnitAbilityLevel(caster, CONFIG.refs.abilities.main)
    )
    IssueImmediateOrderById(dummy, CONFIG.balance.healOrder)
    Storage:set(dummy, "caster", caster)
end

local function onHeal()
    local dummy = GetTriggerUnit()
    local caster = Storage:get(dummy, "caster")
    UnitRemoveAbility(caster, CONFIG.refs.abilities.aura)
    Storage:drop(dummy)
    for _, target in ipairs(Unit.getAllyUnitsInRadius(caster, CONFIG.balance.radius)) do
        UnitRemoveBuffBJ(CONFIG.refs.buffs.main, target)
    end
end

local function onDamage(info)
    if not UnitHasBuffBJ(info.target, CONFIG.refs.buffs.main) then
        return
    end
    local life = GetUnitState(info.target, UNIT_STATE_LIFE)
    if life - info.damage < 1 then
        info.damage = math.max(0, life - 1)
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onChannelStart,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_ENDCAST",
            spellId = CONFIG.refs.abilities.main,
            action = onChannelEnd,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.heal,
            action = onHeal,
        },
        {
            trigger = "DAMAGE",
            action = onDamage,
        },
    },
    config = CONFIG,
    debug = {
        onDamage = onDamage,
    },
}]]

P['scenario/factions/kyrian/abilities/memoryPeer.lua'] = [[-- TODO
-- - review storage
-- - ? onTargetDeath - dummy AA slow to X nearby enemies; remove spirits
-- - refactor dummy immediate order
-- - test 2+ ability level

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.memoryPeer")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.memoryPeer,
            summon = Ids.abilities.memoryPeerSummon,
            slow = Ids.abilities.memoryPeerSlow,
        },
        buffs = {
            main = Ids.buffs.memoryPeer,
        },
        units = {
            spirit = Ids.units.memorySpirit,
            dummyAttack = Ids.units.dummyAttack,
        },
    },
})

local isOrdering = false

local function orderAttack(spirit)
    local target = Storage:get(spirit, "unit")
    if not target or not Unit.isAlive(target) then
        return
    end
    isOrdering = true
    IssueTargetOrder(spirit, "attack", target)
    isOrdering = false
end

local function onSpell()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    if not target then
        return
    end

    local owner = GetOwningPlayer(caster)
    local level = GetUnitAbilityLevel(caster, CONFIG.refs.abilities.main)
    Dummy.applyDummyAttack(owner, target, CONFIG.refs.abilities.slow, level)

    local dummy = Dummy.create(owner, target, CONFIG.refs.abilities.summon, level)
    Storage:set(dummy, "unit", target)
    IssueImmediateOrder(dummy, "spiritwolf")
end

local function onSummoned()
    local spirit = GetSummonedUnit()
    local target = Storage:get(GetSummoningUnit(), "unit")
    if not target then
        return
    end
    Storage:set(spirit, "unit", target)
    Storage:set(target, "summonsLeast", Storage:get(target, "summonsLeast") + 1)
    orderAttack(spirit)
end

local function onOrder()
    if isOrdering then
        return
    end
    local unit = GetTriggerUnit()
    if GetUnitTypeId(unit) ~= AbilityConfig.unitId(CONFIG.refs.units.spirit) then
        return
    end
    if not Storage:has(unit) then
        return
    end
    orderAttack(unit)
end

local function onDeath()
    local spirit = GetDyingUnit()
    local target = Storage:get(spirit, "unit")
    Storage:drop(spirit)
    if not target then
        return
    end
    local left = Storage:get(target, "summonsLeast") - 1
    Storage:set(target, "summonsLeast", left)
    if left <= 0 then
        UnitRemoveBuffBJ(CONFIG.refs.buffs.main, target)
        Storage:drop(target)
    end
end

local function afterDummyAttack(info)
    if GetUnitAbilityLevel(info.source, CONFIG.refs.abilities.slow) > 0 then
        RemoveUnit(info.source)
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SUMMON",
            filter = { target = CONFIG.refs.units.spirit },
            action = onSummoned,
        },
        {
            trigger = "ORDER",
            action = onOrder,
        },
        {
            trigger = "DAMAGE",
            filter = { source = CONFIG.refs.units.dummyAttack },
            action = afterDummyAttack,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DEATH",
            filter = { target = CONFIG.refs.units.spirit },
            action = onDeath,
        },
    },
    config = CONFIG,
}]]

P['scenario/factions/kyrian/abilities/oneMoreChance.lua'] = [[-- TODO:
-- - check dispell

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local GetElapsedGameTime = require("scenario.common.timer")
local Dummy = require("utils.dummy")
local Type = require("utils.type")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.oneMoreChance")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.oneMoreChance,
            buffDummy = Ids.abilities.oneMoreChanceBuffDummy,
            cross = Ids.abilities.oneMoreChanceCross,
            reincarnationCheck = Ids.abilities.reincarnationCheck,
            healDummy = Ids.abilities.oneMoreChanceHealDummy,
        },
        buffs = {
            main = Ids.buffs.oneMoreChance,
        },
    },
    balance = {
        duration = 5, -- real duration + delta
    },
})

local function removeEffect(unit)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.cross)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.reincarnationCheck)
    UnitRemoveBuffBJ(CONFIG.refs.buffs.main, unit)
end

local function onSpell()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    Dummy.applyDummyOrder(
        GetOwningPlayer(caster),
        target,
        CONFIG.refs.abilities.buffDummy,
        "innerfire",
        GetUnitAbilityLevel(caster, CONFIG.refs.abilities.buffDummy)
    )
end

local function onDummyBuff()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    Storage:set(target, "abilityLevel", GetUnitAbilityLevel(caster, CONFIG.refs.abilities.buffDummy))
    Storage:set(target, "buffedAt", GetElapsedGameTime())
    UnitAddAbility(target, CONFIG.refs.abilities.cross)
    UnitAddAbility(target, CONFIG.refs.abilities.reincarnationCheck)
end

local function onDummyHeal()
    local target = GetSpellTargetUnit()
    Storage:drop(target)
end

local function onReincarnate()
    local unit = GetOrderedUnit()
    if not GetUnitAbilityLevel(unit, CONFIG.refs.abilities.cross) then
        return
    end
    if GetUnitState(unit, UNIT_STATE_LIFE) >= 0.01 then
        return
    end
    if Storage:has(unit) then
        removeEffect(unit)
        Storage:drop(unit)
    end
end

local function onTimer()
    Storage:each(function(unit)
        if Storage:get(unit, "expired") then
            return
        end
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            removeEffect(unit)
            Storage:drop(unit)
            return
        end
        local expireTime = Storage:get(unit, "buffedAt") + (CONFIG.balance.duration - 0.1)
        if expireTime <= GetElapsedGameTime() then
            removeEffect(unit)
            Dummy.applyDummyOrder(
                GetOwningPlayer(unit),
                unit,
                CONFIG.refs.abilities.healDummy,
                "holybolt",
                Storage:get(unit, "abilityLevel")
            )
            Storage:set(unit, "expired", true)
        end
    end)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.buffDummy,
            action = onDummyBuff,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.healDummy,
            action = onDummyHeal,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_ISSUED_ORDER",
            order = "undefend", -- https://www.hiveworkshop.com/threads/reincarnation-summon.370049/
            action = onReincarnate,
        },
        {
            trigger = "TIMER",
            delta = 0.03,
            action = onTimer,
        },
    },
    config = CONFIG,
}]]

