P['scenario/factions/kyrian/abilities/pride.lua'] = [[-- todo: handle revive, etc.
local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Unit = require("utils.unit")

local PrideStore = require("scenario.storage.pride")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.pride,
            damage = Ids.abilities.prideDamage,
        },
        units = {
            dummy = Ids.units.dummy,
            carrier = Ids.units.larion,
        },
    },
    balance = {
        radius = 600,
        tickSeconds = 1,
        maxStacks = 5,
        adPerStack = 4,
    },
})

local function isCountable(host, other)
    if other == host then
        return false
    end
    if not Unit.isAlive(other) then
        return false
    end
    if GetUnitTypeId(other) == AbilityConfig.unitId(CONFIG.refs.units.dummy) then
        return false
    end
    if IsUnitType(other, UNIT_TYPE_STRUCTURE) then
        return false
    end
    return true
end

--- raw стаки: может быть < 0; кап 5 не здесь
local function countStacks(unit)
    local selfHp = BlzGetUnitMaxHP(unit)
    local raw = 0
    for _, other in ipairs(Unit.getUnitsInRadius(unit, CONFIG.balance.radius)) do
        if isCountable(unit, other) then
            if BlzGetUnitMaxHP(other) < selfHp then
                raw = raw + 1
            else
                raw = raw - 1
            end
        end
    end
    return raw
end

local function effectiveStacks(raw)
    if raw <= 0 then
        return 0
    end
    if raw > CONFIG.balance.maxStacks then
        return CONFIG.balance.maxStacks
    end
    return raw
end

local function applyPride(unit)
    local stacks = effectiveStacks(countStacks(unit))
    UnitRemoveAbility(unit, CONFIG.refs.abilities.damage)
    if stacks > 0 then
        UnitAddAbility(unit, CONFIG.refs.abilities.damage)
        SetUnitAbilityLevel(unit, CONFIG.refs.abilities.damage, stacks)
    end
end

local function onTick()
    PrideStore:each(function(unit)
        if Unit.isAlive(unit) then
            applyPride(unit)
        end
    end)
end

local function onTrain(unit)
    if unit == nil then
        unit = GetTrainedUnit()
    end
    PrideStore:add(unit)
end

local function onDeath(unit)
    if unit == nil then
        unit = GetDyingUnit()
    end
    PrideStore:drop(unit)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_TRAIN_FINISH",
            filter = { target = CONFIG.refs.units.carrier },
            action = onTrain,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DEATH",
            filter = { target = CONFIG.refs.units.carrier },
            action = onDeath,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.tickSeconds,
            action = onTick,
        },
    },
    config = CONFIG,
    countStacks = countStacks,
    effectiveStacks = effectiveStacks,
    debug = {
        onTrain = onTrain,
        onDeath = onDeath,
        applyPride = applyPride,
    },
}]]

P['scenario/factions/kyrian/abilities/pulseback.lua'] = [[-- TODO:
-- - ignore dummy attacks
local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local MechStorage = require("scenario.storage.mech")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.pulseback,
            toggle = Ids.abilities.pulsebackToggle,
            pulse = Ids.abilities.pulsebackPulse,
        },
        units = {
            carrier = Ids.units.goliath,
        },
    },
    balance = {
        cooldown = 3,
        chance = 25,
        toggleManacost = 20,
        pulseManacost = 20,
        pulseDamage = 50,
        pulseRadius = 250,
    },
})

local function applyPulsebackPulse(unit)
    local owner = GetOwningPlayer(unit)

    for _, target in ipairs(Unit.getUnitsInRadius(unit, CONFIG.balance.pulseRadius)) do
        if not IsUnitAlly(target, owner) then
            UnitDamageTarget(
                unit,
                target,
                CONFIG.balance.pulseDamage,
                false,
                false,
                ATTACK_TYPE_MAGIC,
                DAMAGE_TYPE_UNIVERSAL,
                WEAPON_TYPE_WHOKNOWS
            )
        end
    end

    Dummy.applyDummyPointOrder(owner, unit, CONFIG.refs.abilities.pulse, "blizzard")
end

local function tryActivatePulseback(info)
    local unit = info.target
    if IsUnitAlly(info.source, GetOwningPlayer(unit)) then
        return
    end
    if not MechStorage:has(unit) then
        return
    end
    if not Unit.isOffCooldown(unit, CONFIG.refs.abilities.main) then
        return
    end
    if GetRandomReal(0, 100) >= CONFIG.balance.chance then
        return
    end
    local mana = GetUnitState(unit, UNIT_STATE_MANA)
    if mana < CONFIG.balance.pulseManacost then
        return
    end
    BlzStartUnitAbilityCooldown(unit, CONFIG.refs.abilities.main, CONFIG.balance.cooldown)
    applyPulsebackPulse(unit)
    SetUnitState(unit, UNIT_STATE_MANA, mana - CONFIG.balance.pulseManacost)
end

local function onTurnOn()
    local unit = GetTriggerUnit()
    local mana = GetUnitState(unit, UNIT_STATE_MANA)
    SetUnitState(unit, UNIT_STATE_MANA, mana + CONFIG.balance.toggleManacost)
    MechStorage:set(unit, "active", true)
end

local function onTurnOff()
    MechStorage:drop(GetTriggerUnit())
end

local function onTrain()
    local unit = GetTrainedUnit()
    MechStorage:set(unit, "active", true)
    IssueImmediateOrder(unit, "immolation")
end

local function onDeath()
    MechStorage:drop(GetDyingUnit())
end

local function onDamage(info)
    tryActivatePulseback(info)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.toggle,
            action = onTurnOn,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_ISSUED_ORDER",
            order = "unimmolation",
            action = onTurnOff,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_TRAIN_FINISH",
            filter = { target = CONFIG.refs.units.carrier },
            action = onTrain,
        },
        {
            trigger = "DAMAGE",
            filter = { target = CONFIG.refs.units.carrier },
            action = onDamage,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DEATH",
            filter = { target = CONFIG.refs.units.carrier },
            action = onDeath,
        },
    },
    config = CONFIG,
}]]

P['scenario/factions/kyrian/abilities/reusables.lua'] = [[local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.reusables,
        },
    },
    balance = {
        manaPercent = { 0.33, 0.66, 1.0 },
        costPercent = { 0.25, 0.5, 0.75 },
    },
})

local function getHealthPercent(unit)
    local maxLife = GetUnitState(unit, UNIT_STATE_MAX_LIFE)
    if maxLife <= 0 then
        return 0
    end
    return GetUnitState(unit, UNIT_STATE_LIFE) / maxLife
end

local function isValidTarget(caster, target)
    if not target or target == caster then
        return false
    end
    if not Unit.isAlive(target) then
        return false
    end
    if not IsUnitAlly(target, GetOwningPlayer(caster)) then
        return false
    end
    if not Unit.isMech(target) then
        return false
    end
    if IsUnitType(target, UNIT_TYPE_HERO) then
        return false
    end
    return true
end

local function onCast()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()

    if not isValidTarget(caster, target) then
        return
    end

    local level = GetUnitAbilityLevel(caster, CONFIG.refs.abilities.main)
    local manaPercent = CONFIG.balance.manaPercent[level]
    local costPercent = CONFIG.balance.costPercent[level]
    local healthPercent = getHealthPercent(target)

    local targetMana = GetUnitState(target, UNIT_STATE_MANA)
    local unitTypeId = GetUnitTypeId(target)
    local goldCost = GetUnitGoldCost(unitTypeId)
    local woodCost = GetUnitWoodCost(unitTypeId)
    local owner = GetOwningPlayer(caster)

    KillUnit(target)

    local manaGain = targetMana * manaPercent
    local currentMana = GetUnitState(caster, UNIT_STATE_MANA)
    local maxMana = GetUnitState(caster, UNIT_STATE_MAX_MANA)
    SetUnitState(caster, UNIT_STATE_MANA, math.min(currentMana + manaGain, maxMana))

    AdjustPlayerStateBJ(
        math.floor(goldCost * costPercent * healthPercent),
        owner,
        PLAYER_STATE_RESOURCE_GOLD
    )
    AdjustPlayerStateBJ(
        math.floor(woodCost * costPercent * healthPercent),
        owner,
        PLAYER_STATE_RESOURCE_LUMBER
    )
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_CAST",
            spellId = CONFIG.refs.abilities.main,
            action = onCast,
        },
    },
    config = CONFIG,
}]]

P['scenario/factions/kyrian/abilities/scan.lua'] = [[-- TODO:
-- - [BUG] onDeath nil error
-- - handle stale pending targets
-- - adjust scan radius to current vision radius (can be affected by Fae debuff)
local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local MechStorage = require("scenario.storage.mech")
local PhalynxStorage = require("scenario.storage.phalynx")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            toggle = Ids.abilities.scanToggle,
            trueSight = Ids.abilities.trueSight,
            revealArea = Ids.abilities.scanRevealArea,
            reveal = Ids.abilities.scanReveal,
            speedBuff = Ids.abilities.scanBuffSpeed,
            damageBuff = Ids.abilities.scanBuffDamage,
        },
        buffs = {
            reveal = Ids.buffs.scanReveal,
            speed = Ids.buffs.scanBuffSpeed,
            damage = Ids.buffs.scanBuffDamage,
        },
        units = {
            carrier = Ids.units.phalynx,
        },
    },
    balance = {
        toggleManacost = 10,
        scanRadius = 600,
    },
})

local pendingReveal = {} -- target: unit, processed, queuedAt

local function onTurnOn()
    local unit = GetTriggerUnit()
    local mana = GetUnitState(unit, UNIT_STATE_MANA)
    SetUnitState(unit, UNIT_STATE_MANA, mana + CONFIG.balance.toggleManacost)
    UnitAddAbility(unit, CONFIG.refs.abilities.trueSight)
    MechStorage:set(unit, "active", true)
end

local function onTurnOff()
    local unit = GetTriggerUnit()
    UnitRemoveAbility(unit, CONFIG.refs.abilities.trueSight)
    MechStorage:drop(GetTriggerUnit())
end

local function onDeath()
    MechStorage:drop(GetDyingUnit())
    PhalynxStorage:drop(GetDyingUnit())
end

local function afterDamage(info)
    if UnitHasBuffBJ(info.source, CONFIG.refs.buffs.speed) then
        UnitRemoveBuffBJ(CONFIG.refs.buffs.speed, info.source)
    end
    if UnitHasBuffBJ(info.source, CONFIG.refs.buffs.damage) then
        UnitRemoveBuffBJ(CONFIG.refs.buffs.damage, info.source)
    end
end

local function onReveal()
    local target = GetSpellTargetUnit()
    pendingReveal[target] = nil
end

local function onTimerScan()
    PhalynxStorage:each(function(unit)
        local owner = GetOwningPlayer(unit)
        if not MechStorage:has(unit) then
            return
        end
        for _, u in
            ipairs(Unit.getUnitsInRadius(unit, CONFIG.balance.scanRadius, function(t)
                return (
                    not pendingReveal[t]
                    and not IsUnitAlly(t, owner)
                    and Unit.hasInvisibilityBuff(t)
                    and not UnitHasBuffBJ(t, CONFIG.refs.buffs.reveal)
                )
            end))
        do
            pendingReveal[u] = { unit = unit, ordered = false }
        end
    end)
end

local function onTimerReveal()
    for target, data in pairs(pendingReveal) do
        if data.processed then
            goto continue
        end

        pendingReveal[target].processed = true

        local unit = data.unit
        local owner = GetOwningPlayer(unit)
        Dummy.applyDummyOrder(owner, target, CONFIG.refs.abilities.reveal, "faeriefire")
        Dummy.applyDummyOrder(owner, unit, CONFIG.refs.abilities.speedBuff, "bloodlust")
        Dummy.applyDummyOrder(owner, unit, CONFIG.refs.abilities.damageBuff, "innerfire")

        ::continue::
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.toggle,
            action = onTurnOn,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.reveal,
            action = onReveal,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_ISSUED_ORDER",
            order = "unimmolation",
            action = onTurnOff,
        },
        {
            trigger = "AFTER_DAMAGE",
            filter = { source = CONFIG.refs.units.carrier },
            action = afterDamage,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DEATH",
            filter = { target = CONFIG.refs.units.carrier },
            action = onDeath,
        },
        {
            trigger = "TIMER",
            delta = 0.5,
            action = onTimerScan,
        },
        {
            trigger = "TIMER",
            delta = 0.03,
            action = onTimerReveal,
        },
    },
    config = CONFIG,
}]]

P['scenario/factions/kyrian/abilities/soulbind.lua'] = [[-- TODO:
-- - CHECK: soulbind charge + bond level & buff constistency on morphing
-- - BUG: soulbind abil charge reappears after morph
-- - BUG: dispellability. Try replacing dummy buff with item abilities (3 separate abilities instead of leveled one or so)
--
-- - [1] - check save-load
-- - check upgrades (GetPlayerTechCount, GetOwningPlayer)
-- - - probably update on trigger and store instead of polling each soulbind tick
-- - object editor (upgrades, soulbind buffs, duration, soulbind ability properties)
-- - invisible soulbind charge for Larion (can be targeted, can't cast)
-- - hashtables (save-load persistance)
-- - refactor (group bond methods)
-- QUESTIONS:
-- - prevent bond progress when next level upgrade is not done
-- - autocheck object ability levels VS script ability levels

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Type = require("utils.type")
local Unit = require("utils.unit")

local SoulbindStorage = require("scenario.storage.soulbind")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.soulbind,
            buff = Ids.abilities.soulbindBuff,
        },
        buffs = {
            main = Ids.buffs.soulbind,
        },
        units = {
            dummy = Ids.units.dummy,
            carriers = { Ids.units.aspirant, Ids.units.larion },
        },
    },
    balance = {
        radius = 600,
        tickSeconds = 1,
        secondsForLevel = 5,
        maxLevel = 3,
        levels = {
            [1] = { requiredUpgradeId = nil },
            [2] = { requiredUpgradeId = nil },
            [3] = { requiredUpgradeId = nil },
        },
    },
})

local carrierTypeSet = Type.toSet(CONFIG.refs.units.carriers)

local function hasCharge(unit)
    return GetUnitAbilityLevel(unit, CONFIG.refs.abilities.main) > 0
end

local function consumeCharge(caster, target)
    local r1 = UnitRemoveAbility(caster, CONFIG.refs.abilities.main)
    local r2 = UnitRemoveAbility(target, CONFIG.refs.abilities.main)
    return r1 and r2
end

local function isSoulbindCarrier(unit)
    local t = GetUnitTypeId(unit)
    return Type.toBool(carrierTypeSet[t])
end

local function isValidTarget(caster, target)
    if not Unit.isAlive(caster) or not Unit.isAlive(target) then
        return false
    end
    if caster == target then
        return false
    end
    if SoulbindStorage:find(caster) or SoulbindStorage:find(target) then
        return false
    end
    if not isSoulbindCarrier(target) then
        return false
    end
    if not hasCharge(caster) or not hasCharge(target) then
        return false
    end
    return true
end

local function removeSoulbindBuff(unit)
    UnitRemoveBuffBJ(CONFIG.refs.buffs.main, unit)
end

local function applySoulbindBuff(unit, level)
    local dummy = CreateUnit(
        GetOwningPlayer(unit),
        AbilityConfig.unitId(CONFIG.refs.units.dummy),
        GetUnitX(unit),
        GetUnitY(unit),
        270
    )
    local abilityId = CONFIG.refs.abilities.buff
    UnitApplyTimedLife(dummy, FourCC("BTLF"), 10.00)
    UnitAddAbility(dummy, abilityId)
    SetUnitAbilityLevel(dummy, abilityId, level)
    IssueTargetOrder(dummy, "innerfire", unit)
end

local function onSoulbindCast()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()

    if not isValidTarget(caster, target) then
        return false
    end

    if not SoulbindStorage:create(SoulbindStorage:alloc(), { unit_a = caster, unit_b = target }) then
        error("Can't create soulbind")
    end
    consumeCharge(caster, target)
end

local function tickBond(bondId)
    local bond = SoulbindStorage:bind(bondId)
    if not bond then
        return
    end

    local u1, u2 = bond.unit_a, bond.unit_b
    if not Unit.isAlive(u1) or not Unit.isAlive(u2) then
        SoulbindStorage:drop(bondId)
        return
    end

    local inRange = Unit.distance(u1, u2) <= CONFIG.balance.radius
    if not inRange then
        if bond.active then
            bond.active = false
            removeSoulbindBuff(u1)
            removeSoulbindBuff(u2)
        end
        return
    end

    local leveledUp
    if bond.level < CONFIG.balance.maxLevel then
        local progressDelta = (CONFIG.balance.tickSeconds / CONFIG.balance.secondsForLevel)
        bond.progress = math.min(bond.progress + progressDelta, 1)
        if bond.progress >= 1 and bond.level < CONFIG.balance.maxLevel then
            bond.progress = 0
            bond.level = bond.level + 1
            leveledUp = true
        else
            leveledUp = false
        end
    end
    if not bond.active or leveledUp then
        bond.active = true
        applySoulbindBuff(u1, bond.level)
        applySoulbindBuff(u2, bond.level)
    end
end

local function updateSoulbindStatus()
    SoulbindStorage:each(tickBond)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSoulbindCast,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.tickSeconds,
            action = updateSoulbindStatus,
        },
    },
    config = CONFIG,
    tickBond = tickBond,
}]]

P['scenario/factions/kyrian/abilities/spiritLink.lua'] = [[local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Type = require("utils.type")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        buffs = {
            main = Ids.buffs.spiritLink,
        },
    },
