            main = Ids.buffs.disarm,
        },
        units = {
            carrier = { Ids.units.shackler, Ids.units.vanguard },
        },
    },
    balance = {
        radius = 100,
    },
})

--- @type unit[]
local memory = {} -- TODO: save/load

--- @param info damageInfo
local function onAfterDamage(info)
    if not info.isAttack then
        return
    end
    local owner = GetOwningPlayer(info.source)

    Timed.call(0.00, function()
        dump("disarm onAfterDamage timer")
        if UnitHasBuffBJ(info.target, CONFIG.refs.buffs.init) then
            dump("disarm onAfterDamage UnitRemoveBuffBJ")
            UnitRemoveBuffBJ(CONFIG.refs.buffs.init, info.target)
            UnitAddAbility(info.target, CONFIG.refs.abilities.effect)
            Dummy.applyDummyOrder(owner, info.target, CONFIG.refs.abilities.debuff, "acidbomb")
            Timed.call(0.1, function()
                if not Generic.contains(memory, info.target) then
                    table.insert(memory, info.target)
                end
            end)
        end
    end)

    -- ? visuals

    return
end

local function onTimer()
    for i = #memory, 1, -1 do
        local unit = memory[i]
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            UnitRemoveAbility(unit, CONFIG.refs.abilities.effect)
            table.remove(memory, i)
        end
    end
end

return {
    triggers = {
        {
            trigger = "AFTER_DAMAGE",
            filter = { source = CONFIG.refs.units.carrier },
            action = onAfterDamage,
        },
        {
            trigger = "TIMER",
            delta = 0.25,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/common/fly.lua'] = [=[--[[
-- ? include all ground-fly units
-- ? maybe use on/off version of Channel ability instead of memory<>
-- handle units with default flying state
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            forsworn = Ids.abilities.forswornHeroFly,
            forswornInstant = Ids.abilities.forswornHeroFlyInstant,
        },
        buffs = {},
        units = {
            carrier = { Ids.units.forswornHero, Ids.units.forswornHeroFlying },
        },
        items = {},
    },
    balance = {
        --
    },
})

-- MAPPING = {}

--- @type table<unit, {flying: boolean}>
local memory = {} -- TODO: save/load

--- Default: false
local function getFlyingState(unit)
    if not memory[unit] then
        memory[unit] = {
            flying = false,
        }
    end
    return memory[unit].flying
end

local function updateFlyingState(unit, status)
    if not memory[unit] then
        memory[unit] = {}
    end
    local order
    if status then
        order = "ravenform"
    else
        order = "unravenform"
    end
    local success = IssueImmediateOrder(unit, order)
    dump("IssueImmediateOrder", status, order, ordersuccess)
    if success then
        memory[unit].flying = status
    end
    return success
end

local function toggleFlyingState(unit)
    updateFlyingState(unit, not getFlyingState(unit))
end

local function onFlyToggle()
    local unit = GetTriggerUnit()
    dump("fly state before", unit, getFlyingState(unit))
    toggleFlyingState(unit)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_FINISH",
            spellId = CONFIG.refs.abilities.forsworn,
            action = onFlyToggle,
        },
    },
    config = CONFIG,
    api = {
        get = getFlyingState,
        set = updateFlyingState,
    },
}]=]

P['scenario/factions/mawsworn/abilities/common/grab.lua'] = [=[--[[
-- TODO
-- - !!! check distance - prevent grab if target has moved far away
-- - BUG: grabber doesn't flush
-- - process 1.33/1.5 WS stacks per hit
-- - debuff kidnapper for dmg/speed
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local ItemMeta = require("lib.items")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.mawswornGrab,
        },
        buffs = {
            exhaustion = Ids.buffs.exhaustion,
        },
        units = {
            cage = Ids.units.mawswornCage,
        },
    },
    balance = {
        tickDelta = 1,
        dropsAfter = 90,
    },
})

--- @alias GrabMemory {holder: unit|nil, unit: unit, dropsAt: float|nil}

local grabId = 1
--- @type table<item, GrabMemory>
local memory = {} -- TODO: save/load --
--- @type table<unit, item>
local grabbers = {}
local grabQueue = {}

--- @param item item
local function flushGrabber(item)
    if memory[item].holder and grabbers[memory[item].holder] then
        grabbers[memory[item].holder] = nil
    end
end

--- @param item item
--- @param unit unit
local function onPickUpItem(item, unit)
    flushGrabber(item)
    memory[item].holder = unit
    if GetUnitTypeId(unit) == CONFIG.refs.units.cage then
        memory[item].dropsAt = nil
    else
        memory[item].dropsAt = GetElapsedGameTime() + CONFIG.balance.dropsAfter
    end
end

--- @param item item
local function onDropItem(item)
    SetUnitX(memory[item].unit, GetItemX(item))
    SetUnitY(memory[item].unit, GetItemX(item))
    ShowUnitShow(memory[item].unit)
    RemoveItem(item)
    flushGrabber(item)
    memory[item] = nil
end

--- @param item item
local function getItemMemory(item)
    return memory[item]
end

--- @param item item
local function flushItemMemory(item)
    flushGrabber(item)
    memory[item] = nil
end

local function onGrabCast()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    grabQueue[caster] = target
end

local function onGrabCastFinish()
    local unit = GetTriggerUnit()
    local target = grabQueue[unit]

    if grabbers[unit] then
        dump("onGrabCastFinish break: unit already has grabbed someone")
        return
    end
    if not UnitHasBuffBJ(target, CONFIG.refs.buffs.exhaustion) then
        dump("onGrabCastFinish break: target doesnt have exhaust debuff")
        return
    end
    if not Unit.hasSpaceInInventory(unit) then
        dump("onGrabCastFinish break: unit doesnt have free space in inventory")
        return
    end

    ShowUnitHide(target)
    local itemId = ItemMeta.getGrabItemId(GetUnitTypeId(target))
    local item = CreateItem(itemId, GetUnitX(target), GetUnitY(target))
    UnitAddItem(unit, item)

    memory[item] = {
        unit = target,
    }
    onPickUpItem(item, unit)
    grabbers[unit] = item
end

local function onDropItemEvent()
    local caster = GetTriggerUnit()
    local item = GetManipulatedItem()
    dump("onDropItemEvent()", item)
    if not item or not memory[item] then
        return
    end

    flushGrabber(item)
    memory[item].holder = nil
    memory[item].dropsAt = nil

    -- TODO: warning!!! Can be desync cause?
    Timed.call(0.00, function()
        if memory[item] and not memory[item].holder then
            dump("onDropItem() FLUSH")
            onDropItem(item)
        end
    end)
end

local function onPickUpItemEvent()
    local unit = GetTriggerUnit()
    local item = GetManipulatedItem()
    dump("onPickUpItemEvent()", item)
    if not memory[item] then
        return
    end

    onPickUpItem(item, unit)
end

local function onTimer()
    -- == WS flush
    local now = GetElapsedGameTime()
    local flushQueue = {}
    for item, memoryData in pairs(memory) do
        if memoryData.dropsAt and now > memoryData.dropsAt then
            onDropItem(item)
            table.insert(flushQueue, item)
        end
    end
    for _, item in ipairs(flushQueue) do
        dump("Grab TIMER FLUSH", item)
        flushGrabber(item)
        memory[item] = nil
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onGrabCast,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_FINISH",
            spellId = CONFIG.refs.abilities.main,
            action = onGrabCastFinish,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_PICKUP_ITEM",
            action = onPickUpItemEvent,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DROP_ITEM",
            action = onDropItemEvent,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.tickDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
    api = {
        getItemMemory = getItemMemory,
        flushItemMemory = flushItemMemory,
        onDropItem = onDropItem,
    },
}]=]

P['scenario/factions/mawsworn/abilities/heroes/abduct.lua'] = [=[--[[
TODO:
- resolve conflict with antiair stun
- different behaviour when caster as ground form and air form
- switch to air on end cast
- targets only ground units
- ? special apply to ground-air units
- ? pontential bug - default fly height handle
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")

local Fly = require("scenario.factions.mawsworn.abilities.common.fly")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.abduct,
            height = Ids.abilities.abductHeight,
            morph = Ids.abilities.forswornHeroFly,
        },
        buffs = {},
        units = {
            carrierGround = Ids.units.forswornHero,
            carrierAir = Ids.units.forswornHeroFlying,
        },
        items = {},
    },
    balance = {
        --
        ascendSpeed = 100, -- per second
        fallSpeed = 1000, -- per second
        fallDamage = 50, -- per 100 units of height
        ascendTimerDelta = 0.5,
    },
})

--- @type table<unit, {target: unit}>
local abductors = {}
--- @type table<unit, {caster: unit, height: number, falling: boolean}>
local abducted = {} -- TODO: save/load

local function endEffect(caster, target)
    -- drop
    -- restore fly height
    -- damage basing on current height
    local height = abducted[target].height
    local fallTime = height / CONFIG.balance.fallSpeed
    SetUnitFlyHeight(caster, 0, height / CONFIG.balance.fallSpeed)
    SetUnitFlyHeight(target, 0, height / CONFIG.balance.fallSpeed)
    Timed.call(fallTime, function()
        abductors[caster] = nil
        abducted[target] = nil
        local dummy = Dummy.create(GetOwningPlayer(caster), target)
        local fallDamage = Damage.apply(
            dummy,
            target,
            height / CONFIG.balance.fallDamage,
            false,
            false,
            ATTACK_TYPE_CHAOS,
            DAMAGE_TYPE_ENHANCED
        )
    end)
end

local function onSpell()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    abductors[caster] = { target = target }
    abducted[target] = { caster = caster, height = 0, falling = false } -- TODO: diff default height
end

local function onEndcast()
    -- TODO: ? conflict with antiair stun
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    endEffect(caster, target)
end

local function onOrder()
    local unit = GetOrderedUnit()
    if not abducted[unit] then
        return
    end
    IssueImmediateOrder(unit, "hold")
end

local function onTimer()
    for target, data in pairs(abducted) do
        if not data.falling then
            local caster = data.caster
            local ascendPerSecond = (CONFIG.balance.ascendSpeed / CONFIG.balance.ascendTimerDelta)
            SetUnitFlyHeight(caster, ascendPerSecond, ascendPerSecond)
            SetUnitFlyHeight(target, ascendPerSecond, ascendPerSecond)
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_ENDCAST",
            spellId = CONFIG.refs.abilities.main,
            action = onEndcast,
        },
        {
            trigger = "ORDER",
            action = onOrder,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.ascendTimerDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/heroes/deadlyBlow.lua'] = [=[--[[
TODO:
-- GC memory/marked
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.deadlyBlow,
            mark = Ids.abilities.deadlyBlowMark,
            stun = Ids.abilities.deadlyBlowStun,
        },
        buffs = {
            mark = Ids.buffs.deadlyBlowMark,
        },
        units = {
            carrier = Ids.units.mournebladeHero,
        },
    },
    balance = {
        radius = 800,
    },
})

--- @type table<unit, {target: unit, expiresAt: number}>
local memory = {} -- TODO: save/load
--- @type table<unit, {level: integer}>
local marked = {}

local function onSpell()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local level = GetUnitAbilityLevel(caster, CONFIG.refs.abilities.main)

    if not memory[caster] then
        dump("Cant activate deadly blow - no last AA target")
        return
    end
    local target = memory[caster].target
    if not Unit.isAlive(target) then
        dump("Cant activate deadly blow - last AA target isnt alive")
        return
    end
    if GetElapsedGameTime() > memory[caster].expiresAt then
        dump("Cant activate deadly blow - last AA expired")
        return
    end
    local d = Unit.distance(caster, target)
    if d > CONFIG.balance.radius then
        dump("Cant activate deadly blow - last AA target too far")
        return
    end

    Dummy.applyDummyOrder(owner, target, CONFIG.refs.abilities.mark, "acidbomb", level)
    marked[target] = {
        level = level,
    }
end

--- @param info damageInfo
local function onDamage(info)
    if not info.isAttack then
        return
    end
    memory[info.source] = { target = info.target, expiresAt = GetElapsedGameTime() + CONFIG.balance.duration }
    if marked[info.target] then
        local owner = GetOwningPlayer(info.source)
        UnitRemoveBuffBJ(CONFIG.refs.buffs.mark, marked[info.target])
        Dummy.applyDummyOrder(owner, info.target, CONFIG.refs.abilities.stun, "thunderbolt", marked[info.target].level)
        marked[info.target] = nil
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "DAMAGE",
            filter = {
                source = CONFIG.refs.units.carrier,
            },
            action = onDamage,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/heroes/gorgoa.lua'] = [=[--[[
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Souls = require("scenario.factions.mawsworn.mechanics.souls")
local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.gorgoa,
        },
        units = {
            soul = Ids.units.gorgoaSoul,
        },
    },
    balance = {
        radius = 600,
        wsApplyDelta = 1,
        soulSpawnDelta = 0.5,
        timerDelta = 0.5,
    },
})

--- @type table<unit, {player: player, facing: number, point: Point, nextWsAt: number, nextSoulAt: number}>
local memory = {}

--- @type table<unit, {x: number, y: number}>
local souls = {} -- remove on max distance

local function spawnSoul(caster)
    local data = memory[caster]

    local f = data.facingRadians
    local s = CONFIG.balance.radius -- Square side length (adjust to your spell size)

    -- Random point on the far edge (behind hero)
    -- Center of far edge: (-cos(f)*s/2, -sin(f)*s/2) relative to hero
    -- Offset along edge: (+sin(f)*rand, -cos(f)*rand)
    local r = GetRandomReal(-s / 2, s / 2)
    local spawnX = data.x - (math.cos(f) * s / 2) + (math.sin(f) * r)
    local spawnY = data.y - (math.sin(f) * s / 2) - (math.cos(f) * r)

    -- Spawn unit facing the hero
    ---@diagnostic disable-next-line: param-type-mismatch
    local soul = CreateUnit(data.player, CONFIG.refs.units.soul, spawnX, spawnY, data.facing)

    -- Charge X units in direction of hero's facing
    local targetX = data.x + (s * 2) * math.cos(f)
    local targetY = data.y + (s * 2) * math.sin(f)
    IssuePointOrder(soul, "move", targetX, targetY)

    Souls.api.store("gorgoa", soul)
end

local function onCastStart()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local targetX = GetSpellTargetX()
    local targetY = GetSpellTargetY()

    local facing = GetUnitFacing(caster)
    local facingRadians = math.rad(facing)
    -- local oppositeAngleDeg = facing + 180.0
    -- local oppositeAngleRad = math.rad(oppositeAngleDeg)

    memory[caster] = {
        player = owner,
        facing = facing,
        facingRadians = facingRadians,
        point = { x = targetX, y = targetY },
        nextWsAt = GetElapsedGameTime(),
        nextSoulAt = GetElapsedGameTime(),
        xVector = CONFIG.balance.radius * 2 * math.cos(facingRadians),
        yVector = CONFIG.balance.radius * 2 * math.sin(facingRadians),
    }
end

local function onCastEnd()
    local caster = GetTriggerUnit()
    memory[caster] = nil
end

local function onTimer()
    -- TODO: ? ensure always identical amount of stacks applies by full cast
    local now = GetElapsedGameTime()
    for caster, data in pairs(memory) do
        if now > data.nextWsAt then
            for _, target in
                ipairs(Unit.getUnitsInRadius(data.point, CONFIG.balance.radius, function(t)
                    return not IsUnitAlly(t, data.player)
                end))
            do
                WS.api.applyWeakenedSoulStack(target, 1, data.player)
                data.nextWsAt = GetElapsedGameTime() + CONFIG.balance.wsApplyDelta
            end
        end
        if now > data.nextSoulAt then
            spawnSoul(caster)
            data.nextSoulAt = GetElapsedGameTime() + CONFIG.balance.soulSpawnDelta
        end
    end
end

local function onSoulStop()
    local unit = GetOrderedUnit()
    Souls.api.use("gorgoa", unit)
    souls[unit] = nil
    RemoveUnit(unit)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onCastStart,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_ENDCAST",
            spellId = CONFIG.refs.abilities.main,
            action = onCastEnd,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.timerDelta,
            action = onTimer,
        },
        {
            trigger = "ORDER",
            order = "stop",
            filter = { source = CONFIG.refs.units.soul },
            action = onSoulStop,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/heroes/harpoon.lua'] = [=[--[[
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.harpoon,
            dummy = Ids.abilities.harpoonDummy,
        },
        buffs = {
            main = Ids.buffs.harpoon,
        },
        units = {
            carrier = { Ids.units.forswornHero, Ids.units.forswornHeroFlying },
        },
    },
    balance = {
        radius = 64,
        rootDuration = 3,
        flushDelta = 0.5,
    },
})

--- @type table<unit, {owner: player, level: integer}>
local memory = {} -- harpoon missiled
--- @type table<unit, {propWindow: number, expiresAt: number}>
local rooted = {}

local function applyEffect(unit)
    rooted[unit] =
        { propWindow = GetUnitPropWindow(unit), expiresAt = GetElapsedGameTime() + CONFIG.balance.rootDuration }
    SetUnitPropWindow(unit, 0)
end

local function removeEffect(unit)
    SetUnitPropWindow(unit, rooted[unit].propWindow)
    rooted[unit] = nil
end

local function onSpell()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    local level = GetUnitAbilityLevel(caster, CONFIG.refs.abilities.main)

    memory[target] = { owner = GetOwningPlayer(caster), level = level }
end

--- @param info damageInfo
local function onAfterDamage(info)
    local source = info.source
    local target = info.target
    Timed.call(0.1, function()
        if memory[target] and UnitHasBuffBJ(target, CONFIG.refs.buffs.main) then
            applyEffect(target)
            for _, unit in
                ipairs(Unit.getUnitsInRadius(target, CONFIG.balance.radius, function(u)
                    return not IsUnitAlly(u, GetOwningPlayer(source))
                end))
            do
                applyEffect(unit)
                Dummy.applyDummyOrder(
                    GetOwningPlayer(source),
                    unit,
                    CONFIG.refs.abilities.harpoonDummy,
                    "thunderbolt",
                    memory[target].level
                )
            end
            memory[target] = nil
        end
    end)
end

local function onTimer()
    for unit, data in pairs(rooted) do
        if GetElapsedGameTime() > data.expiresAt then
            removeEffect(unit)
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "AFTER_DAMAGE",
            filter = { source = CONFIG.refs.units.carrier },
            action = onAfterDamage,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.flushDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

