P['scenario/factions/mawsworn/abilities/heroes/opressiveChains.lua'] = [=[--[[
TODO:
-- - BUG: multiple heroes apply chains on same unit - memory rewrites, effect bugs
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.opressiveChains,
            slow = Ids.abilities.opressiveChainsSlow,
        },
        buffs = {
            main = Ids.buffs.opressiveChains,
        },
        units = {
            chain = { Ids.units.opressiveChain1, Ids.units.opressiveChain2, Ids.units.opressiveChain3 },
        },
    },
    balance = {
        radius = 300,
        breakDamage = { 100, 200, 300 },
        duration = 8,
        timerDelta = 0.5,
    },
})

--- @type table<unit, {chain: unit, level: integer}>
local memory = {} -- TODO: save/load /+/ cleaning

--- @param unit unit
--- @param level integer
--- @return unit
local function applyEffect(unit, level)
    local owner = GetOwningPlayer(unit)
    local dummy = CreateUnit(owner, CONFIG.refs.units.chain[level], GetUnitX(unit), GetUnitY(unit), 270)
    UnitAddType(dummy, UNIT_TYPE_SUMMONED)
    Unit.applyTimedLife(dummy, CONFIG.balance.duration)
    Dummy.applyDummyOrder(owner, unit, CONFIG.refs.abilities.slow, "shadowstrike", level)

    memory[unit] = { level = level, chain = dummy }
    return dummy
end

local function onSpell()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    local level = GetUnitAbilityLevel(caster, CONFIG.refs.abilities.main)

    applyEffect(target, level)
end

local function onTimer()
    for unit, data in pairs(memory) do
        if Unit.isAlive(data.chain) then
            local d = Unit.distance(unit, data.chain)
            if d > CONFIG.balance.radius then
                Damage.apply(data.chain, unit, CONFIG.balance.breakDamage[data.level], false, false, ATTACK_TYPE_CHAOS)
            end
        else
            UnitRemoveBuffBJ(CONFIG.refs.buffs.main, unit)
            memory[unit] = nil
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.timerDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/heroes/promoteLeutinant.lua'] = [=[--[[
TODO:
-- ? on skill level learn - update buff
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.promoteLeutinant,
            damage = Ids.abilities.promoteLeutinantDamageBuff,
            hp = Ids.abilities.promoteLeutinantHp,
        },
        units = {},
    },
    balance = {
        diminishing = {
            melee = 1,
            ranged = 2,
        },
    },
})

--- @type table<unit, {unit: unit}>
local memory = {} -- TODO: save/load -- caster to leut
--- @type table<unit, {availableAt: number}>
local leutinants = {} -- leut diminishing

--- @param unit unit
--- @param level integer
local function applyEffect(unit, level)
    leutinants[unit] = {
        availableAt = GetElapsedGameTime(),
    }
    if GetUnitAbilityLevel(unit, CONFIG.refs.abilities.damage) == 0 then
        UnitAddAbility(unit, CONFIG.refs.abilities.damage)
    end
    if GetUnitAbilityLevel(unit, CONFIG.refs.abilities.hp) == 0 then
        UnitAddAbility(unit, CONFIG.refs.abilities.hp)
    end
    SetUnitAbilityLevel(unit, CONFIG.refs.abilities.damage, level)
    SetUnitAbilityLevel(unit, CONFIG.refs.abilities.hp, level)
end

--- @param unit unit
local function removeEffect(unit)
    leutinants[unit] = nil
    UnitRemoveAbility(unit, CONFIG.refs.abilities.damage)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.hp)
end

local function onSpell()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    local level = GetUnitAbilityLevel(caster, CONFIG.refs.abilities.main)

    if memory[caster] then
        removeEffect(memory[caster].unit)
    end

    memory[caster] = { unit = target }
    applyEffect(target, level)
end

--- @param info damageInfo
local function onDamage(info)
    if not info.isAttack then
        return
    end
    if not leutinants[info.source] then
        return
    end

    local now = GetElapsedGameTime()
    if now < leutinants[info.source].availableAt then
        return
    end

    local cooldown
    if info.isMelee then
        cooldown = CONFIG.balance.diminishing.melee
    else
        cooldown = CONFIG.balance.diminishing.ranged
    end

    WS.api.applyWeakenedSoulStack(info.target, 1, GetOwningPlayer(info.source))
    leutinants[info.source].availableAt = now + cooldown
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "DAMAGE",
            filter = {
                source = CONFIG.refs.units.carrier,
            },
            action = onDamage,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/heroes/soulRend.lua'] = [=[--[[
TODO:
-- ! passive DMG effect update
-- aura buff or info passive to show current soul count
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Souls = require("scenario.factions.mawsworn.mechanics.souls")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            toggle = Ids.abilities.soulRend,
            damage = Ids.abilities.soulRendDamage,
            heal = Ids.abilities.soulRendHeal,
        },
    },
    balance = {
        duration = 2,
        cooldown = 1,
        maxSouls = { 3, 6, 9 },
        timerDelta = 0.5,
    },
})

--- @type table<unit, {toggle: boolean, nextHealAt: number|nil, lastHitTo: unit|nil, lastHitAt: number|nil}>
local memory = {}
--- @type table<unit, unit>
local targetToMourneblade = {}

local function updateDamageEffect(unit)
    local level = Souls.api.count("unit", unit)
    if level == 0 then
        UnitRemoveAbility(unit, CONFIG.refs.abilities.damage)
    else
        local currentEffectLevel = GetUnitAbilityLevel(unit, CONFIG.refs.abilities.damage)
        if currentEffectLevel == 0 then
            UnitAddAbility(unit, CONFIG.refs.abilities.damage)
        end
        SetUnitAbilityLevel(unit, CONFIG.refs.abilities.damage, level)
    end
end

local function stopEffect(unit)
    IssueImmediateOrder(unit, "unimmolation")
    memory[unit].toggle = false
end

local function applyEffect(unit)
    local now = GetElapsedGameTime()

    memory[unit].toggle = true

    if not Souls.api.count("unit", unit) then
        dump("soulRend toggle error - no souls available")
        stopEffect(unit)
        return
    end

    if now < memory[unit].nextHealAt then
        return
    end

    if not Souls.api.use("unit", unit, 1) then
        stopEffect(unit)
        return
    end

    updateDamageEffect(unit)

    local owner = GetOwningPlayer(unit)
    Dummy.applyDummyOrder(owner, unit, CONFIG.refs.abilities.heal, "heal")

    memory[unit].nextHealAt = now + CONFIG.balance.cooldown
end

local function onTurnOn()
    dump("mawcaster onspell")
    local caster = GetTriggerUnit()

    applyEffect(caster)
end

local function onTurnOff()
    local caster = GetTriggerUnit()
    stopEffect(caster)
end

--- @param info damageInfo
local function onDamage(info)
    local source = info.source
    local target = info.target

    if not memory[source] then
        memory[source] = { toggle = false }
    end
    if memory[source].lastHitTo and memory[source].lastHitTo ~= target then
        targetToMourneblade[memory[source].lastHitTo] = nil
        memory[source].lastHitTo = target
        memory[source].lastHitAt = GetElapsedGameTime()
    end
    targetToMourneblade[target] = source
end

local function onDeath()
    local unit = GetDyingUnit()
    local source = targetToMourneblade[unit]
    if source and GetElapsedGameTime() < (memory[source].lastHitAt + CONFIG.balance.duration) then
        local level = GetUnitAbilityLevel(source, CONFIG.refs.abilities.main)
        if Souls.api.count("unit", source) <= CONFIG.balance.maxSouls[level] then
            Souls.api.store("unit", source)
        end
        updateDamageEffect(source)
    end
end

local function onTimer()
    for mourneblade, data in pairs(memory) do
        if data.nextHealAt and GetElapsedGameTime() > data.nextHealAt then
            applyEffect(mourneblade)
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.toggle,
            action = onTurnOn,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_ISSUED_ORDER",
            order = "unimmolation",
            action = onTurnOff,
        },
        {
            trigger = "DAMAGE",
            filter = { source = CONFIG.refs.units.carrier },
            action = onDamage,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DEATH",
            action = onDeath,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.timerDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/heroes/superiourCause.lua'] = [=[--[[
1. after damage -> apply shield once and start casting
2. on damage -> reduce shield
3. on cast finish -> detonate

TODO:
-- ? on skill level learn - update buff
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.superiourCause,
            shield = Ids.abilities.superiourCauseShield,
            dummy = Ids.abilities.superiourCauseDummy,
            detonate = Ids.abilities.superiourCauseDetonate,
        },
        buffs = {
            main = Ids.buffs.superiourCause,
        },
        units = {},
    },
    balance = {
        shieldAmount = 50,
    },
})

--- @type table<unit, {shieldAmount: integer}>
local memory = {} -- TODO: save/load /+/ cleaning

--- @param unit unit
--- @param level integer
local function applyEffect(unit, level)
    local owner = GetOwningPlayer(unit)
    memory[unit] = {
        shieldAmount = CONFIG.balance.shieldAmount,
    }
    Dummy.applyDummyOrder(owner, unit, CONFIG.refs.abilities.shield, "acidbomb", level)

    UnitAddAbility(unit, CONFIG.refs.abilities.dummy)
    SetUnitAbilityLevel(unit, CONFIG.refs.abilities.dummy, level)
    IssueImmediateOrder(unit, "channel")
    -- UnitRemoveAbility(unit, CONFIG.refs.abilities.dummy)
end

--- @param unit unit
--- @param level integer
local function applyDetonate(unit, level)
    local owner = GetOwningPlayer(unit)
    memory[unit] = nil

    UnitAddAbility(unit, CONFIG.refs.abilities.detonate)
    SetUnitAbilityLevel(unit, CONFIG.refs.abilities.detonate, level)
    IssueTargetOrder(unit, "selfdestruct", unit)
end

--- @param info damageInfo
local function onLethalDamage(info)
    if not UnitHasBuffBJ(info.target, CONFIG.refs.buffs.main) then
        return
    end
    if memory[info.target] then
        return
    end

    -- TODO: find hero -> get level | OR cache aura level
    local level = 1
    applyEffect(info.target, level)

    Damage.life = 1 -- HACK: turn off next onLethalDamage callback in chain
end

--- @param info damageInfo
local function onDamage(info)
    if not memory[info.target] then
        return
    end

    local shieldAmount = memory[info.target].shieldAmount
    if shieldAmount then
        local soaked = math.min(info.damage, shieldAmount)
        info.damage = info.damage - soaked

        memory[info.target].shieldAmount = shieldAmount - soaked
        if soaked == shieldAmount then
            UnitRemoveBuffBJ(CONFIG.refs.buffs.main, info.target)
        end
    end
end

local function onSpell()
    local unit = GetTriggerUnit()
    local level = GetUnitAbilityLevel(unit, CONFIG.refs.abilities.dummy)

    applyDetonate(unit, level)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_FINISH",
            spellId = CONFIG.refs.abilities.dummy,
            action = onSpell,
        },
        {
            trigger = "DAMAGE",
            priority = -1000, -- later than all
            action = onDamage,
        },
        {
            trigger = "LETHAL_DAMAGE",
            priority = 1000, -- earlier than all
            action = onLethalDamage,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/heroes/twistedPain.lua'] = [=[--[[
TODO:
-- onUnitRemove - clean memory (add trigger type)
-- some visual effect for voidzone
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.twistedPain,
        },
        buffs = {
            main = Ids.buffs.twistedPain,
        },
        units = {},
    },
    balance = {
        hits = {
            [1] = 1,
            [2] = 2,
            [3] = 3,
        },
        damagePerTick = {
            [1] = 20,
            [2] = 40,
            [3] = 60,
        },
        radius = 200,
        ticks = 3,
        tickDelta = 1,
        timerDelta = 0.5,
        flushDelta = 1,
    },
})

--- @type table<unit, {level: integer, owner: player, buffApplied: boolean, hits: integer, availableAt: number}> target->hits
local memory = {} -- TODO: save/load /+/ cleaning
--- @type table<unit, {level: integer, ticks: integer, tickAt: number}> dummy->ticks
local voidzones = {}

--- @param info damageInfo
local function onDamage(info)
    if not memory[info.target] then
        return
    end
    if GetElapsedGameTime() < memory[info.target] then
        return
    end
    if not UnitHasBuffBJ(info.target, CONFIG.refs.buffs.main) then
        return
    end
    if memory[info.target].hits == 0 then
        memory[info.target] = nil
        return
    end

    memory[info.target].hits = memory[info.target].hits - 1

    local dummy = Dummy.create(memory[info.target].owner, info.target)
    voidzones[dummy] = {
        level = memory[info.target].level,
        owner = memory[info.target].owner,
        ticks = CONFIG.balance.ticks,
        tickAt = GetElapsedGameTime(),
    }
end

local function onSpell()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    local level = GetUnitAbilityLevel(caster, CONFIG.refs.abilities.dummy)

    memory[target] = {
        level = level,
        owner = GetOwningPlayer(caster),
        buffApplied = false,
        hits = CONFIG.balance.hits[level],
        availableAt = GetElapsedGameTime(),
    }
end

local function onTimer()
    --- @type table<unit, {dummies: unit[]}>
    local damage = {}
    local now = GetElapsedGameTime()
    for dummy, data in pairs(voidzones) do
        for _, unit in
            Unit.getUnitsInRadius(dummy, CONFIG.balance.radius, function(u)
                return not IsUnitAlly(u, data.owner)
            end)
        do
            damage[unit] = { dummies = damage[unit].dummies or {} }
            table.insert(damage[unit].dummies, dummy)
        end
    end
    --
    local ticked = {}
    for target, data in pairs(damage) do
        local damageSource
        for _, dummy in ipairs(damage[target].dummies) do
            local dummyData = voidzones[dummy]
            if damageSource then
                ticked[dummy] = true
                dummyData.ticks = dummyData.ticks - 1
                dummyData.tickAt = now + CONFIG.balance.tickDelta
            elseif now > dummyData.ticksAt then
                ticked[dummy] = true
                dummyData.ticks = dummyData.ticks - 1
                dummyData.tickAt = now + CONFIG.balance.tickDelta
                damageSource = dummy
            end
        end
        if damageSource then
            Damage.apply(
                damageSource,
                target,
                CONFIG.balance.damagePerTick[voidzones[damageSource].level],
                false,
                false,
                ATTACK_TYPE_CHAOS
            )
        end
    end
    --
    for dummy, data in pairs(voidzones) do
        if not ticked[dummy] and now > GetElapsedGameTime() then
            data.ticks = data.ticks - 1
            data.tickAt = now + CONFIG.balance.tickDelta
        end
        if data.ticks <= 0 then
            voidzones[dummy] = nil
        end
    end
end

local function onTimerFlush()
    for unit, data in pairs(memory) do
        local buffFound = UnitHasBuffBJ(unit, CONFIG.refs.buffs.main)
        if buffFound and not data.buffApplied then
            data.buffApplied = true
        elseif data.buffApplied and not buffFound then
            memory[unit] = nil
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "DAMAGE",
            action = onDamage,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.timerDelta,
            action = onTimer,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.flushDelta,
            action = onTimerFlush,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/heroes/wraithWalk.lua'] = [=[--[[
TODO:
-- check reapply after attack / spell cast
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.wraithWalk,
            phase = Ids.abilities.wraithWalkPhase,
            aura = Ids.abilities.wraithWalkSlow,
        },
        buffs = {
            main = Ids.buffs.wraithWalk,
        },
        units = {
            carrier = Ids.units.mournebladeHero,
        },
    },
    balance = {
        duration = { 4, 6, 8 },
        timerDelta = 0.5,
    },
})

--- @type table<unit, {expiresAt: number, level: integer}>
local memory = {} -- TODO: save/load

local function applyEffect(unit, level)
    -- apply/reapply phase
    UnitAddAbility(unit, CONFIG.refs.abilities.phase)
    SetUnitAbilityLevel(unit, CONFIG.refs.abilities.phase, level)
    IssueImmediateOrder(unit, "windwalk")
    UnitRemoveAbility(unit, CONFIG.refs.abilities.phase)

    if not memory[unit] then
        UnitAddAbility(unit, CONFIG.refs.abilities.aura)
        SetUnitAbilityLevel(unit, CONFIG.refs.abilities.aura, level)
        memory[unit] = { expiresAt = GetElapsedGameTime() + CONFIG.balance.duration[level], level = level }
    end
end

local function removeEffect(unit, level)
    UnitRemoveBuffBJ(CONFIG.refs.buffs.main, unit)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.aura)
    memory[unit] = nil
end

local function onSpell()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local level = GetUnitAbilityLevel(caster, CONFIG.refs.abilities.main)

    applyEffect(caster, level)
end

local function onTimer()
    for unit, data in pairs(memory) do
        if GetElapsedGameTime() > data.expiresAt then
            removeEffect(unit)
        elseif not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            applyEffect(unit, data.level)
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.timerDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/items/soulforged.lua'] = [=[--[[
