    UnitAddAbility(info.source, CONFIG.refs.abilities.gauntletsFrenzy)
    IssueImmediateOrder(info.source, "berserk")
    UnitRemoveAbility(info.source, CONFIG.refs.abilities.gauntletsFrenzy)
end

return {
