]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local ItemMeta = require("lib.items")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Souls = require("scenario.factions.mawsworn.mechanics.souls")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.soulkeeper,
        },
        buffs = {},
        items = {
            main = { Ids.items.soulkeeper0, Ids.items.soulkeeper1, Ids.items.soulkeeper2, Ids.items.soulkeeper3 },
            soul = Ids.items.soul,
        },
        units = {
            receiver = { Ids.units.mawswornCage, Ids.units.mawswornMechBarracks },
        },
    },
    balance = {
        cooldown = 2,
        maxCapacity = 3,
    },
})

local byLevel = {
    [0] = CONFIG.refs.items.main[1],
    [1] = CONFIG.refs.items.main[2],
    [2] = CONFIG.refs.items.main[3],
    [3] = CONFIG.refs.items.main[4],
}
local byLevelReversed = {
    [byLevel[0]] = 0,
    [byLevel[1]] = 1,
    [byLevel[2]] = 2,
    [byLevel[3]] = 3,
}

local function isReceiver(unit)
    return Generic.contains(CONFIG.refs.units.receiver, GetUnitTypeId(unit))
end

--- @param item item
--- @return boolean
local function isOnGround(item)
    return not IsItemOwned(item)
end

--- @param item item
local function clearOrphanSoul(item)
    if Souls.api.holder.isOrphan(item) then
        Souls.api.use("orphan", item)
    end
end

--- @param unit unit Unit who receives item
--- @param oldItem item
--- @param slot integer
local function updateSoulkeeper(unit, oldItem, slot)
    local itemId = byLevel[Souls.api.count("item", oldItem)]
    RemoveItem(oldItem)
    UnitAddItemToSlotById(unit, itemId, slot)

    local newItem = UnitItemInSlot(unit, slot)
    Souls.api.remap("item", oldItem, newItem)
    Souls.api.holder.update(unit, newItem, true)
end

--- @param unit unit
--- @param item item
local function onPickUpSoul(unit, item)
    clearOrphanSoul(item)

    if isReceiver(unit) then
        return
    end

    local soulkeepersHeld = Souls.api.holder.getItems(unit)
    if not soulkeepersHeld then
        UnitDropItemPoint(unit, item, GetUnitX(unit), GetUnitY(unit))
        return
    end

    local soulkeeperSlot = Unit.findItem(unit, function(s)
        return Souls.api.count("item", s) <= CONFIG.balance.maxCapacity
    end)
    if not soulkeeperSlot then
        UnitDropItemPoint(unit, item, GetUnitX(unit), GetUnitY(unit))
        return
    end

    RemoveItem(item)
    Souls.api.store("item", soulkeeperSlot.item)

    updateSoulkeeper(unit, soulkeeperSlot.item, soulkeeperSlot.index)
end

--- @param item item
local function onDropSoul(item)
    Timed.call(0.00, function()
        if IsItemOwned(item) then
            return
        end
        Souls.api.store("orphan", item)
        Timed.call(1, function() -- TODO: optimize, remove recursive lambda
            if Souls.api.holder.isOrphan(item) and isOnGround(item) then
                Souls.api.use("orphan", item)
            end
        end)
    end)
end

local function onPickUpItem()
    local item = GetManipulatedItem()
    local unit = GetTriggerUnit()
    if GetItemTypeId(item) == CONFIG.refs.items.soul then
        onPickUpSoul(unit, item)
    end
    if not byLevelReversed[GetItemTypeId(item)] then
        return
    end
    Souls.api.holder.update(unit, item, true)
end

local function onDropItem()
    -- Game crash? Lololol
    local item = GetManipulatedItem()
    if GetItemTypeId(item) == CONFIG.refs.items.soul then
        onDropSoul(item)
        return
    end
    if not byLevelReversed[GetItemTypeId(item)] then
        return
    end
    local dropper = GetTriggerUnit()
    local returnTo = dropper

    Timed.call(0.00, function()
        local receiver = Souls.api.holder.get(item)
        dump("onDropItem", returnTo, receiver)
        if isReceiver(receiver) then
            UnitAddItem(returnTo, item)

            local capacity = Souls.api.count("item", item)
            local receiverSlots = Unit.countFreeSlots(receiver)
            local amount = math.min(capacity, receiverSlots)
            if amount == 0 then
                dump("Trying to pass 0 souls")
                return
            end
            Souls.api.use("item", item, amount)
            for i = 1, amount do
                UnitAddItemById(receiver, CONFIG.refs.items.soul)
            end
        else
            if Souls.api.holder.get(item) == dropper then
                Souls.api.holder.update(dropper, item, false)
            end
        end
    end)
end

--- Sell item to shop
local function onPawnItem()
    local item = GetManipulatedItem()
    -- if GetItemTypeId(item) == CONFIG.refs.items.soul then
    --     clearOrphanSoul(item)
    --     return
    -- end
    if not byLevelReversed[GetItemTypeId(item)] then
        return
    end
    local unit = GetSellingUnit()
    local receiver = GetBuyingUnit()
    dump("onPawnItem event", unit, receiver)
    -- Souls.api.holder.update(unit, item, false)
end

local function onActivate()
    -- TODO: ? multiple soulkeepers on 1 hero
    local caster = GetTriggerUnit()
    local slot = Unit.findItem(caster, function(i)
        return byLevelReversed[GetItemTypeId(i)] ~= nil
    end)

    if not slot then
        dump("Soulkeeper item not found")
        return
    end
    local currentCapacity = Souls.api.count("item", slot.item)
    if currentCapacity >= CONFIG.balance.maxCapacity then
        dump("Soulkeeper has max capacity")
        return
    end

    local q = Souls.api.find(caster, 400, { "orphan", "corpse" })
    if q then
        local success = Souls.api.use(q.holderType, q.holder)
        if success then
            Souls.api.store("item", slot.item)

            updateSoulkeeper(caster, slot.item, slot.index)

            BlzStartUnitAbilityCooldown(caster, CONFIG.refs.abilities.main, CONFIG.balance.cooldown)
        else
            dump('Fail on Souls.api.use("corpse", q)')
        end
    else
        dump("No souls found")
    end
end

--- @param info {item: item}
local function onSoulUse(info)
    dump("itemSoulkeeper onSoulUse")
    local item = info.item
    local unit = Souls.api.holder.get(item)
    if not UnitHasItem(unit, item) then
        dump("Invalid Soulkeeper holder data")
        return
    end

    local slot = Unit.findItem(unit, function(i)
        return i == item
    end)
    if not slot then
        dump("Soulkeeper slot not found")
        return
    end
    local currentCooldown = BlzGetUnitAbilityCooldownRemaining(unit, CONFIG.refs.abilities.main)

    updateSoulkeeper(unit, slot.item, slot.index)

    BlzSetUnitAbilityCooldown(unit, CONFIG.refs.abilities.main, 1, currentCooldown)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_PICKUP_ITEM",
            action = onPickUpItem,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DROP_ITEM",
            action = onDropItem,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_PAWN_ITEM",
            action = onPawnItem,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onActivate,
        },
        {
            trigger = "SOUL_USE",
            action = onSoulUse,
        },
    },
    config = CONFIG,
    api = {},
}]=]

P['scenario/factions/mawsworn/abilities/units/accursedStrenth.lua'] = [=[--[[
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.accursedStrength,
            effectDamage = Ids.abilities.accursedStrengthDamage,
            effectSplash = Ids.abilities.accursedStrengthSplash,
        },
        buffs = {
            main = Ids.buffs.accursedStrength,
            damage = Ids.buffs.accursedStrengthDamage,
        },
        units = {
            carrier = { Ids.units.vanguard },
        },
    },
    balance = {
        timerDelta = 0.5,
    },
})

--- @type table<unit, boolean>
local memory = {} -- TODO: save/load

local function onSpell()
    local caster = GetTriggerUnit()

    UnitAddAbility(caster, CONFIG.refs.abilities.effectDamage)
    UnitAddAbility(caster, CONFIG.refs.abilities.effectSplash)

    table.insert(memory, caster)
end

local function removeEffect(unit)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.effectDamage)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.effectSplash)

    UnitRemoveBuffBJ(CONFIG.refs.buffs.damage, unit)
end

--- @param info damageInfo
local function onAfterDamage(info)
    if not info.isAttack then
        return
    end
    if GetUnitAbilityLevel(info.source, CONFIG.refs.abilities.effectDamage) > 0 then
        removeEffect(info.source)
    end
end

local function onTimer()
    local flushQueue = {}
    for _, unit in ipairs(memory) do
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            removeEffect(unit)
            table.insert(flushQueue, unit)
        end
    end
    for _, unit in ipairs(flushQueue) do
        flushQueue[unit] = nil
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell, -- ? cast start
        },
        {
            trigger = "AFTER_DAMAGE",
            filter = { source = CONFIG.refs.units.carrier },
            action = onAfterDamage, -- ? cast start
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.timerDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/units/betrayalSeed.lua'] = [=[--[[
TODO:
- cancel if range has broken during channel
- loyalty trigger
- ? give xp to mawsworn on possess

KNOWN:
- reapplying seed prolongates timer
- different mawsworn player can re-bribe enemy unit if another mawsworn bribed it before
