P['scenario/factions/mawsworn/abilities/units/calcify.lua'] = [=[--[[
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.corrosivePlague")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.calcify,
            slow = Ids.abilities.calcifySlow,
            stun = Ids.abilities.calcifyStun,
        },
        buffs = {
            main = Ids.buffs.calcify,
            slow = Ids.buffs.calcifySlow,
        },
    },
    balance = {
        spreadRadius = 64,
        pulseRate = 1,
        timerDelta = 0.34,
        maxStacks = 3,
    },
})

--- @type table<unit, {owner: player, charges: integer, untilPulse: number}>
local memory = {} -- actively pulsing
--- @type table<unit, {stacks: integer, debuffApplied: boolean}>
local debuffed = {} -- debuff stacks

local function applyEffect(unit, owner)
    if not debuffed[unit] then
        debuffed[unit] = { stacks = 0, debuffApplied = false }
    end
    debuffed[unit].stacks = math.min(CONFIG.balance.maxStacks, debuffed[unit].stacks + 1)

    local stacks = debuffed[unit].stacks
    Dummy.applyDummyOrder(owner, unit, CONFIG.refs.abilities.slow, "slow", math.min(2, stacks))
    if stacks == 3 then
        Dummy.applyDummyOrder(owner, unit, CONFIG.refs.abilities.stun, "thunderbolt")
    end
end

local function onSlow()
    local target = GetSpellTargetUnit()

    debuffed[target].debuffApplied = true
end

local function onSpell()
    local owner = GetOwningPlayer(GetTriggerUnit())
    local target = GetSpellTargetUnit()

    memory[target] = {
        owner = owner, -- WARNING: multiple players casts will overwrite
        charges = 2,
        untilPulse = CONFIG.balance.pulseRate,
    }
end

local function onTimer()
    for target, data in pairs(memory) do
        if not UnitHasBuffBJ(target, CONFIG.refs.buffs.main) then
            memory[target] = nil
            goto continue
        end

        data.untilPulse = data.untilPulse - CONFIG.balance.timerDelta
        if data.untilPulse <= 0 then
            data.untilPulse = data.untilPulse + CONFIG.balance.pulseRate
            data.charges = data.charges - 1
            if data.charges == 0 then
                memory[target] = nil
            end
        end

        local neighbours = Unit.getUnitsInRadius(target, CONFIG.balance.spreadRadius * 2, function(x)
            return not IsUnitAlly(x, data.owner)
        end)
        for _, u in ipairs(neighbours) do
            applyEffect(u, data.owner)
        end
        if #neighbours == 0 then
            --
        end
        ::continue::
    end
end

local function onTimerFlush()
    for target, data in pairs(debuffed) do
        if not UnitHasBuffBJ(target, CONFIG.refs.buffs.slow) then
            debuffed[target] = nil
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.slow,
            action = onSlow,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.timerDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/units/fallenArmamanets.lua'] = [=[--[[
TODO:
- VISUAL BUG: always shows 1 level of aura. effect works correctly
- upgrade reqs
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.fallenArmaments,
            effect = Ids.abilities.fallenArmamentsEffect,
        },
        buffs = {
            ui = Ids.buffs.fallenArmaments,
        },
        units = {
            carrier = { Ids.units.myrmidon, Ids.units.myrmidonFlying },
        },
    },
    balance = {
        maxStacks = 5,
        flushRate = 0.5,
        fadeTime = 3,
    },
})

--- @type table<unit, {buffApplied: boolean, stacks: integer, fadesAt: number}>
local memory = {} -- TODO: save/load

local function applyEffect(unit)
    if not memory[unit] then
        memory[unit] = { buffApplied = true, stacks = 1 }
    end

    memory[unit].fadesAt = GetElapsedGameTime() + CONFIG.balance.fadeTime

    if memory[unit].stacks == CONFIG.balance.maxStacks then
        return
    else
        memory[unit].stacks = math.min(CONFIG.balance.maxStacks, memory[unit].stacks + 1)
        SetUnitAbilityLevel(unit, CONFIG.refs.abilities.effect, memory[unit].stacks)
    end
end

local function removeEffect(unit)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.effect)
    UnitRemoveBuffBJ(CONFIG.refs.buffs.ui, unit)
    memory[unit] = nil
end

--- @param info damageInfo
local function onAfterDamage(info)
    if not info.isAttack then
        return
    end
    if not GetUnitAbilityLevel(info.source, CONFIG.refs.abilities.main) then
        return
    end

    UnitAddAbility(info.source, CONFIG.refs.abilities.effect)
    if UnitHasBuffBJ(info.source, CONFIG.refs.buffs.ui) then -- TODO: review, visible pause between battle start and AA speed stacking
        applyEffect(info.source)
    end
end

local function onTimer()
    for unit, data in pairs(memory) do
        if GetElapsedGameTime() > data.fadesAt then
            removeEffect(unit)
        end
    end
end

return {
    triggers = {
        {
            trigger = "AFTER_DAMAGE",
            filter = { source = CONFIG.refs.units.carrier },
            action = onAfterDamage,
        },
        { trigger = "TIMER", delta = CONFIG.balance.flushRate, action = onTimer },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/units/fallenMorale.lua'] = [=[--[[
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.fallenMorale,
        },
        buffs = {},
        units = {},
    },
    balance = {
        radius = 500,
    },
})

local function onSpell()
    local target = GetSpellTargetUnit()
    local owner = GetOwningPlayer(target)

    local donor
    local maxWs
    for _, unit in
        Unit.getUnitsInRadius(target, CONFIG.balance.radius, function(u)
            return WS.api.has(u) and not IsUnitAlly(u, owner)
        end)
    do
        local ws = WS.api.get(unit)
        if not maxWs or ws > maxWs then
            donor = unit
            maxWs = ws
        end
    end

    if not donor then
        dump("fallenMorale -> no donor with WS found")
        return
    end

    local targetWs = WS.api.get(target)
    local wsDelta = maxWs - targetWs
    if wsDelta <= 0 then
        dump("fallenMorale -> no donor with higher WS found")
        return
    end

    WS.api.applyWeakenedSoulStack(target, wsDelta, owner)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/units/forcedRestitution.lua'] = [=[--[[
