local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.freezeBlood,
        },
        buffs = {
            main = Ids.buffs.freezeBlood,
        },
        units = {},
    },
    balance = {
        checkRate = 0.1,
    },
})

--- @alias FreezeBloodTargetInfo {baseRegen: number, lastHp: number}

--- @type table<unit,FreezeBloodTargetInfo>
local memory = {} -- TODO: save/load

local function onSpell()
    local target = GetSpellTargetUnit()

    local baseRegenRaw = BlzGetUnitRealField(target, UNIT_RF_HIT_POINTS_REGENERATION_RATE)
    memory[target] = {
        baseRegen = baseRegenRaw * CONFIG.balance.checkRate,
        lastHp = GetUnitState(target, UNIT_STATE_LIFE),
    }
    return
end

local function onTimer()
    local flushQueue = {}
    for unit, data in pairs(memory) do
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            table.insert(flushQueue, unit)
        else
            local hp = GetUnitState(unit, UNIT_STATE_LIFE)
            local d = hp - data.lastHp
            if d > 0 and d < (data.baseRegen * 3) then
                SetUnitState(unit, UNIT_STATE_LIFE, data.lastHp)
            else
                data.lastHp = hp
            end
        end
    end
    for _, v in ipairs(flushQueue) do
        memory[v] = nil
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.checkRate,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/units/glare.lua'] = [[-- TODO:
-- - check range from caster, not only from dummy
-- - immunity to "taunt"
-- - adjust numbers in OE and script

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Type = require("utils.type")
local Unit = require("utils.unit")

local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.glare,
            greater = Ids.abilities.glareGreater,
            debuff = Ids.abilities.glareDebuff,
            vision = Ids.abilities.trueSight,
            reveal = Ids.buffs.glareReveal,
        },
        buffs = {
            main = Ids.abilities.glare,
            reveal = Ids.buffs.piercingGazeReveal,
        },
        units = {
            vision = Ids.units.dummyVision,
        },
    },
    balance = {
        castRange = 1000,
        maxRange = 2000,
        castRangeGreater = 2500,
        maxRangeGreater = 5000,
        wsModifierCooldown = 2,
    },
})

--- @type table<unit,{target: unit, dummy: unit, range: number, bonusWsSince: float}>
local memory = {}
--- @type table<unit,unit[]>
local revealed = {}

local function removeEffect(caster)
    local data = memory[caster]
    local target = data.target

    WS.api.modifiers.remove(target, "glare")
    UnitRemoveBuffBJ(CONFIG.refs.buffs.main, target)
    RemoveUnit(data.dummy)
    memory[caster] = nil

    if revealed[target] then
        Generic.removeValue(revealed[target], caster)
        if #revealed[target] == 0 then
            revealed[target] = nil
        end
    end
end

local function startEffect(owner, caster, target)
    local x, y = Generic.pointXY(target)
    ---@diagnostic disable-next-line: param-type-mismatch
    local dummy = CreateUnit(owner, CONFIG.refs.units.vision, x, y, 270)
    UnitAddAbility(dummy, CONFIG.refs.abilities.vision)
    UnitAddAbility(dummy, CONFIG.refs.abilities.reveal)
    Dummy.issueImmediate(dummy, "ORDER") -- TODO

    memory[caster] = { target = target, dummy = dummy }

    if not revealed[target] then
        revealed[target] = {}
    end
    table.insert(revealed[target], caster)

    WS.api.modifiers.add(target, "glare", 1, CONFIG.balance.wsModifierCooldown) -- TODO: visuals callback
end

local function onCast()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local target = GetSpellTargetUnit()

    Timed.call(0.1, function()
        startEffect(owner, caster, target)
    end)
end

local function onCastGreater()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local target = GetSpellTargetUnit()

    if not UnitHasBuffBJ(target, CONFIG.refs.buffs.reveal) then
        dump("Target lacks reveal debuff")
        return
    end

    Timed.call(0.1, function()
        startEffect(owner, caster, target)
    end)
end

local function onEndCast()
    local caster = GetTriggerUnit()
    if not memory[caster] then
        return
    end
    removeEffect(caster)
end

local function onTimer()
    for caster, data in pairs(memory) do
        local target = data.target
        local dummy = data.dummy
        local d = Unit.distance(dummy, target)
        if d > CONFIG.balance.maxRange then
            removeEffect(caster)
        else
            local x, y = Generic.pointXY(target)
            SetUnitPosition(dummy, x, y)
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onCast,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.greater,
            action = onCastGreater,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_ENDCAST",
            spellId = { CONFIG.refs.abilities.main, CONFIG.refs.abilities.greater },
            action = onEndCast,
        },
        { trigger = "TIMER", delta = 0.25, action = onTimer },
    },
    config = CONFIG,
}]]

P['scenario/factions/mawsworn/abilities/units/infusion.lua'] = [[-- - ? AoE dmg on unit detonate
-- - test: multiple infusers on same target
local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Type = require("utils.type")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.infusion,
            buff = Ids.abilities.infusionBuff,
            uiAura = Ids.abilities.infusionUI,
            effect = Ids.abilities.infusionEffect,
        },
        buffs = {
            main = Ids.buffs.infusion,
            ui = Ids.buffs.infusionEffect,
        },
    },
    balance = {
        maxStacks = 5,
        damageBase = 3.5, -- 3, 12, 42, 150, 525
        tickRate = 0.25,
        stacksDelta = 1,
    },
})

--- @type table<unit, {stacks: integer, untilStack: number}>
local memory = {}
--- @type table<unit, unit>
local channels = {}

local function applyEffect(source, unit)
    local data = memory[unit]
    if data.stacks == 0 then
        UnitAddAbility(unit, CONFIG.refs.abilities.uiAura)
        UnitAddAbility(unit, CONFIG.refs.abilities.effect)
    end
    data.stacks = math.min(CONFIG.balance.maxStacks, data.stacks + 1)
    SetUnitAbilityLevel(unit, CONFIG.refs.abilities.effect, data.stacks)

    Damage.apply(
        source,
        unit,
        CONFIG.balance.damageBase ^ data.stacks,
        false,
        false,
        ATTACK_TYPE_CHAOS,
        DAMAGE_TYPE_FIRE
    )
end

local function removeEffect(unit)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.uiAura)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.effect)
    UnitRemoveBuffBJ(CONFIG.refs.buffs.ui, unit)
end

local function onCast()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local target = GetSpellTargetUnit()

    channels[caster] = target
    memory[target] = {
        stacks = 0,
        untilStack = CONFIG.balance.stacksDelta,
    }

    Dummy.applyDummyOrder(owner, target, CONFIG.refs.abilities.buff, "innerfire")
end

local function onBuff()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    applyEffect(caster, target)
end

local function onEndCast()
    local caster = GetTriggerUnit()
    channels[caster] = nil
end

local function onTimer()
    for caster, target in pairs(channels) do
        local owner = GetOwningPlayer(caster)
        local targetData = memory[target]
        targetData.untilStack = math.max(0, targetData.untilStack - CONFIG.balance.tickRate)
        if targetData.untilStack == 0 then
            targetData.untilStack = CONFIG.balance.stacksDelta
            Dummy.applyPoint(owner, target, CONFIG.refs.abilities.buff, "innerfire")
        end
    end
end

local function onTimerFlush()
    for unit, _ in pairs(memory) do
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            removeEffect(unit)
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onCast,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.buff,
            action = onBuff,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_ENDCAST",
            spellId = CONFIG.refs.abilities.main,
            action = onEndCast,
        },
        { trigger = "TIMER", delta = CONFIG.balance.tickRate, action = onTimer },
    },
    config = CONFIG,
}]]

