local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.piercingGaze,
            dummyVision = Ids.abilities.piercingGazeDummyVision,
            glareGreater = Ids.abilities.glareGreater,
        },
        buffs = {
            reveal = Ids.buffs.piercingGazeReveal,
        },
        units = {
            vision = Ids.units.dummyVisionShort,
        },
    },
    balance = {
        timerDelta = 0.5,
        distance = 3000,
        radius = 100,
    },
})

--- @type table<unit, boolean>
local memory = {} -- TODO: save/load

--- @param owner player
--- @param startX number
--- @param startY number
--- @param targetX number
--- @param targetY number
--- @param totalDistance number
--- @param radius number
function revealLineInstant(owner, startX, startY, targetX, targetY, totalDistance, radius)
    local angleInRadians = math.atan(targetY - startY, targetX - startX)

    local duration = 3.0
    local stepDistance = radius * 1.5
    local currentDistance = 0.0

    local someoneFound = false

    while currentDistance < totalDistance do
        local currentX = startX + currentDistance * math.cos(angleInRadians)
        local currentY = startY + currentDistance * math.sin(angleInRadians)
        local point = { x = currentX, y = currentY }

        local modifier = CreateFogModifierRadius(owner, FOG_OF_WAR_VISIBLE, currentX, currentY, radius, true, false)
        FogModifierStart(modifier)

        local dummy = Dummy.create(owner, point, CONFIG.refs.abilities.dummyVision, 1, CONFIG.refs.units.vision)
        Dummy.issueImmediate(dummy, "ORDER")

        if Unit.getNearestUnit(point, radius, function(u)
            return not IsUnitAlly(u, owner)
        end) then
            someoneFound = true
        end

        Timed.call(duration, function()
            DestroyFogModifier(modifier)
        end)

        currentDistance = currentDistance + stepDistance
    end

    return someoneFound
end

local function onGreaterGlareBreak()
    local caster = GetTriggerUnit()
    if GetUnitAbilityLevel(caster, CONFIG.refs.abilities.glareGreater) then
        UnitRemoveAbility(caster, CONFIG.refs.abilities.glareGreater)
        UnitAddAbility(caster, CONFIG.refs.abilities.main)
    end
end

local function onGaze()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local cX, cY = Generic.pointXY(caster)
    local tX = GetSpellTargetX()
    local tY = GetSpellTargetY()

    local someoneFound = revealLineInstant(owner, cX, cY, tX, tY, CONFIG.balance.distance, CONFIG.balance.radius)
    if someoneFound then
        UnitRemoveAbility(caster, CONFIG.refs.abilities.main)
        UnitAddAbility(caster, CONFIG.refs.abilities.glareGreater)
        Timed.call(5, function()
            if GetUnitAbilityLevel(caster, CONFIG.refs.abilities.glareGreater) then
                UnitRemoveAbility(caster, CONFIG.refs.abilities.glareGreater)
                UnitAddAbility(caster, CONFIG.refs.abilities.main)
            end
        end)
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onGaze,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_ENDCAST",
            spellId = CONFIG.refs.abilities.glareGreater,
            action = onGreaterGlareBreak,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/units/shackle.lua'] = [=[--[[
- ? upgrade shackle power
- ? apply shackle power to current HP, not only max (weaker units surrender easier)
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.shackle,
            slow = Ids.abilities.shackleSlow,
        },
        buffs = {},
        units = {},
    },
    balance = {
        timerDelta = 0.5,
        shacklePower = 1000, -- (POWER - TARGET_MAX_HP) / 100 = DURATION -- ? upgradable
        radius = 500, -- TODO: sync with OE
    },
})

--- @type table<unit, {shacklers: unit[]}> -- TODO: save/load
local shackles = {}
--- @type table<unit, {target: unit, charges: integer}> -- TODO: save/load
local shacklers = {}

local function removeShackle(shackler)
    local target = shacklers[shackler].target
    shacklers[shackler] = nil

    Generic.removeValue(shackles[target].shacklers, shackler)
end

local function onSpell()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local target = GetSpellTargetUnit()

    local targetMaxHp = GetUnitState(target, UNIT_STATE_MAX_LIFE)
    local maxDuration = math.min(2, (CONFIG.balance.shacklePower - targetMaxHp) // 100)

    shacklers[caster] = {
        target = target,
        charges = maxDuration, -- int
    }
    if not shackles[target] then
        shackles[target] = {
            shacklers = {},
        }
    end
    table.insert(shackles[target].shacklers, caster)

    -- get max duration, save to memory
    -- onTimer (0.5): check status and distance and duration, apply slow+ws, order stop on limit
    -- (1 shackle effects at time)
    -- ? maybe don't spend duration points if another shackle spends point
    -- onOrder/?onSpellCancel?: change status

    return
end

local function onSpellEndCast()
    local caster = GetTriggerUnit()

    removeShackle(caster)
    return
end

local function onTimer()
    local flushQueue = {}
    for target, data in pairs(shackles) do
        local shackler
        for _, shacklerQ in data.shacklers do
            if Unit.distance(shacklerQ, target) > CONFIG.balance.radius then
                IssueImmediateOrder(shacklerQ, "stop")
                removeShackle(shacklerQ)
            else
                shackler = shacklerQ
            end
        end
        if shackler then
            local owner = GetOwningPlayer(shackler)
            local shacklerData = shacklers[shackler]

            WS.api.applyWeakenedSoulStack(target, 1, owner)
            Dummy.applyDummyOrder(owner, target, CONFIG.refs.abilities.slow, "slow")

            shacklerData.charges = shacklerData.charges - 1
            if shacklerData.charges == 0 then
                IssueImmediateOrder(shackler, "stop")
                removeShackle(shackler)
            end
        else
            flushQueue[target] = true
        end
    end
    for _, v in ipairs(flushQueue) do
        shackles[v] = nil
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell, -- ? cast start
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_ENDCAST",
            spellId = CONFIG.refs.abilities.main,
            action = onSpellEndCast,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.timerDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/units/soulFeast.lua'] = [[local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local removeControl = require("scenario.common.control")
local Type = require("utils.type")
local Unit = require("utils.unit")

local Souls = require("scenario.factions.mawsworn.mechanics.souls")
local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.soulFeast,
            cannibalize = Ids.abilities.soulFeastEat,
        },
    },
    balance = {
        radius = 600,
        searchRadiusPoint = 300,
        requiredUpgradeId = nil,
    },
})

--- @type table<unit, {pointX: number, pointY: number, holderType: string, holder: unit|item}> -- TODO: save/load
local memory = {}

--- @type boolean
local reordering = false

local function periodicOrder(unit, x, y)
    if not memory[unit] then
        return
    end
    if Unit.isAtPoint(unit, x, y, 16) then
        local success = Souls.api.use(memory[unit].holderType, memory[unit].holder)
        memory[unit] = nil
        if not success then
            return
        end
        UnitRemoveAbility(unit, CONFIG.refs.abilities.main)
        UnitAddAbility(unit, CONFIG.refs.abilities.cannibalize)
        if GetUnitState(unit, UNIT_STATE_LIFE) >= BlzGetUnitMaxHP(unit) - 1 then
            SetUnitState(unit, UNIT_STATE_LIFE, BlzGetUnitMaxHP(unit) - 5)
        end
        IssueImmediateOrder(unit, "cannibalize")
    else
        reordering = true
        IssuePointOrder(unit, "move", x, y)
        reordering = false
    end
end

local function onSearchCast()
    local unit = GetTriggerUnit()
    local targetX = GetSpellTargetX()
    local targetY = GetSpellTargetY()

    local soul = Souls.api.find({ x = targetX, y = targetY }, CONFIG.balance.searchRadiusPoint, { "orphan", "corpse" })
    if not soul then
        dump("No soul found")
        return
    end

    local targetClass
    if soul.holderType == "orphan" then
        targetClass = "item"
    else
        targetClass = "unit"
    end
    local x, y = Generic.pointXY(soul.holder, targetClass)

    memory[unit] = {
        pointX = x,
        pointY = y,
        holderType = soul.holderType,
        holder = soul.holder,
    }

    periodicOrder(unit, x, y)
end

local function onCannibalizeEndCast()
    local unit = GetTriggerUnit()
    UnitRemoveAbility(unit, CONFIG.refs.abilities.cannibalize)
    UnitAddAbility(unit, CONFIG.refs.abilities.main)
end

local function onCannibalizeFinish()
    local unit = GetTriggerUnit()
    local owner = GetOwningPlayer(unit)

    for _, target in
        ipairs(Unit.getUnitsInRadius(unit, CONFIG.balance.radius, function(t)
            return not IsUnitAlly(t, owner)
        end))
    do
        WS.api.applyWeakenedSoulStack(target, 1, owner)
    end
end

local function onAnyOrder()
    local unit = GetTriggerUnit()
    if not memory[unit] then
        return
    end
    if not reordering then
        memory[unit] = nil
    end
end

local function onTimer()
    for unit, data in pairs(memory) do
        periodicOrder(unit, data.pointX, data.pointY)
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSearchCast,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_ENDCAST",
            spellId = CONFIG.refs.abilities.cannibalize,
            action = onCannibalizeEndCast,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_FINISH",
            spellId = CONFIG.refs.abilities.cannibalize,
            action = onCannibalizeFinish,
        },
        { trigger = "ORDER", filter = { source = CONFIG.refs.units.carrier }, action = onAnyOrder },
        { trigger = "TIMER", delta = 0.25, action = onTimer },
    },
    config = CONFIG,
}]]

