local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local DispellMeter = require("scenario.common.mechanics.dispellMeter")
local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.vessel,
            dummy = Ids.abilities.vesselDispell,
        },
        buffs = {},
        units = {
            vessel = Ids.units.vessel,
        },
    },
    balance = {
        radius = 200,
        timerDelta = 0.25,
        pulseDelta = 1,
    },
})

--- @type table<unit, {owner: player, charges: integer, untilPulse: number}>
local memory = {} -- TODO: save/load

local function onSpell()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local x = GetSpellTargetX()
    local y = GetSpellTargetY()

    DispellMeter.api.count(
        owner,
        { ability = CONFIG.refs.abilities.dummyDispell, target = { x = x, y = y } },
        { unit = { mp = 1 } },
        --- @param result dispellMeterResult
        function(result)
            if result.unit then
                ---@diagnostic disable-next-line: param-type-mismatch
                local vessel = CreateUnit(owner, CONFIG.refs.units.vessel, x, y, 270)
                memory[vessel] = {
                    owner = owner,
                    charges = math.min(10, result.unit),
                    untilPulse = CONFIG.balance.pulseDelta,
                }
            end
        end
    )
end

local function onTimer()
    local flushQueue = {}
    for vessel, data in pairs(memory) do
        data.untilPulse = math.max(0, data.untilPulse - CONFIG.balance.timerDelta)
        if data.untilPulse <= 0 then
            data.untilPulse = CONFIG.balance.pulseDelta
            for _, target in
                ipairs(Unit.getUnitsInRadius(vessel, CONFIG.balance.radius, function(t)
                    return not IsUnitAlly(t, data.owner) -- TODO and not structure, and not mechanical
                end))
            do
                data.charges = data.charges - 1
                WS.api.applyWeakenedSoulStack(target, 1, data.owner)
                if data.charges == 0 then
                    KillUnit(vessel)
                end
            end
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.timerDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/abilities/units/weaknessHunger.lua'] = [=[--[[
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local WS = require("scenario.factions.mawsworn.mechanics.weakenedSoul")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.weaknessHunger,
        },
        units = {
            carrier = { Ids.units.soulEater },
        },
    },
    balance = {
        bonusDamagePerStack = 2,
    },
})

--- @param info damageInfo
local function onDamage(info)
    if not info.isAttack then
        return
    end
    local stacks = WS.api.get(info.target)
    if not stacks then
        return
    end
    local bonusDamage = stacks * CONFIG.balance.bonusDamagePerStack
    info.damage = info.damage + bonusDamage
    Unit.applyTimedFloatingText(info.target, bonusDamage, "red")
end

return {
    triggers = {
        {
            trigger = "DAMAGE",
            filter = { source = CONFIG.refs.units.carrier },
            action = onDamage,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/mawsworn/mechanics/souls.lua'] = [=[--[[
item holder type = Soulkeeper only

?? any special storage for plain "soul" items?

-- TODO
-- - ADR (orphan~corpse, gorgoa, item, unit)
-- - on "soul" item drop/pickup without soulkeeper -> ... destroy with effect
-- - on "soul" item pickup with soulkeeper -> updateSoulkeeper or drop if full
-- - on "soulkeeper" drop/pickup to cage/forge -> create "soul" item, return "soulkeeper" back
-- - ?? separate method for inventory souls (cage, soulforge)
-- - UI effect on corpse with drained soul
-- - drained corpse decay timer
-- - put soul in cage
-- - search() in items and units
-- - unit sells item -> nullify holder
-- - maybe rewrite to class
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Triggers = require("lib.triggers.callbacks")
local UnitMeta = require("lib.units")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.death")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {},
        buffs = {},
        units = {},
    },
    balance = {},
})

--- Hero spell holders
--- @type table<unit,integer>
local unitHolders = {} -- TODO: save/load
--- @type table<item,integer>
local itemHolders = {}

--- @type table<item,{x: number, y: number}>
local orphanItemHolders = {}

--- @type table<unit,true>
local gorgoaUnits = {}

--- @type table<item,unit>
local itemToUnit = {}
--- @type table<unit,item[]>
local unitToItems = {}

--- @param item item
--- @return unit
local function getItemHolder(item)
    return itemToUnit[item]
end

--- @param unit unit
--- @return item[]
local function getItemsHeld(unit)
    return unitToItems[unit]
end

--- @param item item
--- @return boolean
local function hasOrphanStatus(item)
    return orphanItemHolders[item] ~= nil
end

--- @param unit unit
--- @param item item
--- @param status boolean
local function updateItemHolder(unit, item, status)
    local previousHolder = itemToUnit[item]

    if status then
        itemToUnit[item] = unit
    else
        itemToUnit[item] = nil
    end
    dump("updateItemHolder", unit, item, status, "previousHolder=", previousHolder)

    if previousHolder then
        local previousHolderItems = Generic.filter(unitToItems[previousHolder], function(i)
            return i ~= item
        end)
        if #previousHolderItems > 0 then
            unitToItems[previousHolder] = previousHolderItems
        else
            unitToItems[previousHolder] = nil
        end
    end

    if status then
        if not unitToItems[unit] then
            unitToItems[unit] = {}
        end
        table.insert(unitToItems[unit], item)
    end
end

--- @alias soulSource "orphan"|"gorgoa"|"corpse"|"unit"|"item"

--- @param point {x:number,y:number}
--- @param radius integer
--- @param sources soulSource[]|nil
--- @return {holder:item|unit,holderType:soulSource}|nil
local function findSoul(point, radius, sources)
    -- TODO: optimized search grouping - 1 cycle instead of 2-3
    if not sources then
        sources = { "orphan", "gorgoa", "corpse", "item", "unit" }
    end

    local holder
    local holderType
    for _, source in ipairs(sources) do
        if source == "orphan" then
            local nearestOrphan --- @type item|nil
            local nearestOrphanD --- @type number|nil
            for item, orphanPoint in pairs(orphanItemHolders) do
                local d = Generic.distance(point, orphanPoint)
                if not nearestOrphan or d < nearestOrphanD then
                    nearestOrphan = item
                    nearestOrphanD = d
                end
            end
            if nearestOrphan then
                holder = nearestOrphan
            end
        elseif source == "gorgoa" then
            local nearestOrphan --- @type item|nil
            local nearestOrphanD --- @type number|nil
            for unit, _ in pairs(orphanItemHolders) do
                local d = Generic.distance(point, unit)
                if not nearestOrphan or d < nearestOrphanD then
                    nearestOrphan = unit
                    nearestOrphanD = d
                end
            end
            if nearestOrphan then
                holder = nearestOrphan
            end
        elseif source == "corpse" then
            holder = Unit.getNearestCorpse(point, radius, function(x)
                return Storage:has(x) and Storage:get(x, "soulAvailable") -- remove :has - safe?
            end)
        elseif source == "item" then
            local unit = Unit.getNearestUnit(point, radius, function(x)
                return unitToItems[x]
            end)
            if unit then
                local slot = Unit.findItem(unit, function(i)
                    return itemHolders[i]
                end, true)
                if slot then
                    holder = slot.item
                end
            end
        elseif source == "unit" then
            -- TODO
        end
        if holder then
            holderType = source
            break
        end
    end
    if holder then
        return {
            holder = holder,
            holderType = holderType,
        }
    else
        return nil
    end
end

--- Soft count, returns 0 on not found.
--- @param holderType "unit"|"item"
--- @param holder unit|item
--- @return integer
local function countSouls(holderType, holder)
    dump("countSoul", holderType, holder)
    if holderType == "unit" and unitHolders[holder] then
        return unitHolders[holder]
    elseif holderType == "item" and itemHolders[holder] then
        return itemHolders[holder]
    end
    return 0
end

--- @param holderType soulSource
--- @param holder unit|item
--- @param amount integer|nil
--- @return boolean
local function useSoul(holderType, holder, amount)
    if not amount then
        amount = 1
    end
    dump("useSoul", holderType, holder, amount)
    if holderType == "orphan" and orphanItemHolders[holder] and amount == 1 then
        orphanItemHolders[holder] = nil
        ---@diagnostic disable-next-line: param-type-mismatch
        RemoveItem(holder)
        return true
    elseif holderType == "gorgoa" and gorgoaUnits[holder] and amount == 1 then
        gorgoaUnits[holder] = nil
        ---@diagnostic disable-next-line: param-type-mismatch
        RemoveUnit(holder)
        return true
    elseif holderType == "corpse" and amount == 1 then
        Storage:set(holder, "soulAvailable", false)
        return true
    elseif holderType == "unit" and unitHolders[holder] and unitHolders[holder] >= amount then
        unitHolders[holder] = unitHolders[holder] - amount
        return true
    elseif holderType == "item" and itemHolders[holder] and itemHolders[holder] >= amount then
        itemHolders[holder] = itemHolders[holder] - amount
        Triggers.fireEvent("SOUL_USE", { item = holder })
        dump("fireEvent SOUL_USE")
        return true
    end
    return false
end

--- @param holderType "orphan"|"gorgoa"|"unit"|"item"
--- @param holder unit|item
--- @return boolean
local function storeSoul(holderType, holder)
    if holderType == "orphan" then
        ---@diagnostic disable-next-line: param-type-mismatch
        orphanItemHolders[holder] = { x = GetItemX(holder), y = GetItemY(holder) }
        return true
    elseif holderType == "gorgoa" then
        ---@diagnostic disable-next-line: param-type-mismatch
        gorgoaUnits[holder] = true
        return true
    elseif holderType == "unit" then
        unitHolders[holder] = unitHolders[holder] or 0
        unitHolders[holder] = unitHolders[holder] + 1
        return true
    elseif holderType == "item" then
        itemHolders[holder] = itemHolders[holder] or 0
        itemHolders[holder] = itemHolders[holder] + 1
        return true
    end
    return false
end

--- @param holderType "unit"|"item"
--- @param holderBefore unit|item
--- @param holderAfter unit|item
--- @return boolean
local function remapStorage(holderType, holderBefore, holderAfter)
    if holderType == "unit" then
        unitHolders[holderAfter] = unitHolders[holderBefore]
        unitHolders[holderBefore] = nil
        return true
    elseif holderType == "item" then
        itemHolders[holderAfter] = itemHolders[holderBefore]
        itemHolders[holderBefore] = nil
        return true
    end
    return false
end

return {
    triggers = {},
    config = CONFIG,
    api = {
        count = countSouls,
        find = findSoul,
        use = useSoul,
        store = storeSoul,
        remap = remapStorage,
        holder = {
            get = getItemHolder,
            getItems = getItemsHeld,
            isOrphan = hasOrphanStatus,
            update = updateItemHolder,
        },
    },
}]=]

P['scenario/factions/mawsworn/mechanics/weakenedSoul.lua'] = [=[--[[
-- TODO
-- - prevent spawning lots of dummies on same unit in 1-sec window (prolongate WS/exhaustion debuffs)


-- - - probably reduce WS stacks without dummy rebuff - adjust passive aura only (but buff level will glitch then showing not actual level)
-- - ? optimize by not applying dummy buff EACH time (only when there is at least +1 stack)
-- - visual floating text markers (WS level)
-- - ?? optimize by applying dummy abils only per 0.25-0.5 s ticks (apply if there is delta)
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local UnitMeta = require("lib.units")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.weakenedSoulDebuff,
            ws = Ids.abilities.weakenedSoulEffect,
            exhaustion = Ids.abilities.exhaustionDebuff,
            exhaustionEffect = Ids.abilities.exhaustionEffect,
            neutralize = Ids.abilities.exhaustionNeutralize,
        },
        buffs = {
            dispellMark = Ids.buffs.weakenedSoulDebuff,
            ws = Ids.buffs.weakenedSoulAura,
            exhaustion = Ids.buffs.exhaustion,
            neutralize = Ids.buffs.exhaustionNeutralize,
        },
        units = {},
    },
    balance = {
        flushDelta = 0.2,
        neutralizeDamageIgnoreDuration = 3,
        exhaustionDebuffUpdateDelta = 1,
    },
})

---@alias ExhaustionData { debuffApplied: boolean, dontUpdateExhaustionDebuffUntil: float|nil, neutralizeExpiresAt: float|nil }

--- @type table<unit, boolean>
local memory = {} -- TODO: save/load
--- @type table<unit, ExhaustionData>
local exhausted = {} -- TODO: save/load
local dummyCastQueue = {} -- TODO: save/load

--- @alias ModifierTag "glare"
--- @type table<unit, table<ModifierTag, {modifier: integer, cooldown: integer, availableAt: number}>>
local modifiers = {} -- TODO: save/load

--- @param unit unit
--- @return integer
local function getCurrentWsLevel(unit)
    return GetUnitAbilityLevel(unit, CONFIG.refs.abilities.ws)
end

--- @param unit unit
--- @param stacksDelta integer
--- @param player player | nil Owner of debuff (required only for positive <stacksDelta> values)
local function updateWeakenedSoulState(unit, stacksDelta, player)
    local stacksBefore = getCurrentWsLevel(unit) -- ? save in memory
    local stacks = math.max(0, math.min(10, stacksBefore + stacksDelta))

    if stacks == 0 then
        UnitRemoveAbility(unit, CONFIG.refs.abilities.ws)
        UnitRemoveBuffBJ(CONFIG.refs.buffs.ws, unit)
        memory[unit] = nil
        return
    else
        if not memory[unit] then
            memory[unit] = true
        end

        if stacksBefore == 0 then
            UnitAddAbility(unit, CONFIG.refs.abilities.ws)
        end
        SetUnitAbilityLevel(unit, CONFIG.refs.abilities.ws, stacks)

        if stacks == 10 then
            if not exhausted[unit] then
                exhausted[unit] = {
                    debuffApplied = false,
                    dontUpdateExhaustionDebuffUntil = nil,
                    neutralizeExpiresAt = nil,
                }
            end
            -- apply neutralize only if unit didn't have exhaustion right before
            if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.exhaustion) then
                exhausted[unit].neutralizeExpiresAt = GetElapsedGameTime()
                    + CONFIG.balance.neutralizeDamageIgnoreDuration
                Dummy.applyDummyOrder(player, unit, CONFIG.refs.abilities.neutralize, "thunderbolt")
            end
            -- throttle exhaustion debuff-dummy creation (optimization)
            if
                UnitHasBuffBJ(unit, CONFIG.refs.buffs.dispellMark)
                and (
                    not exhausted[unit].dontUpdateExhaustionDebuffUntil
                    or GetElapsedGameTime() > exhausted[unit].dontUpdateExhaustionDebuffUntil
                )
            then
                Dummy.applyDummyOrder(player, unit, CONFIG.refs.abilities.exhaustion, "acidbomb")
                exhausted[unit].dontUpdateExhaustionDebuffUntil = GetElapsedGameTime()
                    + CONFIG.balance.exhaustionDebuffUpdateDelta
            end
        end
    end
    Unit.applyTimedFloatingText(unit, stacks .. "WS", "purple")
end

--- Add or substract <stacksDelta> stacks of WS, refresh buff duration on add
--- Apply modifiers
--- @param unit unit
--- @param stacksDelta integer
--- @param player player|nil Owner of debuff (required only for positive <stacksDelta> values)
local function applyWeakenedSoulStack(unit, stacksDelta, player)
    if stacksDelta > 0 then
        local mods = modifiers[unit] or {}
        for tag, mod in pairs(mods) do
            local now = GetElapsedGameTime()
            if now > mod.availableAt then
                stacksDelta = stacksDelta + mod.modifier
                modifiers[unit][tag].availableAt = now + mod.cooldown
            end
        end

        local dummy = Dummy.create(player, unit, CONFIG.refs.abilities.main)
        dummyCastQueue[dummy] = stacksDelta
        IssueTargetOrder(dummy, "curse", unit)
    elseif stacksDelta < 0 then
        updateWeakenedSoulState(unit, stacksDelta, player)
    end
end

local function onApplyWeakenedSoulCast()
    -- - ? optimize by bypassing event gets() from trigger service
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local target = GetSpellTargetUnit()

    local delta = dummyCastQueue[caster]
    dummyCastQueue[caster] = nil
    updateWeakenedSoulState(target, delta, owner)
end

local function onApplyExhaustionCast()
    local target = GetSpellTargetUnit()
    Timed.call(0.1, function()
        exhausted[target].debuffApplied = true
        UnitAddAbility(target, CONFIG.refs.abilities.exhaustionEffect)
    end)
end

--- Remove 1 WS stack on each attack to enemy mawsworn.
--- @param info damageInfo
local function onDamageToMawsworn(info)
    if not info.isAttack then
        return
    end
    if UnitMeta.factionOf(info.target) ~= UnitMeta.FACTIONS.mawsworn then
        return
    end
    if IsUnitAlly(info.target, GetOwningPlayer(info.source)) then
        return
    end
    applyWeakenedSoulStack(info.source, -1)
end

--- Remove neutralize stun effect when unit is attacked after <balance.neutralizeDamageIgnoreDuration>
--- @param info damageInfo
local function onDamageToNeutralized(info)
    local unit = info.target
    if not exhausted[unit] then
        return
    end
    local neutralizeExpiresAt = exhausted[unit].neutralizeExpiresAt
    if neutralizeExpiresAt and GetElapsedGameTime() > neutralizeExpiresAt then
        UnitRemoveBuffBJ(CONFIG.refs.buffs.neutralize, unit)
        exhausted[unit].neutralizeExpiresAt = nil
    end
end

local function onTimer()
    -- == Exhaustion flush
    local exhaustionFlushQueue = {}
    for unit, _ in pairs(exhausted) do
        -- remove effect ability when debuff fades
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.exhaustion) then
            UnitRemoveAbility(unit, CONFIG.refs.abilities.exhaustionEffect)
            table.insert(exhaustionFlushQueue, unit)
        end
    end
    for _, unit in ipairs(exhaustionFlushQueue) do
        exhausted[unit] = nil
    end

    -- == WS flush
    local flushQueue = {}
    for unit, _ in pairs(memory) do
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.dispellMark) then
            UnitRemoveAbility(unit, CONFIG.refs.abilities.ws)
            table.insert(flushQueue, unit)
        end
    end
    for _, unit in ipairs(flushQueue) do
        memory[unit] = nil
    end
end

--- modifiers

local function addModifier(target, tag, value, cooldown)
    if not modifiers[target][tag] then
        modifiers[target][tag] =
            { modifier = math.max(0, value), cooldown = cooldown, availableAt = GetElapsedGameTime() }
    end
end

local function removeModifier(target, tag)
    if modifiers[target] and modifiers[target][tag] then
        modifiers[target][tag] = nil
    end
    if not #pairs(modifiers[target]) then
        modifiers[target] = nil
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onApplyWeakenedSoulCast,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.exhaustion,
            action = onApplyExhaustionCast,
        },
        {
            trigger = "DAMAGE",
            action = onDamageToMawsworn,
        },
        {
            trigger = "DAMAGE",
            action = onDamageToNeutralized,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.flushDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
    api = {
        applyWeakenedSoulStack = applyWeakenedSoulStack,
        get = getCurrentWsLevel,
        has = function(t)
            return not not memory[t]
        end,
        isExhausted = function(u)
            return not not exhausted[u]
        end,
        modifiers = {
            add = addModifier,
            remove = removeModifier,
        },
    },
}]=]

P['scenario/factions/necrolord/abilities/allOnOne.lua'] = [=[--[[
TODO:
- maybe UI-visible armor decrease during buff
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.allOnOne,
            effect = Ids.abilities.allOnOneSplash,
        },
        buffs = {
            main = Ids.buffs.allOnOne,
        },
        units = {
            carrier = Ids.units.gladiatorHero,
        },
    },
    balance = {
        flushDelta = 0.2,
        radius = 100,
    },
})

local memory = {} -- TODO: save/load

local function onSpell()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)

    UnitAddAbility(caster, CONFIG.refs.abilities.effect)
    table.insert(memory, caster)

    local targets = Unit.getUnitsInRadius(caster, CONFIG.balance.radius, function(u)
        return IsUnitEnemy(u, owner)
    end)
    for _, target in ipairs(targets) do
        IssueTargetOrder(target, "attack", caster)
    end
end

--- @param info damageInfo
local function onPreDamage(info)
    if not info.isAttack then
        return
    end
    if UnitHasBuffBJ(info.target, CONFIG.refs.buffs.main) then
        info.damageType = DAMAGE_TYPE_ENHANCED
        info.defenseType = GetHandleId(DEFENSE_TYPE_NONE)
    end
end

local function onTimer(info)
    for i = #memory, 1, -1 do
        local unit = memory[i]
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            UnitRemoveAbility(unit, CONFIG.refs.abilities.effect)
            table.remove(memory, i)
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "PRE_DAMAGE",
            filter = { target = CONFIG.refs.units.carrier },
            action = onPreDamage,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.flushDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/necrolord/abilities/ammunitionControl.lua'] = [=[--[[
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.ammunitionControl,
            selfBuff = Ids.abilities.ammunitionControlBuff,
            bonusDamage = Ids.abilities.ammunitionControlBonusDamage,
            bonusArmor = Ids.abilities.ammunitionControlBonusArmor,
        },
        buffs = {
            main = Ids.buffs.ammunitionControl,
        },
        units = {
            carrier = Ids.units.bonesmith,
        },
    },
    balance = {
        radius = 600,
        flushDelta = 0.2,
    },
})

local memory = {} -- todo: save/load persistence

local function onTrain()
    local target = GetTrainedUnit()

    local bonesmiths = Unit.getAllyUnitsInRadius(target, CONFIG.balance.radius, function(u)
        return GetUnitTypeId(u) == CONFIG.refs.units.carrier
    end)
    local caster
    local maxLevel
    for _, bonesmith in ipairs(bonesmiths) do
        local level = GetUnitAbilityLevel(bonesmith, CONFIG.refs.abilities.main)
        if level > 0 and (not maxLevel or level > maxLevel) then
            caster = bonesmith
            maxLevel = level
        end
    end
    if caster == nil then
        return
    end

    local level = maxLevel
    if level > 0 then
        -- visible buff
        UnitAddAbility(target, CONFIG.refs.abilities.selfBuff)
        SetUnitAbilityLevel(target, CONFIG.refs.abilities.selfBuff, level)
        IssueImmediateOrder(target, "berserk")
        UnitRemoveAbility(target, CONFIG.refs.abilities.selfBuff)
        -- passive bonuses
        UnitAddAbility(target, CONFIG.refs.abilities.bonusDamage)
        UnitAddAbility(target, CONFIG.refs.abilities.bonusArmor)
        SetUnitAbilityLevel(target, CONFIG.refs.abilities.bonusDamage, level)
        SetUnitAbilityLevel(target, CONFIG.refs.abilities.bonusArmor, level)
        table.insert(memory, target)
    end
end

local function onTimer()
    for i = #memory, 1, -1 do
        local unit = memory[i]
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            UnitRemoveAbility(unit, CONFIG.refs.abilities.bonusDamage)
            UnitRemoveAbility(unit, CONFIG.refs.abilities.bonusArmor)
            table.remove(memory, i)
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_TRAIN_FINISH",
            action = onTrain,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.flushDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/necrolord/abilities/animateDead.lua'] = [=[--[[
TODO:
- BUG: some mechanical units spawn corpses
- visual effect
- check dispell damage
- revive block mechanic
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.death")
local Triggers = require("lib.triggers.callbacks")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.animateDead,
            empowered = Ids.abilities.animateDeadGreater,
        },
    },
    balance = {
        manaCost = 100,
        searchRadiusPoint = 400,
        -- tuning values
    },
})

local function tryRevive(caster, corpse)
    dump("tryRevive", caster, corpse)
    local owner = GetOwningPlayer(caster)

    Unit.substractMana(caster, CONFIG.balance.manaCost)
    IssueImmediateOrder(caster, "stop")

    if corpse == nil then
        dump("tryRevive nil", corpse)
        Unit.restoreMana(caster, CONFIG.balance.manaCost)
        return false
    end

    local corpseInfo = Storage:bind(corpse)

    dump("tryRevive corpseInfo", corpseInfo)
    if corpseInfo then
        dump("tryRevive corpseInfo.reviveAfter", corpseInfo.reviveAfter)
        if corpseInfo.reviveAfter > 0 then
            corpseInfo.reviveAfter = corpseInfo.reviveAfter - 1
            return false
        end

        local resurrectUnit = corpseInfo.unit
        SetUnitOwner(resurrectUnit, owner, true)
        SetUnitState(resurrectUnit, UNIT_STATE_LIFE, GetUnitState(resurrectUnit, UNIT_STATE_MAX_LIFE))
        SetUnitInvulnerable(resurrectUnit, false)
        ShowUnitShow(resurrectUnit)
        SetUnitUseFood(resurrectUnit, true)
        if not corpseInfo.isPeon then
            UnitRemoveType(resurrectUnit, UNIT_TYPE_PEON)
        end
        Triggers.fireEvent("REVIVE", { source = caster, target = resurrectUnit })
        Storage:drop(corpse)
        RemoveUnit(corpse)
        dump("tryRevive finish")
        return true
    end

    return false
end

local function onCastStart()
    tryRevive(GetTriggerUnit(), GetSpellTargetUnit())
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_CAST",
            spellId = CONFIG.refs.abilities.main,
            action = onCastStart,
        },
    },
    config = CONFIG,
    debug = {
        tryRevive = tryRevive,
    },
}]=]

P['scenario/factions/necrolord/abilities/betterBody.lua'] = [=[--[[
TODO:
- BlzSetUnitMaxMana doesn't work on units which don't have mana initially
- remove possess ability if order cancelled
- fix possession cast time lag (prob won't work now because of unit animation)
- check cast interrupts on stun
- save to "POSSESSED" storage (kyrian loyalty)
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

-- local Storage = require("scenario.storage.sporeCloud")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.betterBody,
            possession = Ids.abilities.betterBodyPossession,
            manaBonus = Ids.abilities.betterBodyPossessionManaBonus,
            --
            applyLimb = Ids.abilities.applyLimb, -- TODO: add abilities with different hotkeys
            scissorSoul = Ids.abilities.scissorSoul,
        },
        buffs = {
            --
        },
        units = {
            --
        },
    },
    balance = {
        --
    },
})

local memory = {} -- TODO: save/load

local function onSpellCast()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    memory[caster] = target
end

local function onSpellFinish()
    local caster = GetTriggerUnit()
    local target = memory[caster]

    -- Unit.face(caster, target)
    UnitAddAbility(caster, CONFIG.refs.abilities.possession)
    local pos = IssueTargetOrder(caster, "possession", target)
    -- UnitRemoveAbility(caster, CONFIG.refs.abilities.possession) -- TODO: hide active ability, remove on cast or after short delay
end

local function onPossession()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()

    local casterMaxMana = GetUnitState(caster, UNIT_STATE_MAX_MANA)
    local targetMaxMana = GetUnitState(target, UNIT_STATE_MAX_MANA)

    dump("onPossession casterMaxMana", casterMaxMana)
    dump("onPossession targetMaxMana", targetMaxMana)
    if targetMaxMana < casterMaxMana then
        if targetMaxMana == 0 then
            local m = UnitAddAbility(target, CONFIG.refs.abilities.manaBonus)
            dump("onPossession UnitAddAbility", m)
        end
        BlzSetUnitMaxMana(target, casterMaxMana)
    end

    local abilities = { CONFIG.refs.abilities.applyLimb, CONFIG.refs.abilities.scissorSoul, CONFIG.refs.abilities.main }
    for _, a in ipairs(abilities) do
        if GetUnitAbilityLevel(target, a) == 0 then
            UnitAddAbility(target, a)
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpellCast,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_FINISH",
            spellId = CONFIG.refs.abilities.main,
            action = onSpellFinish,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.possession,
            action = onPossession,
        },
    },
    config = CONFIG,
}]=]

