P['scenario/factions/necrolord/abilities/brutalCombo.lua'] = [=[--[[
TODO:
- fade with stale time
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.brutalCombo,
        },
        units = {
            carrier = Ids.units.gladiatorHero,
        },
    },
    balance = {
        critModifier = { 1.6, 2, 2.4 },
    },
})

local memory = {} -- TODO: save/load

local function onPreDamage(info)
    if not info.isAttack then
        return
    end

    local unit = info.source
    local level = GetUnitAbilityLevel(unit, CONFIG.refs.abilities.main)
    if level == 0 then
        return
    end

    if memory[unit] == nil then
        memory[unit] = 1 -- attacks before crit
    elseif memory[unit] > 0 then
        memory[unit] = memory[unit] - 1
    elseif memory[unit] == 0 then
        memory[unit] = 2

        local before = info.damage
        info.damage = info.damage * CONFIG.balance.critModifier[level]
        dump("brutalCombo hit - ", before, "->", info.damage)
        -- Create the classic red floating text
        local text = CreateTextTagUnitBJ(string.format("%.0f!", info.damage), info.target, 0, 10, 100, 0, 0, 0)
        SetTextTagVelocityBJ(text, 64, 90)
        SetTextTagPermanent(text, false)
        SetTextTagLifespan(text, 2.0)
        SetTextTagFadepoint(text, 1.5)
    else
        error("Broken brutalCombo memory value")
    end
end

return {
    triggers = {
        {
            trigger = "PRE_DAMAGE",
            filter = { source = CONFIG.refs.units.carrier },
            action = onPreDamage,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/necrolord/abilities/combatExpertise.lua'] = [[-- TODO:
-- - ? filter ally death
local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Unit = require("utils.unit")

local Store = require("scenario.storage.combatExpertise")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.combatExpertise,
            damageBuff = Ids.abilities.combatExpertiseDamage,
            -- TODO: final passive for max level
        },
        units = {
            carrier = Ids.units.animateWarrior,
        },
    },
    balance = {
        maxLevel = 5,
        radius = 300,
    },
})

local function updateAbility(unit, level)
    if GetUnitAbilityLevel(unit, CONFIG.refs.abilities.damageBuff) < 1 then
        UnitAddAbility(unit, CONFIG.refs.abilities.damageBuff)
    end
    SetUnitAbilityLevel(unit, CONFIG.refs.abilities.damageBuff, level)
end

local function onDeath(unit)
    if unit == nil then
        unit = GetDyingUnit()
    end

    if GetUnitTypeId(unit) == CONFIG.refs.units.carrier then
        Store:drop(unit)
        return
    end

    local nearbyAnimates = Unit.getUnitsInRadius(unit, CONFIG.balance.radius, function(u)
        return GetUnitTypeId(u) == CONFIG.refs.units.carrier
    end)
    for _, carrier in ipairs(nearbyAnimates) do
        if not Store:has(carrier) then
            Store:set(carrier, "buffLevel", 0)
            Store:set(carrier, "frags", 0)
        end
        local stat = Store:bind(carrier)
        if stat and stat.buffLevel < CONFIG.balance.maxLevel then
            stat.frags = stat.frags + 1
            local newLevel = math.min(stat.frags // 2, CONFIG.balance.maxLevel)
            if newLevel > stat.buffLevel then
                stat.buffLevel = newLevel
                updateAbility(carrier, stat.buffLevel)
            end
        end
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_DEATH",
            action = onDeath,
        },
    },
    config = CONFIG,
    debug = {
        onDeath = onDeath,
    },
}]]

P['scenario/factions/necrolord/abilities/concoctPotion.lua'] = [=[--[[
TODO:
- timed life for potions
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

-- PotionStorage -- timedlife
local StorageFrenzy = require("scenario.storage.frenzyPotion")
local StorageHealing = require("scenario.storage.healingPotion")
local DeathStorage = require("scenario.storage.death")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            explosivePotion = Ids.abilities.concoctPotionExplosive,
            healPotion = Ids.abilities.concoctPotionHealing,
            frenzyPotion = Ids.abilities.concoctPotionFrenzy,
            --
            explosiveOrder = Ids.abilities.concoctedExplosionActive,
            healingOrder = Ids.abilities.concoctedHealingActive,
            frenzyOrder = Ids.abilities.concoctedFrenzyActive,
            --
            explosionDummy = Ids.abilities.concoctedExplosionDummy,
            healStunDummy = Ids.abilities.concoctedHealingStunDummy,
            healDummy = Ids.abilities.concoctedHealingRejuvDummy,
            frenzyPassive = Ids.abilities.concoctedFrenzyPassiveDoom,
        },
        buffs = {
            healingStun = Ids.buffs.concoctedHealingStun,
            healing = Ids.buffs.concoctedHealingRejuv,
        },
        units = {
            --
        },
        items = {
            explosive = Ids.items.explosivePotion,
            healing = Ids.items.healingPotion,
            frenzy = Ids.items.frenzyPotion,
        },
    },
    balance = {
        frenzyDoomMaxLevel = 5,
    },
})

local CONCOCT_TABLE = {
    [CONFIG.refs.abilities.explosivePotion] = CONFIG.refs.items.explosive,
    [CONFIG.refs.abilities.healPotion] = CONFIG.refs.items.healing,
    [CONFIG.refs.abilities.frenzyPotion] = CONFIG.refs.items.frenzy,
}

local function activateExplosivePotion(owner, caster)
    if caster == nil then
        caster = GetTriggerUnit()
    end
    if owner == nil then
        owner = GetOwningPlayer(caster)
    end

    local dummy = Dummy.create(owner, caster, CONFIG.refs.abilities.explosionDummy)
    IssueTargetOrder(dummy, "selfdestruct", dummy)
end

local function activateHealingPotion()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    Dummy.applyDummyOrder(owner, caster, CONFIG.refs.abilities.healStunDummy, "thunderbolt")
    Dummy.applyDummyOrder(owner, caster, CONFIG.refs.abilities.healDummy, "rejuvination")
    StorageHealing:add(caster)
end

local function activateFrenzyPotion()
    local caster = GetTriggerUnit()
    UnitAddAbility(caster, CONFIG.refs.abilities.frenzyPassive)
    StorageFrenzy:add(caster)
end

local function onConcoct()
    local target = GetSpellTargetUnit()
    local spellId = GetSpellAbilityId()

    local itemId = CONCOCT_TABLE[spellId]
    UnitAddItemById(target, itemId)
end

local function onLethalDamage(info)
    if UnitHasItemOfTypeBJ(info.target, CONFIG.refs.items.explosive) then
        dump("onLethalDamage activateExplosivePotion")
        local owner = Player(DeathStorage:get(info.target, "originalOwner"))
        activateExplosivePotion(owner, info.target)
    end
end

local function onTimer()
    -- TODO: beware to keep debuff skill on morph (currently it will drop most likely)
    StorageFrenzy:each(function(unit)
        SetUnitAbilityLevel(
            unit,
            CONFIG.refs.abilities.frenzyPassive,
            math.min(
                CONFIG.balance.frenzyDoomMaxLevel,
                GetUnitAbilityLevel(unit, CONFIG.refs.abilities.frenzyPassive) + 1
            )
        )
    end)
    StorageHealing:each(function(unit)
        if Unit.isHealthFull(unit) then
            StorageHealing:drop(unit)
        end
    end)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = {
                CONFIG.refs.abilities.explosivePotion,
                CONFIG.refs.abilities.healPotion,
                CONFIG.refs.abilities.frenzyPotion,
            },
            action = onConcoct,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.explosiveOrder,
            action = activateExplosivePotion,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.healingOrder,
            action = activateHealingPotion,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.frenzyOrder,
            action = activateFrenzyPotion,
        },
        {
            trigger = "LETHAL_DAMAGE",
            action = onLethalDamage,
        },
        {
            trigger = "TIMER",
            delta = 1,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/necrolord/abilities/corrosivePlague.lua'] = [=[--[[
TODO:
- WARNING - won't work on undead because of disease cloud hardcode
- check duration (must be almost infinite now); beware infinite spread reapply duration refresh


apply plague buff to target (curse or smth)
add plague cloud OE ability + -armor to target
store disased to memory
timer scan nearby units around diseased
add ability + add to memory

timer check plague cloud buff, remove debuffs if dispelled
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.corrosivePlague")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.corrosivePlague,
            disease = Ids.abilities.corrosivePlagueSpread,
            debuff = Ids.abilities.corrosivePlagueArmorDebuff,
        },
        buffs = {
            main = Ids.buffs.corrosivePlague,
        },
    },
    balance = {
        spreadRadius = 64,
    },
})

local memory = {}

local function applyDisease(unit, owner)
    -- dump("applyDisease", unit, GetUnitName(unit), unit, GetUnitRace(unit), GetUnitRace(unit) == RACE_UNDEAD)
    if GetUnitAbilityLevel(unit, CONFIG.refs.abilities.disease) == 0 then
        local r1 = UnitAddAbility(unit, CONFIG.refs.abilities.debuff)
        local r2 = UnitAddAbility(unit, CONFIG.refs.abilities.disease)
        -- dump("applyDisease -armor", r1, r2)
        Storage:set(unit, "owner", GetPlayerId(owner))
    end
end

local function cleanseDisease(unit)
    -- dump("cleanseDisease", unit, GetUnitName(unit), unit, GetUnitRace(unit), GetUnitRace(unit) == RACE_UNDEAD)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.debuff)
    UnitRemoveAbility(unit, CONFIG.refs.abilities.disease)
    Storage:drop(unit)
end

local function onSpell()
    local owner = GetOwningPlayer(GetTriggerUnit())
    local target = GetSpellTargetUnit()
    applyDisease(target, owner)
end

local function onTimerSpread()
    Storage:each(function(unit)
        if UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            local owner = Player(Storage:get(unit, "owner")) -- TODO: ensure player N correct
            for _, u in
                ipairs(Unit.getUnitsInRadius(unit, CONFIG.balance.spreadRadius * 2, function(x)
                    return not Storage:has(x)
                        and not IsUnitAlly(x, owner)
                        and not UnitHasBuffBJ(x, CONFIG.refs.buffs.main)
                        and GetUnitRace(x) ~= RACE_UNDEAD
                end))
            do
                applyDisease(u, owner)
            end
        end
    end)
end

local function onTimerCleanse()
    Storage:each(function(unit)
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            cleanseDisease(unit)
        end
    end)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "TIMER",
            delta = 0.2,
            action = onTimerCleanse,
        },
        {
            trigger = "TIMER",
            delta = 0.5,
            action = onTimerSpread,
        },
    },
    config = CONFIG,
}]=]

