P['scenario/factions/necrolord/abilities/forgeboneReveries.lua'] = [=[--[[
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.forgeboneReveries,
        },
        buffs = {
            main = Ids.buffs.forgeboneReveries,
        },
    },
    balance = {
        flushDelta = 0.2,
    },
})

local memory = {} -- dies after buff fades or not; TODO: save/load

local function onSpell()
    local target = GetSpellTargetUnit()

    Timed.call(0.03, function()
        -- dump("forgebone has buff", UnitHasBuffBJ(target, CONFIG.refs.buffs.main))
        memory[target] = true
    end)
end

local function onDamage(info)
    -- dump("forgebone onDamage! info.damage=", info.damage)
    if not UnitHasBuffBJ(info.target, CONFIG.refs.buffs.main) then
        return
    end
    -- dump("forgebone onDamage! save")
    local life = GetUnitState(info.target, UNIT_STATE_LIFE)
    if life - info.damage < 1 then
        info.damage = math.max(0, life - 1)
    end
end

local function onLethalDamage(info)
    if memory[info.source] then
        memory[info.source] = false
    end
end

local function onTimer(info)
    local flushQueue = {}
    for unit, dies in pairs(memory) do
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then -- buff not ready right after effect?
            if dies then
                Damage.apply(unit, unit, 99999, false, false, ATTACK_TYPE_CHAOS, DAMAGE_TYPE_ENHANCED)
            end
            table.insert(flushQueue, unit)
        end
    end
    for _, unit in ipairs(flushQueue) do
        memory[unit] = nil
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "DAMAGE",
            action = onDamage,
        },
        {
            trigger = "LETHAL_DAMAGE",
            action = onLethalDamage,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.flushDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/necrolord/abilities/healingSlime.lua'] = [=[--[[
TODO:
- test change base to heal with long duration -> autocast slimes
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.healingSlime")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.healingSlime,
        },
        buffs = {
            main = Ids.buffs.healingSlime,
        },
    },
    balance = {
        shield = 100, -- max damage soaked
    },
})

local function onSpell()
    local target = GetSpellTargetUnit()
    Storage:set(target, "shieldAmount", CONFIG.balance.shield)
end

local function onDamage(info)
    local shieldAmount = Storage:get(info.target, "shieldAmount")
    if shieldAmount then
        local soaked = math.min(info.damage, shieldAmount)
        info.damage = info.damage - soaked

        if soaked == shieldAmount then
            UnitRemoveBuffBJ(CONFIG.refs.buffs.main, info.target)
            Storage:drop(info.target)
        else
            Storage:set(info.target, "shieldAmount", shieldAmount - soaked)
        end
    end
end

local function onTimer()
    Storage:each(function(unit)
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            Storage:drop(unit)
        end
    end)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "DAMAGE",
            action = onDamage,
        },
        {
            trigger = "TIMER",
            delta = 0.5,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/necrolord/abilities/moldWeakness.lua'] = [=[--[[
TODO:
- grey floating text with decreased damage
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.moldWeakness,
            debuff = Ids.abilities.moldWeaknessDebuff,
        },
        buffs = {
            aim = Ids.buffs.moldWeaknessAim,
            debuff = Ids.buffs.moldWeakness,
        },
    },
    balance = {
        damageDecrease = { 0.3, 0.6, 1 },
        flushDelta = 1,
        duration = 8,
    },
})

local memory = {} -- todo: save/load persistence
local debuffed = {} -- todo: save/load persistence

local function onSpell()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    local spell = GetSpellAbilityId()
    local level = GetUnitAbilityLevel(caster, spell)
    memory[target] = level
end

local function onDummySpell()
    local caster = GetTriggerUnit()
    local target = GetSpellTargetUnit()
    local spell = GetSpellAbilityId()
    local level = GetUnitAbilityLevel(caster, spell)
    memory[target] = level

    debuffed[target] = level
end

local function onDamage(info)
    if not info.isAttack then
        return
    end
    if UnitHasBuffBJ(info.target, CONFIG.refs.buffs.aim) then
        local owner = GetOwningPlayer(info.source)
        local level = memory[info.target]
        UnitRemoveBuffBJ(CONFIG.refs.buffs.aim, info.target)

        Dummy.applyDummyOrder(owner, info.target, CONFIG.refs.abilities.debuff, "acidbomb", level)
        memory[info.target] = nil
    end
    if UnitHasBuffBJ(info.source, CONFIG.refs.buffs.debuff) then
        local decrease = CONFIG.balance.damageDecrease[debuffed[info.source]]
        info.damage = info.damage - (info.damage * decrease)
    end
end

local function onTimer()
    local flushQueue = {}
    for unit, _ in pairs(debuffed) do
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.debuff) then
            table.insert(flushQueue, unit)
        end
    end
    for _, unit in ipairs(flushQueue) do
        debuffed[unit] = nil
    end
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.debuff,
            action = onDummySpell,
        },
        {
            trigger = "DAMAGE",
            action = onDamage,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.flushDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

