P['scenario/factions/necrolord/abilities/opressiveBanner.lua'] = [=[--[[
TODO:
- visual effect for banner shield
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.opressiveBanner,
            aura = Ids.abilities.opressiveBannerAura,
            shield = Ids.abilities.opressiveBannerShield,
        },
        buffs = {
            shield = Ids.buffs.opressiveBannerShield,
        },
        units = {
            banner = Ids.units.opressiveBanner,
        },
    },
    balance = {
        shieldTime = 3,
        shieldCapacity = { 50, 100, 150 },
    },
})

local memory = {} -- todo: save/load
local spawnQueue = {}

local function onSpell()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)

    local x = GetSpellTargetX()
    local y = GetSpellTargetY()
    local level = GetUnitAbilityLevel(caster, CONFIG.refs.abilities.main)

    ---@diagnostic disable-next-line: param-type-mismatch
    local banner = CreateUnit(owner, CONFIG.refs.units.banner, x, y, 270)
    Unit.applyTimedLife(banner, 60)
    UnitAddAbility(banner, CONFIG.refs.abilities.aura)
    UnitAddAbility(banner, CONFIG.refs.abilities.shield)
    SetUnitAbilityLevel(banner, CONFIG.refs.abilities.aura, level)
    SetUnitAbilityLevel(banner, CONFIG.refs.abilities.shield, level)
    memory[banner] = {
        shield = CONFIG.balance.shieldCapacity[level],
    }
end

local function onDamage(info)
    if not memory[info.target] then
        return
    end

    local shield = memory[info.target].shield
    local blocked = math.min(shield, info.damage)

    info.damage = info.damage - blocked

    if blocked >= shield then
        memory[info.target] = nil
    else
        memory[info.target].shield = shield - blocked
    end
end

local function onDeath()
    memory[GetDyingUnit()] = nil
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "DAMAGE",
            filter = { target = CONFIG.refs.units.banner },
            action = onDamage,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DEATH",
            filter = { target = CONFIG.refs.units.banner },
            action = onDeath,
        },
    },
    config = CONFIG,
}]=]

P['scenario/factions/necrolord/abilities/scavengerCorpses.lua'] = [[-- TODO:
-- - cyclic scavenge until different order (-2 hp before to enable it)
-- - create corpse on drop
-- - preserve corpse lifetime if not in body banks
-- - ? different storage model (now corpse is PK and it recreates)
-- - ? pause&hide picked corpse, move&show dropped corpse
local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Slugs = require("lib.slugs")
local Items = require("lib.items")
local Unit = require("utils.unit")

local ScavengerStore = require("scenario.storage.scavenger")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            search = Ids.abilities.collectCorpsesSearch,
            collect = Ids.abilities.collectCorpses,
            toggle = Ids.abilities.collectCorpsesToggle,
            drop = Ids.abilities.dropCorpses,
        },
        units = {
            carrier = Ids.units.scavenger,
        },
    },
    balance = {
        radius = 600,
        tickSeconds = 1,
        linkRadius = 275,
    },
})

local function onCollect(unit)
    dump("onCollect run")
    local caster = GetTriggerUnit()
    local corpse = GetSpellTargetUnit()
    local slug = Slugs.unit(GetUnitTypeId(corpse)) -- "steward"
    -- unit handle → corpse item type id
    local itemTypeId = Items.getCorpseItemId(GetUnitTypeId(corpse))
    dump("onCollect GetUnitTypeId(corpse)", GetUnitTypeId(corpse))
    if not itemTypeId then
        dump("onCollect itemTypeId =", itemTypeId)
        -- TODO: error
        return
    end
    UnitAddItem(caster, CreateItem(itemTypeId, GetUnitX(corpse), GetUnitY(corpse)))
end

local function onTrain(unit)
    if unit == nil then
        unit = GetTrainedUnit()
    end
    ScavengerStore:add(unit)
end

local function onDeath(unit)
    if unit == nil then
        unit = GetDyingUnit()
    end
    ScavengerStore:drop(unit)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_CAST",
            spellId = CONFIG.refs.abilities.collect,
            action = onCollect,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_TRAIN_FINISH",
            filter = { target = CONFIG.refs.units.carrier },
            action = onTrain,
        },
        {
            trigger = "EVENT_PLAYER_UNIT_DEATH",
            filter = { target = CONFIG.refs.units.carrier },
            action = onDeath,
        },
    },
    config = CONFIG,
}]]

P['scenario/factions/necrolord/abilities/scissorSoul.lua'] = [=[--[[
TODO:
- add delay
]]

local Ids = require("data.ids")
local AbilityConfig = require("lib.ability.config")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local Storage = require("scenario.storage.regenBlock")

local CONFIG = AbilityConfig.compile({
    refs = {
        abilities = {
            main = Ids.abilities.scissorSoul,
            dummy = Ids.abilities.scissorSoulDummy,
            burn = Ids.abilities.scissorSoulManaBurn,
        },
        buffs = {
            main = Ids.buffs.scissorSoul,
        },
        units = {
            --
        },
    },
    balance = {
        decaySpeed = 25, -- per second
        tickDelta = 0.03,
    },
})
local DECAY_PER_TICK = CONFIG.balance.decaySpeed * CONFIG.balance.tickDelta

local function onSpell()
    local caster = GetTriggerUnit()
    local owner = GetOwningPlayer(caster)
    local target = GetSpellTargetUnit()

    Dummy.applyDummyOrder(owner, target, CONFIG.refs.abilities.dummy, "acidbomb")
    Dummy.applyDummyAttack(owner, target, CONFIG.refs.abilities.burn)
end

local function afterDummyAttack(info)
    if GetUnitAbilityLevel(info.source, CONFIG.refs.abilities.burn) > 0 then
        RemoveUnit(info.source)

        Storage:set(info.target, "type", 2)
        Storage:set(info.target, "frozenAmount", GetUnitState(info.target, UNIT_STATE_MANA))
    end
end

local function onTimer()
    Storage:each(function(unit)
        local status = Storage:bind(unit)
        if not UnitHasBuffBJ(unit, CONFIG.refs.buffs.main) then
            Storage:drop(unit)
        elseif status and status.type == 2 then
            local currentMana = GetUnitState(unit, UNIT_STATE_MANA)
            if currentMana > status.frozenAmount then
                local mana = math.max(status.frozenAmount, currentMana - DECAY_PER_TICK)
                SetUnitState(unit, UNIT_STATE_MANA, mana)
            elseif currentMana < status.frozenAmount then
                status.frozenAmount = currentMana
            end
        end
    end)
end

return {
    triggers = {
        {
            trigger = "EVENT_PLAYER_UNIT_SPELL_EFFECT",
            spellId = CONFIG.refs.abilities.main,
            action = onSpell,
        },
        {
            trigger = "AFTER_DAMAGE",
            filter = { source = CONFIG.refs.units.dummyAttack },
            action = afterDummyAttack,
        },
        {
            trigger = "TIMER",
            delta = CONFIG.balance.tickDelta,
            action = onTimer,
        },
    },
    config = CONFIG,
}]=]

