P['spawn.lua'] = [[local Ids = require("data.ids")
local Units = require("data.units")
local Triggers = require("lib.triggers.callbacks")
local Dummy = require("utils.dummy")
local Unit = require("utils.unit")

local DeathStorage = require("scenario.storage.death")

local x, y, f = 219.4, -90.4, 293.630
local p0, p1 = Player(0), Player(1)

local skip = {
    aspirantMelee = true,
    memorySpirit = true,
    warBanner = true,
    opressiveBanner = true,
}

local function shouldSpawn(slug, row)
    if row.class == "building" then
        return false
    end
    if skip[slug] then
        return false
    end
    if slug:find("Flying") then
        return false
    end
    if slug:find("^ascended") then
        return false
    end
    return true
end

local function spawnSlug(player, slug, row)
    local id = Ids.units[slug]
    if not id then
        return
    end

    local unit = CreateUnit(player, FourCC(id), x, y, f)
    Triggers.fireEvent("CREATE", { target = unit })

    if row.heroAbilities then
        -- SetHeroLevel(unit, 10, false)
    end
    if slug == "phalynx" then
        require("scenario.storage.phalynx"):add(unit)
    end
end

local CORPSE_CLUSTER_RADIUS = 56

local kyrianCorpses = { "aspirant", "larion", "purity", "wisdom", "loyalty" }
local necrolordCorpses = { "animateWarrior", "gladiator", "scavenger", "necromancer", "bonestorm" }

local function finishFakeDeath(unit, px, py)
    Timed.call(0.1, function()
        for _, corpse in ipairs(Unit.getCorpsesInRadius({ x = px, y = py }, 48)) do
            local info = DeathStorage:bind(corpse)
            if info and info.unit == unit then
                -- UnitSuspendDecay(corpse, true)
                -- DeathStorage:set(corpse, "reviveAfter", 0)
                return
            end
        end
    end)
end

local function spawnCorpseCluster(player, slugs, centerX, centerY)
    local count = #slugs
    for i, slug in ipairs(slugs) do
        local id = Ids.units[slug]
        if id then
            local angle = (i - 1) * (360 / count)
            local rad = math.rad(angle)
            local px = centerX + CORPSE_CLUSTER_RADIUS * math.cos(rad)
            local py = centerY + CORPSE_CLUSTER_RADIUS * math.sin(rad)
            local unit = CreateUnit(player, FourCC(id), px, py, GetRandomReal(0, 360))
            Damage.apply(unit, unit, 99999, false, false, ATTACK_TYPE_CHAOS, DAMAGE_TYPE_ENHANCED)
            -- finishFakeDeath(unit, px, py)
        end
    end
end

local function spawnFaction(faction)
    local slugs = {}
    for slug, row in pairs(Units) do
        if row.faction == faction and shouldSpawn(slug, row) then
            slugs[#slugs + 1] = slug
        end
    end
    table.sort(slugs)

    for _, slug in ipairs(slugs) do
        spawnSlug(p0, slug, Units[slug])
    end
end

local packs = {
    kyrian = function()
        spawnFaction("kyrian")
    end,
    necrolord = function()
        spawnFaction("necrolord")
    end,
    fae = function()
        spawnFaction("fae")
    end,
    venthyr = function()
        spawnFaction("venthyr")
    end,
    mawsworn = function()
        CreateUnit(p0, FourCC(Ids.units.mawswornCage), x - 50, y - 50, f)
        CreateUnit(p0, FourCC(Ids.units.mawswornMechBarracks), x + 200, y + 200, f)
        CreateItem(FourCC(Ids.items.soulkeeper0), x, y)
        spawnFaction("mawsworn")
    end,
    corpses = function()
        spawnCorpseCluster(p1, kyrianCorpses, x - 180, y)
        spawnCorpseCluster(p1, necrolordCorpses, x + 180, y)
    end,
    enemies = function()
        CreateUnit(p1, FourCC(Ids.units.aspirant), -1000.4, y, f)
        CreateUnit(p1, FourCC(Ids.units.aspirant), -1000.4, y, f)
        CreateUnit(p1, FourCC(Ids.units.shade), -1000.4, y, f)

        local i = CreateUnit(p1, FourCC(Ids.units.dummyInvis), -1000.4, y, f)
        IssueImmediateOrder(i, "windwalk")
        IssueImmediateOrder(i, "hold")

        local e = CreateUnit(p1, FourCC(Ids.units.aspirant), x, y, f)
        BlzSetUnitMaxHP(e, 1)

        local g = CreateUnit(p0, FourCC(Ids.units.footman), x, y, f)
        SetUnitState(g, UNIT_STATE_LIFE, 1)
        local g = CreateUnit(p0, FourCC(Ids.units.footman), x, y, f)
        SetUnitState(g, UNIT_STATE_LIFE, 1)
        local g = CreateUnit(p0, FourCC(Ids.units.footman), x, y, f)
        SetUnitState(g, UNIT_STATE_LIFE, 1)

        CreateItemLoc(FourCC(Ids.items.dummyHeroItem), Location(200, -100))

        local footman = CreateUnit(p1, FourCC(Ids.units.footman), -1500.4, y + 1000, f)
        BlzSetUnitMaxMana(footman, 300)

        local t = CreateUnit(p1, FourCC(Ids.units.dummyTank), x, y + 1500, f)
        -- Dummy.applyDummyOrder(p0, t, FourCC(Ids.abilities.exhaustionDebuff), "acidbomb")
        CreateUnit(p1, FourCC(Ids.units.priest), x, y + 1500, f)
        CreateUnit(p1, FourCC(Ids.units.priest), x, y + 1500, f)
        -- CreateUnit(p1, FourCC(Ids.units.priest), x, y + 1500, f)
        local p = CreateUnit(p1, FourCC(Ids.units.priest), x, y + 1500, f)
        SetUnitState(p, UNIT_STATE_MAX_MANA, 1)
        BlzSetUnitMaxMana(p, 0)
    end,
}

local function run(names)
    Debug.original.print("Hello warcraft-vscode !")

    for _, name in ipairs(names) do
        local pack = packs[name]
        if not pack then
            error("unknown spawn pack: " .. tostring(name))
        end
        pack()
    end

    Debug.original.print("IngameConsole:", IngameConsole ~= nil)

    SetPlayerState(p0, PLAYER_STATE_RESOURCE_GOLD, 100000)
    SetPlayerState(p0, PLAYER_STATE_RESOURCE_LUMBER, 100000)
    SetPlayerState(p0, PLAYER_STATE_RESOURCE_FOOD_CAP, 70)
end

return {
    run = run,
}]]

P['tests/data/items.lua'] = [[local Ids = require("data.ids")
local Items = require("lib.items")
local T = require("tests.support.runner").suite("items")

T:test("stewardCorpse maps back to steward unit", function(case)
    local item = case:createItem(Ids.items.stewardCorpse)
    assert(Items.getCorpseOf(GetItemTypeId(item)) == "steward")
end)

T:test("steward unit maps to stewardCorpse item", function(case)
    local unit = case:createUnit(Ids.units.steward)
    assert(Items.getCorpseItemId(GetUnitTypeId(unit)) == FourCC(Ids.items.stewardCorpse))
end)

T:test("Unit can pick unit item", function(case)
    local unit = case:createUnit(Ids.units.dummy)
    UnitAddAbility(unit, FourCC(Ids.abilities.inventory))

    local unitItem = case:createItem(Ids.items.dummyUnitItem)

    IssueTargetOrder(unit, "smart", unitItem)

    return case:delay(1, function()
        assert(UnitHasItem(unit, unitItem), "unit can't pick unit item")
    end)
end)

T:test("Unit can't pick hero item", function(case)
    local unit = case:createUnit(Ids.units.dummy)
    UnitAddAbility(unit, FourCC(Ids.abilities.inventory))

    local heroItem = case:createItem(Ids.items.dummyHeroItem)

    IssueTargetOrder(unit, "smart", heroItem)

    return case:delay(1, function()
        assert(not UnitHasItem(unit, heroItem), "unit can pick hero item")
    end)
end)

T:test("Hero can pick unit item", function(case)
    local hero = case:createUnit(Ids.units.dummyHero)
    local unitItem = case:createItem(Ids.items.dummyUnitItem)

    IssueTargetOrder(hero, "smart", unitItem)

    return case:delay(1, function()
        assert(UnitHasItem(hero, unitItem), "hero can't pick unit item")
    end)
end)

T:test("Hero can pick hero item", function(case)
    local hero = case:createUnit(Ids.units.dummyHero)
    local heroItem = case:createItem(Ids.items.dummyHeroItem)

    IssueTargetOrder(hero, "smart", heroItem)

    return case:delay(1, function()
        assert(UnitHasItem(hero, heroItem), "hero can't pick hero item")
    end)
end)]]

P['tests/factions/kyrian/defenceProtocol.lua'] = [[-- TODO: dispell test
local Ids = require("data.ids")
local T = require("tests.support.runner").suite("defenceProtocol")

local defenceProtocol = require("scenario.factions.kyrian.abilities.defenceProtocol")
local MechStorage = require("scenario.storage.mech")

local config = defenceProtocol.config

local function enableToggle(praetor)
    IssueImmediateOrder(praetor, "immolation")
end

T:test("Buff is applied, cooldown starts", function(case)
    local praetor = case:createUnit(Ids.units.praetor)
    local target = case:createUnit(Ids.units.aspirant)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))

    enableToggle(praetor)
    IssueTargetOrder(attacker, "attack", target)

    return case:delay(2, function()
        assert(UnitHasBuffBJ(praetor, config.refs.buffs.main), "praetor doesn't receive buff")
        assert(BlzGetUnitAbilityCooldown(praetor, config.refs.abilities.main, 1) <= 0, "cooldown didn't start")
    end)
end)

T:test("Buff is applied", function(case)
    local praetor = case:createUnit(Ids.units.praetor)
    local target = case:createUnit(Ids.units.aspirant)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))

    enableToggle(praetor)
    IssueTargetOrder(attacker, "attack", target)

    return case:delay(2, function()
        assert(UnitHasBuffBJ(praetor, config.refs.buffs.main), "praetor doesn't receive buff")
    end)
end)

T:test("Buff not applied when toggle off", function(case)
    local praetor = case:createUnit(Ids.units.praetor)
    local target = case:createUnit(Ids.units.aspirant)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))

    IssueTargetOrder(attacker, "attack", target)

    return case:delay(2, function()
        assert(not UnitHasBuffBJ(praetor, config.refs.buffs.main), "buff applied without toggle")
    end)
end)

T:test("Buff not applied to wrong target type", function(case)
    local praetor = case:createUnit(Ids.units.praetor)
    local target = case:createUnit(Ids.units.praetor)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))

    enableToggle(praetor)
    IssueTargetOrder(attacker, "attack", target)

    return case:delay(2, function()
        assert(not UnitHasBuffBJ(praetor, config.refs.buffs.main), "wrong triggering unit")
    end)
end)

T:test("Cooldown affects", function(case)
    local praetor = case:createUnit(Ids.units.praetor)
    local target = case:createUnit(Ids.units.aspirant)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))

    enableToggle(praetor)
    BlzStartUnitAbilityCooldown(praetor, config.refs.abilities.main, config.balance.cooldown)
    IssueTargetOrder(attacker, "attack", target)

    return case:delay(2, function()
        assert(not UnitHasBuffBJ(praetor, config.refs.buffs.main), "ability works when on cooldown")
    end)
end)

T:test("Passive skipped when mana below cost", function(case)
    local praetor = case:createUnit(Ids.units.praetor)
    local target = case:createUnit(Ids.units.aspirant)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))

    enableToggle(praetor)
    SetUnitState(praetor, UNIT_STATE_MANA, config.balance.manacost - 1)
    IssueTargetOrder(attacker, "attack", target)

    return case:delay(2, function()
        assert(not UnitHasBuffBJ(praetor, config.refs.buffs.main), "buff applied without enough mana")
        assert(MechStorage:has(praetor), "toggle turned off when passive skipped")
    end)
end)

T:test("Passive spends mana", function(case)
    local praetor = case:createUnit(Ids.units.praetor)
    local target = case:createUnit(Ids.units.aspirant)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))
    local manaBefore = GetUnitState(praetor, UNIT_STATE_MANA)

    enableToggle(praetor)
    IssueTargetOrder(attacker, "attack", target)

    return case:delay(2, function()
        assert(UnitHasBuffBJ(praetor, config.refs.buffs.main), "praetor doesn't receive buff")
        assert(
            GetUnitState(praetor, UNIT_STATE_MANA) <= manaBefore - config.balance.manacost + 0.01,
            "mana not spent on passive trigger"
        )
    end)
end)

T:test("Toggle not enabled without enough mana", function(case)
    local praetor = case:createUnit(Ids.units.praetor)

    SetUnitState(praetor, UNIT_STATE_MANA, config.balance.manacost - 1)
    enableToggle(praetor)

    return case:delay(0.5, function()
        assert(not MechStorage:has(praetor), "toggle enabled without enough mana")
    end)
end)]]

