P['tests/factions/kyrian/pride.lua'] = [[local Ids = require("data.ids")
local Items = require("lib.items")
local T = require("tests.support.runner").suite("pride")

local pride = require("scenario.factions.kyrian.abilities.pride")

local function populate(case, biggerUnits, equalUnits, lesserUnits, player)
    local result = { unit = nil, bigger = {}, equal = {}, lesser = {} }
    local unit = case:createUnit(Ids.units.larion)
    local baseHP = BlzGetUnitMaxHP(unit)

    pride.debug.onTrain(unit)
    case:addFlushCallback(function()
        -- pride.debug.onDeath(unit)
    end)

    result.unit = unit
    for i = 1, biggerUnits do
        local u = case:createUnit(Ids.units.aspirant, player)
        BlzSetUnitMaxHP(u, baseHP + 1)
        table.insert(result.bigger, u)
    end
    for i = 1, equalUnits do
        local u = case:createUnit(Ids.units.aspirant, player)
        BlzSetUnitMaxHP(u, baseHP)
        table.insert(result.equal, u)
    end
    for i = 1, lesserUnits do
        local u = case:createUnit(Ids.units.aspirant, player)
        BlzSetUnitMaxHP(u, baseHP - 1)
        table.insert(result.lesser, u)
    end
    return result
end

local function testPrideLevelCalc(case, unitsData, expectedResult)
    local populated = populate(case, unitsData.bigger, unitsData.equal, unitsData.lesser)
    pride.debug.applyPride(populated.unit)

    local prideLevel = GetUnitAbilityLevel(populated.unit, pride.config.refs.abilities.damage)
    assert(
        prideLevel == expectedResult,
        "Invalid prideLevel value = " .. prideLevel .. ", expected = " .. expectedResult
    )
end

T:test("No damage bonus by default", function(case)
    testPrideLevelCalc(case, { bigger = 0, equal = 0, lesser = 0 }, 0)
end)

T:test("+1 strict", function(case)
    testPrideLevelCalc(case, { bigger = 0, equal = 0, lesser = 1 }, 1)
end)

T:test("+5 strict", function(case)
    testPrideLevelCalc(case, { bigger = 0, equal = 0, lesser = 5 }, 5)
end)

T:test("+5 max", function(case)
    testPrideLevelCalc(case, { bigger = 0, equal = 0, lesser = 6 }, 5)
end)

T:test("Bigger creatures negate bonus", function(case)
    testPrideLevelCalc(case, { bigger = 5, equal = 0, lesser = 5 }, 0)
end)

T:test("Equal creatures negate bonus", function(case)
    testPrideLevelCalc(case, { bigger = 1, equal = 1, lesser = 5 }, 3)
end)]]

P['tests/factions/kyrian/pulseback.lua'] = [[local Ids = require("data.ids")
local T = require("tests.support.runner").suite("pulseback")

local pulseback = require("scenario.factions.kyrian.abilities.pulseback")
local MechStorage = require("scenario.storage.mech")

local config = pulseback.config

local function setActive(unit, active)
    if active then
        MechStorage:set(unit, "active", true)
    else
        MechStorage:drop(unit)
    end
end

T:test("Proc not triggered when toggle off", function(case)
    local goliath = case:createUnit(Ids.units.goliath)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))

    setActive(goliath, false)
    IssueTargetOrder(attacker, "attack", goliath)

    return case:delay(2, function()
        assert(BlzGetUnitAbilityCooldownRemaining(goliath, config.refs.abilities.main) <= 0, "proc triggered with toggle off")
    end)
end)

T:test("Proc skipped when mana below cost", function(case)
    local goliath = case:createUnit(Ids.units.goliath)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))

    setActive(goliath, true)
    SetUnitState(goliath, UNIT_STATE_MANA, config.balance.pulseManacost - 1)
    IssueTargetOrder(attacker, "attack", goliath)

    return case:delay(2, function()
        assert(BlzGetUnitAbilityCooldownRemaining(goliath, config.refs.abilities.main) <= 0, "proc triggered without enough mana")
        assert(MechStorage:has(goliath), "toggle turned off when proc skipped")
    end)
end)

T:test("Cooldown blocks proc", function(case)
    local goliath = case:createUnit(Ids.units.goliath)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))

    setActive(goliath, true)
    BlzStartUnitAbilityCooldown(goliath, config.refs.abilities.main, config.balance.cooldown)
    IssueTargetOrder(attacker, "attack", goliath)

    return case:delay(2, function()
        assert(BlzGetUnitAbilityCooldownRemaining(goliath, config.refs.abilities.main) > 0, "cooldown was reset")
    end)
end)

T:test("Ally attack does not proc", function(case)
    local goliath = case:createUnit(Ids.units.goliath)
    local ally = case:createUnit(Ids.units.aspirant)

    setActive(goliath, true)
    IssueTargetOrder(ally, "attack", goliath)

    return case:delay(2, function()
        assert(BlzGetUnitAbilityCooldownRemaining(goliath, config.refs.abilities.main) <= 0, "proc triggered by ally attack")
    end)
end)

T:test("Toggle off via unimmolation", function(case)
    local goliath = case:createUnit(Ids.units.goliath)

    setActive(goliath, true)
    IssueImmediateOrder(goliath, "unimmolation")

    return case:delay(1, function()
        assert(not MechStorage:has(goliath), "toggle not disabled")
    end)
end)

T:test("Active by default allows proc attempt", function(case)
    local goliath = case:createUnit(Ids.units.goliath)
    local attacker = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))
    local manaBefore = GetUnitState(goliath, UNIT_STATE_MANA)

    IssueTargetOrder(attacker, "attack", goliath)

    return case:delay(3, function()
        local cdRemaining = BlzGetUnitAbilityCooldownRemaining(goliath, config.refs.abilities.main)
        local manaAfter = GetUnitState(goliath, UNIT_STATE_MANA)
        assert(
            cdRemaining > 0 or manaAfter >= manaBefore - config.balance.pulseManacost + 0.01,
            "no proc attempt with default active state"
        )
    end)
end)]]

P['tests/factions/kyrian/soulbind.lua'] = [[-- TODO:
-- - forbid 2 bonds on same target
-- - forbid 2 bonds from same caster
-- Generated
local Ids = require("data.ids")
local Store = require("scenario.storage.soulbind")
local Storage = require("lib.storage.storage")
local Soulbind = require("scenario.factions.kyrian.abilities.soulbind")

local cfg = Soulbind.config
local BUFF = FourCC(Ids.buffs.soulbind)
local TICKS_PER_LEVEL = cfg.balance.secondsForLevel / cfg.balance.tickSeconds
local OUT_OF_RANGE_OFFSET = cfg.balance.radius + 500

local function report(ok, name)
    DisplayTextToPlayer(GetLocalPlayer(), 0, 0, (ok and "OK: " or "ERROR: ") .. name)
end

local function hasBuff(unit)
    return UnitHasBuffBJ(unit, BUFF)
end

local function pair(x, y)
    local u1 = CreateUnit(Player(0), FourCC(Ids.units.aspirant), x, y, 270)
    local u2 = CreateUnit(Player(0), FourCC(Ids.units.aspirant), x + 32, y, 270)
    return u1, u2
end

local function bond(u1, u2)
    local id = Store:alloc()
    assert(Store:create(id, { unit_a = u1, unit_b = u2 }), "create failed")
    return id
end

local function cleanup(id, u1, u2)
    Store:drop(id)
    RemoveUnit(u1)
    RemoveUnit(u2)
end

local function tick(id, n)
    for _ = 1, n do
        Soulbind.tickBond(id)
    end
end

Timed.call(0, function()
    Storage.initAll()
    local x, y = -200, -200
    local u1, u2 = pair(x, y)
    local id = bond(u1, u2)
    local b = assert(Store:read(id), "bond missing")

    report(b.level == 1 and b.progress == 0 and not b.active, "bond starts at level 1")
    report(Store:find(u1) == id, "unit lookup works")

    cleanup(id, u1, u2)
end)

Timed.call(0, function()
    Storage.initAll()
    local x, y = -200, -400
    local u1, u2 = pair(x, y)
    local id = bond(u1, u2)

    local halfTicks = math.ceil(TICKS_PER_LEVEL / 2)
    tick(id, halfTicks)
    local mid = assert(Store:read(id), "bond missing")
    report(mid.level == 1 and mid.progress > 0 and mid.progress < 1, "partial progress mid level")

    tick(id, TICKS_PER_LEVEL - halfTicks)
    local lvl2 = assert(Store:read(id), "bond missing")
    report(lvl2.level == 2 and lvl2.progress == 0, "level 2 after full cycle")

    tick(id, TICKS_PER_LEVEL)
    report(assert(Store:read(id), "bond missing").level == 3, "level 3 after second cycle")

    tick(id, TICKS_PER_LEVEL)
    local capped = assert(Store:read(id), "bond missing")
    report(capped.level == 3 and capped.progress == 0, "stays at max level")

    cleanup(id, u1, u2)
end)

Timed.call(0, function()
    Storage.initAll()
    local x, y = -200, -600
    local u1, u2 = pair(x, y)
    local id = bond(u1, u2)

    SetUnitPosition(u2, x + OUT_OF_RANGE_OFFSET, y)
    Soulbind.tickBond(id)
    local b = assert(Store:read(id), "bond missing")

    report(not b.active and b.level == 1 and b.progress == 0, "no progress when out of range")

    cleanup(id, u1, u2)
end)

Timed.call(0, function()
    Storage.initAll()
    local x, y = -400, -200
    local u1, u2 = pair(x, y)
    local id = bond(u1, u2)

    tick(id, TICKS_PER_LEVEL * 2)

    Timed.call(1, function()
        report(hasBuff(u1) and hasBuff(u2), "buff applied at level 3")

        SetUnitPosition(u2, x + OUT_OF_RANGE_OFFSET, y)
        Soulbind.tickBond(id)
        report(not hasBuff(u1) and not hasBuff(u2), "buff removed on range break")

        SetUnitPosition(u2, x + 32, y)
        Soulbind.tickBond(id)

        Timed.call(1, function()
            report(hasBuff(u1) and hasBuff(u2), "buff restored in range")

            SetUnitPosition(u2, x + OUT_OF_RANGE_OFFSET, y)
            Soulbind.tickBond(id)
            report(not hasBuff(u1) and not hasBuff(u2), "buff removed on 2nd range break")

            cleanup(id, u1, u2)
        end)
    end)
end)]]

P['tests/factions/necrolord/combatExpertise.lua'] = [[local Ids = require("data.ids")
local T = require("tests.support.runner").suite("combatExpertise")

local combatExpertise = require("scenario.factions.necrolord.abilities.combatExpertise")

local config = combatExpertise.config
local OUT_OF_RANGE_OFFSET = config.balance.radius + 50

local function populate(case, deathCount, opts)
    opts = opts or {}
    local carrier = case:createUnit(Ids.units.animateWarrior)
    local victim = case:createUnit(Ids.units.aspirant, Player(PLAYER_NEUTRAL_AGGRESSIVE))

    if opts.outOfRange then
        local cx, cy = GetUnitX(carrier), GetUnitY(carrier)
        SetUnitPosition(victim, cx + OUT_OF_RANGE_OFFSET, cy)
    end

    for _ = 1, deathCount do
        combatExpertise.debug.onDeath(victim)
    end

    return { carrier = carrier, victim = victim }
end

local function testLevelCalc(case, deathCount, expectedLevel, opts)
    local populated = populate(case, deathCount, opts)
    local level = GetUnitAbilityLevel(populated.carrier, config.refs.abilities.damageBuff)
    assert(
        level == expectedLevel,
        "Invalid buffLevel value = " .. level .. ", expected = " .. expectedLevel
    )
end

T:test("No damage bonus by default", function(case)
    testLevelCalc(case, 0, 0)
end)

T:test("1 death no bonus yet", function(case)
    testLevelCalc(case, 1, 0)
end)

T:test("+1 level", function(case)
    testLevelCalc(case, 2, 1)
end)

T:test("+5 strict", function(case)
    testLevelCalc(case, 10, 5)
end)

T:test("+5 max", function(case)
    testLevelCalc(case, 12, 5)
end)

T:test("Out of range deaths ignored", function(case)
    testLevelCalc(case, 10, 0, { outOfRange = true })
end)

T:test("Progress reset on carrier death", function(case)
    local populated = populate(case, 4)
    combatExpertise.debug.onDeath(populated.carrier)
    for _ = 1, 2 do
        combatExpertise.debug.onDeath(populated.victim)
    end

    local level = GetUnitAbilityLevel(populated.carrier, config.refs.abilities.damageBuff)
    assert(level == 1, "Invalid buffLevel after carrier death reset = " .. level .. ", expected = 1")
end)]]

