P['tests/support/case.lua'] = [=[local Ids = require("data.ids")

ENUM_WAIT = "WAIT"

local Case = {}

---@param testName string
---@param testFunc TestFn
---@param x number
---@param y number
---@param reporter TestReporterFn
---@return TestCase
function Case.new(testName, testFunc, x, y, reporter)
    local self = {}

    local items = {}
    local units = {}

    local flushCallbacks = {}

    -- local x = -100
    -- local y = -100

    function self:run()
        local ok, res = pcall(testFunc, self)
        if not ok then
            return self:finish(ok, res)
        end
        if res ~= ENUM_WAIT then
            self:finish(ok, res)
        end
    end

    function self:delay(delta, callback)
        Timed.call(delta, function()
            local ok, err = pcall(callback)
            self:finish(ok, err)
        end)
        return ENUM_WAIT
    end

    function self:finish(ok, err)
        self:flush()
        if ok then
            return self:ok()
        else
            return self:fail(err)
        end
    end

    function self:ok()
        reporter(testName, true)
    end

    function self:fail(msg)
        reporter(testName, false, tostring(msg))
    end

    ---
    ---
    ---

    function self:createItem(itemTypeId)
        local item = CreateItem(FourCC(itemTypeId), x, y)
        items[#items + 1] = item
        return item
    end

    function self:createUnit(unitTypeId, player, collision)
        if player == nil then
            player = Player(0)
        end
        local unit = CreateUnit(player, FourCC(unitTypeId), x, y, 270)
        if collision == nil then
            UnitAddAbility(unit, FourCC(Ids.abilities.phase))
            IssueImmediateOrderBJ(unit, "windwalk")
        end
        units[#units + 1] = unit
        return unit
    end

    function self:applyDummyOrder(owner, target, abilityId, order, level)
        local dummy = self:createUnit(Ids.units.dummy, owner, true)
        UnitApplyTimedLife(dummy, FourCC("BTLF"), 10)
        local abilityAdded = UnitAddAbility(dummy, abilityId)
        if level then
            SetUnitAbilityLevel(dummy, abilityId, level)
        end
        local orderIssued = IssueTargetOrder(dummy, order, target)
        return {
            dummy = dummy,
            abilityAdded = abilityAdded,
            orderIssued = orderIssued,
        }
    end

    function self:flush()
        for _, callback in ipairs(flushCallbacks) do
            callback()
        end
        for _, v in ipairs(items) do
            RemoveItem(v)
        end
        for _, v in ipairs(units) do
            RemoveUnit(v)
        end
        return true
    end

    function self:addFlushCallback(callback)
        table.insert(flushCallbacks, callback)
    end

    return self --[[@as TestCase]]
end

---@cast Case CaseModule
return Case]=]

P['tests/support/reporter.lua'] = [[local ReporterMode = require("tests.support.reporter_mode")

local logger = require("utils.logger")

local Reporter = {}

---@type ReporterMode
Reporter.mode = nil
Reporter.Mode = ReporterMode

local COLOR_OK = "55ff55"
local COLOR_FAIL = "ff5555"

---@param hex string
---@param text string
---@return string
local function color(hex, text)
    return "|cff" .. hex .. text .. "|r"
end

---@param hex string
---@param plain string
local function printColored(hex, plain)
    Debug.original.print(color(hex, plain))

    logger.log(plain)
end

---@param testName string
---@param ok boolean
---@param err? string
function Reporter.immediate(testName, ok, err)
    if Reporter.mode ~= ReporterMode.verbose then
        return
    end

    local plain

    if ok then
        plain = "OK: [" .. testName .. "]"
    else
        plain = "ERROR: [" .. testName .. "] -> " .. (err or "?")
    end
    DisplayTextToPlayer(GetLocalPlayer(), 0, 0, color(ok and COLOR_OK or COLOR_FAIL, plain))
    logger.log(plain)
end

---@param suite TestSuite
---@param failed { name: string, err?: string }[]
local function printFailures(suite, failed)
    printColored(COLOR_FAIL, string.format("[%s] FAILED %d/%d", suite.name, #failed, suite.total))

    for _, f in ipairs(failed) do
        printColored(COLOR_FAIL, string.format("  x %s: %s", f.name, f.err or "?"))
    end
end

---@param suite TestSuite
function Reporter.flushSuite(suite)
    logger.log(string.format("--- [%s] ---", suite.name))

    if Reporter.mode ~= ReporterMode.verbose then
        local failed = {}

        local passed = 0

        for _, testName in ipairs(suite.order) do
            local result = suite.results[testName]

            if result.ok then
                passed = passed + 1
            else
                failed[#failed + 1] = { name = testName, err = result.err }
            end
        end

        if Reporter.mode == ReporterMode.errors then
            if #failed > 0 then
                printFailures(suite, failed)
            end
        elseif #failed == 0 then
            printColored(COLOR_OK, string.format("[%s] %d/%d OK", suite.name, passed, suite.total))
        else
            printFailures(suite, failed)
        end
    end

    logger.flush()
end

---@cast Reporter TestReporter
return Reporter]]

P['tests/support/reporter_mode.lua'] = [[---@enum ReporterMode
local ReporterMode = {
    summary = "summary",
    errors = "errors",
    verbose = "verbose",
}

return ReporterMode]]

P['tests/support/runner.lua'] = [=[local Case = require("tests.support.case")
local Reporter = require("tests.support.reporter")
local Suite = require("tests.support.suite")

local T = {}

local pendingRunners = {}

local world = GetWorldBounds()
local margin = 800
local minX = GetRectMinX(world) + margin
local minY = GetRectMinY(world) + margin
local maxX = GetRectMaxX(world) - margin / 2
local maxY = GetRectMaxY(world) - margin / 2

local cursorX = minX
local cursorY = minY
local rowHeight = 0
local cellSize = 700

---@param size number
---@return number x
---@return number y
local function alloc(size)
    if cursorX + size > maxX then
        print("-> НЕ ПОМЕЩАЕТСЯ! Перенос строки.")
        cursorX = minX
        cursorY = cursorY + rowHeight
        rowHeight = 0
    end

    if cursorY + size > maxY then
        error(
            "Превышены границы карты: не осталось свободных тестовых ячеек! Увеличьте размер карты или уменьшите cellSize."
        )
    end

    local x, y = cursorX, cursorY
    cursorX = cursorX + size

    if size > rowHeight then
        rowHeight = size
    end

    return x, y
end

---@param suite TestSuite
---@return TestRunner
local function createRunner(suite)
    local self = {}
    local queued = {}
    local started = false

    ---@param name string
    ---@param testFunc TestFn
    function self:test(name, testFunc)
        if started then
            error(string.format("[%s] test registered after run: %q", suite.name, name))
        end

        suite:registerTest(name)
        queued[#queued + 1] = { name = name, testFunc = testFunc }
    end

    function self:run()
        if started then
            error(string.format("[%s] suite already started", suite.name))
        end
        started = true

        if #queued == 0 then
            return
        end

        for _, entry in ipairs(queued) do
            ---@type TestReporterFn
            local reporter = function(testName, ok, err)
                Reporter.immediate(testName, ok, err)
                suite:record(testName, ok, err)
            end

            local x, y = alloc(cellSize)
            Case.new(entry.name, entry.testFunc, x, y, reporter):run()
        end
    end

    return self --[[@as TestRunner]]
end

---@param name string
---@return TestRunner
function T.suite(name)
    local runner = createRunner(Suite.new(name))
    pendingRunners[#pendingRunners + 1] = runner
    return runner
end

function T.runAll()
    for _, runner in ipairs(pendingRunners) do
        runner:run()
    end
end

---@cast T RunnerModule
return T]=]

P['tests/support/suite.lua'] = [=[local Reporter = require("tests.support.reporter")

local Suite = {}

---@param name string
---@return TestSuite
function Suite.new(name)
    local self = {}

    self.name = name
    self.names = {}
    self.results = {}
    self.order = {}
    self.pending = 0
    self.total = 0

    ---@param testName string
    function self:registerTest(testName)
        if self.names[testName] then
            error(string.format("[%s] duplicate test name: %q", self.name, testName))
        end
        self.names[testName] = true
        self.total = self.total + 1
        self.pending = self.pending + 1
        self.order[#self.order + 1] = testName
    end

    ---@param testName string
    ---@param ok boolean
    ---@param err? string
    function self:record(testName, ok, err)
        self.results[testName] = { ok = ok, err = err }
        self.pending = self.pending - 1
        if self.pending == 0 then
            self:flush()
        end
    end

    function self:flush()
        Reporter.flushSuite(self)
    end

    return self --[[@as TestSuite]]
end

---@cast Suite SuiteModule
return Suite]=]

P['tests/support/types.lua'] = [[---@meta

---@alias TestWait "WAIT"
---@alias TestReporterFn fun(testName: string, ok: boolean, err?: string)
---@alias TestFn fun(case: TestCase): TestWait|nil

---@class TestCase
---@field run fun(self: TestCase)
---@field delay fun(self: TestCase, delta: number, callback: fun()): TestWait
---@field finish fun(self: TestCase, ok: boolean, err: any)
---@field ok fun(self: TestCase)
---@field fail fun(self: TestCase, msg: string)
---@field createItem fun(self: TestCase, itemTypeId: string): item
---@field createUnit fun(self: TestCase, unitTypeId: string, player?: player, collision?: boolean): unit
---@field applyDummyOrder fun(self: TestCase, owner: player, target: unit, abilityId: integer, order: string, level?: integer)
---@field flush fun(self: TestCase): boolean
---@field addFlushCallback fun(self: TestCase, callback: fun())

---@class TestResult
---@field ok boolean
---@field err? string

---@class TestSuite
---@field name string
---@field names table<string, boolean>
---@field results table<string, TestResult>
---@field order string[]
---@field pending integer
---@field total integer
---@field registerTest fun(self: TestSuite, name: string)
---@field record fun(self: TestSuite, name: string, ok: boolean, err?: string)
---@field flush fun(self: TestSuite)

---@class TestRunner
---@field test fun(self: TestRunner, name: string, testFunc: TestFn)
---@field run fun(self: TestRunner)

---@class ReporterModeEnum
---@field summary ReporterMode
---@field errors ReporterMode
---@field verbose ReporterMode

---@class TestReporter
---@field mode ReporterMode
---@field Mode ReporterModeEnum
---@field immediate fun(testName: string, ok: boolean, err?: string)
---@field flushSuite fun(suite: TestSuite)

---@class CaseModule
---@field new fun(testName: string, testFunc: TestFn, x: number, y: number, reporter: TestReporterFn): TestCase

---@class SuiteModule
---@field new fun(name: string): TestSuite

---@class RunnerModule
---@field suite fun(name: string): TestRunner
---@field runAll fun()]]

P['utils/dummy.lua'] = [[local Ids = require("data.ids")

local Dummy = {}

---@alias Order string|integer

local function spawn(owner, at, abilityId, level, unitId)
    local x, y = Generic.pointXY(at)
    local dummy = CreateUnit(owner, unitId or FourCC(Ids.units.dummy), x, y, 270)
    UnitApplyTimedLife(dummy, FourCC("BTLF"), 10)
    if abilityId then
        UnitAddAbility(dummy, abilityId)
        if level then
            SetUnitAbilityLevel(dummy, abilityId, level)
        end
    end
    SetUnitInvulnerable(dummy, true)
    SetUnitPathing(dummy, false)
    SetUnitPosition(dummy, x, y)
    return dummy
end

function Dummy.issueImmediate(dummy, order)
    if type(order) == "number" then
        IssueImmediateOrderById(dummy, order)
    else
        IssueImmediateOrder(dummy, order)
    end
end

function Dummy.issueTarget(dummy, order, target)
    if type(order) == "number" then
        IssueTargetOrderById(dummy, order, target)
    else
        IssueTargetOrder(dummy, order, target)
    end
end

function Dummy.issuePoint(dummy, order, x, y)
    if type(order) == "number" then
        IssuePointOrderById(dummy, order, x, y)
    else
        IssuePointOrder(dummy, order, x, y)
    end
end

function Dummy.create(owner, at, abilityId, level, unitId)
    return spawn(owner, at, abilityId, level, unitId)
end

function Dummy.applyDummyOrder(owner, target, abilityId, order, level)
    local dummy = spawn(owner, target, abilityId, level)
    local s = Dummy.issueTarget(dummy, order, target)
    dump("applyDummyOrder", order, s)
    return dummy
end

function Dummy.applyDummyPointOrder(owner, at, abilityId, order, level)
    local x, y = Generic.pointXY(at)
    local dummy = spawn(owner, at, abilityId, level)
    Dummy.issuePoint(dummy, order, x, y)
    return dummy
end

function Dummy.applyDummyAttack(owner, target, abilityId, level)
    local dummy = spawn(owner, target, abilityId, level, FourCC(Ids.units.dummyAttack))
    Dummy.issueTarget(dummy, "attack", target)
    return dummy
end

function Dummy.applyDummyImmediateOrder(owner, at, abilityId, order, level)
    local dummy = spawn(owner, at, abilityId, level)
    Dummy.issueImmediate(dummy, order)
    return dummy
end

return Dummy]]

P['utils/generic.lua'] = [[local Generic = {}

---@param at Point
---@param class "unit"|"item"|nil
function Generic.pointXY(at, class)
    if type(at) == "table" then
        return at.x, at.y
    end
    if class == "item" then
        ---@diagnostic disable-next-line: param-type-mismatch
        return GetItemX(at), GetItemY(at)
    else
        ---@diagnostic disable-next-line: param-type-mismatch
        return GetUnitX(at), GetUnitY(at)
    end
end

function Generic.filter(t, predicate)
    local result = {}
    for _, v in ipairs(t) do
        if predicate(v) then
            table.insert(result, v)
        end
    end
    return result
end

--- @param t table
--- @result table
function Generic.reverseTable(t)
    local result = {}
    for k, v in pairs(t) do
        result[v] = k
    end
    return result
end

function Generic.contains(t, value)
    for _, v in pairs(t) do
        if v == value then
            return true
        end
    end
    return false
end

function Generic.index(t, value)
    for i, v in ipairs(t) do
        if v == value then
            return i
        end
    end
    return nil
end

--- @param t table
--- @result table<integer,any>
function Generic.toArray(t)
    local array = {}
    for _, value in pairs(t) do
        table.insert(array, value)
    end
    return array
end

--- @param t table
--- @result table<any,true>
function Generic.toSet(t)
    local set = {}
    for _, value in pairs(t) do
        set[value] = true
    end
    return set
end

--- @param t table
--- @param value any
--- @result boolean
function Generic.removeValue(t, value)
    for i, v in ipairs(t) do
        if v == value then
            table.remove(t, i)
            return true
        end
    end
    return false
end

--- @param a {x:number,y:number}
--- @param b {x:number,y:number}
function Generic.distance(a, b)
    local aX, aY = Generic.pointXY(a)
    local bX, bY = Generic.pointXY(b)
    local dX = math.abs(aX - bX)
    local dY = math.abs(aY - bY)
    return math.sqrt(dX ^ 2 + dY ^ 2)
end

return Generic]]

P['utils/logger.lua'] = [[-- utils/dump.lua
local LOG_COLOR = "bbbbbb"
local LOG_FILE = "shadowlands-melee.txt"
local PRELOAD_LIMIT = 259

---@type string[]
local logBuffer = {}

local function formatValue(v, depth)
    if type(v) == "table" then
        return table.tostring(v, depth) -- DebugUtils: name cache + вложенность
    end
    if type(v) == "userdata" then
        local isUnit = pcall(GetUnitTypeId, v)
        if isUnit then
            return GetUnitName(v)
            -- return GetUnitName(v) .. "[" .. tostring(v) .. "]"
        end
        local isItem = pcall(GetItemTypeId, v)
        if isItem then
            return GetItemName(v)
            -- return GetItemName(v) .. "[" .. tostring(v) .. "]"
        end
        local isAbility = pcall(GetSpellAbilityId, v)
        if isAbility then
            return GetAbilityName(v)
            -- return GetItemName(v) .. "[" .. tostring(v) .. "]"
        end
    end
    return tostring(v) -- юниты/игроки с именами из name cache
end

---@param line string
local function preloadLine(line)
    if line == "" then
        Preload("\n")
        return
    end

    local i = 1
    while i <= #line do
        Preload(line:sub(i, i + PRELOAD_LIMIT - 1) .. "\n")
        i = i + PRELOAD_LIMIT
    end
end

local function flushLog()
    if #logBuffer == 0 then
        return
    end

    local ok, err = pcall(function()
        PreloadGenClear()
        PreloadGenStart()
        for _, line in ipairs(logBuffer) do
            preloadLine(line)
        end
        PreloadGenEnd(LOG_FILE)
    end)

    if not ok then
        Debug.original.print("|cffff5555logger flush failed: " .. tostring(err) .. "|r")
    end
end

---@param line string
local function appendLog(line)
    logBuffer[#logBuffer + 1] = line
end

---@param tag? string
---@param ... any
local function dump(tag, ...)
    local n = select("#", ...)
    local parts = {}
    if tag then
        parts[#parts + 1] = tostring(tag)
    end
    for i = 1, n do
        parts[#parts + 1] = formatValue(select(i, ...))
    end
    local plain = table.concat(parts, " | ")
    local msg = "|cff" .. LOG_COLOR .. plain .. "|r"

    -- print перехвачен DebugUtils → виден в игре, если PRINT_DURATION задан
    Debug.original.print(msg)
    appendLog(plain)
end

---@class Logger
---@field flush fun()
---@field log fun(line: string)
---@field mark fun(line: string)
local logger = setmetatable({
    flush = flushLog,
    log = appendLog,
    mark = appendLog,
}, {
    __call = function(_, tag, ...)
        dump(tag, ...)
    end,
})

return logger]]

