P['vendor/assets/objediting/base/string.lua'] = [[-- string.lua
-- @Author : Dencer (tdaddon@163.com)
-- @Link   : https://dengsir.github.io
-- @Date   : 4/1/2019 4:15 PM

local string, table = string, table

---@diagnostic disable: inject-field, undefined-field, redundant-return-value

---trimleft
---@param s string
---@return string
function string.trimleft(s)
    return (s:gsub('^%s+', ''))
end

---trimright
---@param s string
---@return string
function string.trimright(s)
    return (s:gsub('%s+$', ''))
end

---trim
---@param s string
---@return string
function string.trim(s)
    return s:trimleft():trimright()
end

---split
---@param s string
---@param pattern string
---@param plain boolean
---@param maxTokens integer
---@return string[]
function string.split(s, pattern, plain, maxTokens)
    local pos = 0
    local start, stop
    local r = {}

    while true do
        start, stop = s:find(pattern, pos, plain)
        if not start then
            break
        end

        table.insert(r, s:sub(pos, start - 1))
        pos = stop + 1

        if maxTokens then
            maxTokens = maxTokens - 1
            if maxTokens == 0 then
                break
            end
        end
    end
    table.insert(r, s:sub(pos))
    return r
end

---startswith
---@param s string
---@param pattern string
---@param plain boolean
---@return boolean
function string.startswith(s, pattern, plain)
    if plain then
        pattern = pattern:escapepattern()
    end
    pattern = '^' .. pattern
    return not not s:find(pattern)
end

---endswith
---@param s string
---@param pattern string
---@param plain boolean
---@return boolean
function string.endswith(s, pattern, plain)
    if plain then
        pattern = pattern:escapepattern()
    end
    pattern = pattern .. '$'
    return not not s:find(pattern)
end

---escapepattern
---@param s string
---@return string
function string.escapepattern(s)
    return s:gsub('[%(%)%.%%%+%-%*%?%[%]%^%$]', '%%%0')
end]]

P['vendor/assets/objediting/base/table.lua'] = [[-- table.lua
-- @Author : Dencer (tdaddon@163.com)
-- @Link   : https://dengsir.github.io
-- @Date   : 4/1/2019 2:47 PM

local pairs, ipairs, select, type = pairs, ipairs, select, type
local table = table

---@diagnostic disable: inject-field, redundant-return-value, missing-return, undefined-doc-name, return-type-mismatch

---@class integer: number
---@class float: number

---@generic V
---@alias array V[]|table<integer, V>

local function riter(t, i)
    i = i - 1
    if i > 0 then
        return i, t[i]
    end
end

---ripairs
---@generic V
---@param t array
---@return fun(t:array):number,V
function ripairs(t)
    return riter, t, #t + 1
end

---spairs
---@generic V
---@param t table<string, V>|V[]
---@return fun(tbl: table<string, V>):string, V
function spairs(t)
    local i = 0
    local keys = table.keys(t)
    table.sort(keys)

    return function()
        i = i + 1
        local k = keys[i]
        if k then
            return k, t[k]
        end
    end
end

---vipairs
---@generic V
---@param t array
---@return fun(t:array):V
function vipairs(t)
    local i = 0
    return function()
        i = i + 1
        return t[i]
    end
end

---vpairs
---@generic K
---@generic V
---@param t table<K, V>
---@return fun(): V
function vpairs(t)
    local k
    return function()
        k = next(t, k)
        if not k then
            return
        end
        return t[k]
    end
end

---wipe
---@param t T
---@return T
function table.wipe(t)
    for k, v in pairs(t) do
        t[k] = nil
    end
    return t
end

---reduce
---@generic V, T
---@param t array
---@param callback fun(r:any, v:V, i:integer, t:array):T
---@param initialValue T
---@return T
function table.reduce(t, callback, initialValue)
    local r = initialValue
    for i, v in ipairs(t) do
        r = callback(r, v, i, t) or r
    end
    return r
end

---filter
---@generic V
---@param t array
---@param callback fun(v:V, i:integer, t:array):boolean
---@return array
function table.filter(t, callback)
    return table.reduce(t, function(r, v, i, _t)
        if callback(v, i, _t) then
            table.insert(r, v)
        end
    end, {})
end

---map
---@generic V, O
---@param t array
---@param callback fun(v:V, i:integer, t:array):O
---@return O[]|table<integer,O>
function table.map(t, callback)
    return table.reduce(t, function(r, v, i, _t)
        r[i] = callback(v, i, _t)
    end, {})
end

---every
---@generic V
---@param t array
---@param callback fun(v:V, i:integer, t:array):boolean
---@return boolean
function table.every(t, callback)
    for i, v in ipairs(t) do
        if not callback(v, i, t) then
            return false
        end
    end
    return true
end

---shallowcopy
---@generic T
---@param t T
---@return T
function table.shallowcopy(t)
    local r = {}
    for k, v in pairs(t) do
        r[k] = v
    end
    return r
end

---arraycopy
---@generic T
---@param t T
---@return T
function table.arraycopy(t)
    local r = {}
    for i, v in ipairs(t) do
        r[i] = v
    end
    return r
end

---indexof
---@generic V
---@param t array
---@param item V
---@return integer|nil
function table.indexof(t, item)
    for i, v in ipairs(t) do
        if v == item then
            return i
        end
    end
end

---contains
---@generic V
---@param t array
---@param item V
---@return boolean
function table.contains(t, item)
    return not not table.indexof(t, item)
end

---isempty
---@param t table
---@return boolean
function table.isempty(t)
    return next(t) == nil
end

---keys
---@param t table
function table.keys(t)
    local r = {}
    for k in pairs(t) do
        table.insert(r, k)
    end
    return r
end

---values
---@generic T
---@param t table<any, T>
---@return T[]
function table.values(t)
    local r = {}
    for _, v in pairs(t) do
        table.insert(r, v)
    end
    return r
end

---join
---@generic T
---@vararg T
---@return T
function table.join(...)
    local r = {}
    local t

    for i = 1, select('#', ...) do
        t = select(i, ...)
        if type(t) == 'table' then
            for _, v in ipairs(t) do
                table.insert(r, v)
            end
        else
            table.insert(r, t)
        end
    end
    return r
end

---merge
---@vararg table
---@return table
function table.merge(...)
    local r = {}
    for i = 1, select('#', ...) do
        for k, v in pairs(select(i, ...)) do
            r[k] = v
        end
    end
    return r
end

---random
---@generic T
---@param t T[]
---@return T
function table.random(t)
    if #t == 1 then
        return t[1]
    end
    return t[math.random(1, #t)]
end

_G.ripairs = ripairs
_G.spairs = spairs
_G.vipairs = vipairs
_G.vpairs = vpairs]]

P['vendor/assets/objediting/core/checker.lua'] = [=[-- checker.lua
-- @Author : Dencer (tdaddon@163.com)
-- @Link   : https://dengsir.github.io
-- @Date   : 7/14/2019, 10:27:56 PM

local function itype(value)
    local t = type(value)
    if t == 'number' then
        return math.type(value)
    end
    return t
end

function checktype(value, checkType, api, index)
    local t = itype(value)
    if t == checkType then
        return
    end

    if checkType == 'float' and t == 'integer' or checkType == 'integer' and t == 'float' then
        return
    end

    if checkType == 'boolean' and (value == 0 or value == 1) then
        return
    end

    error(string.format([[bad argument #%s to '%s' (%s expected, got %s)]], index, api, checkType, t), 3)
end

local enumCache = setmetatable({}, {__index = function(t, k)
    local r = {}
    for _, v in pairs(k) do
        r[v] = true
    end
    t[k] = r
    return r
end})

function checkenum(value, enum, api, index)
    local e = _G[enum]
    if not e then
        return
    end
    if enumCache[e][value] or value == '' then
        return
    end

    error(string.format([[bad argument #%s to '%s' (%s expected, got %s, value %s)]], index, api, enum, type(value), value))
end]=]

P['vendor/assets/objediting/core/dummper.lua'] = [=[---@diagnostic disable: assign-type-mismatch
---@class Dummper: object
Dummper = class('Dummper')

function Dummper:constructor(defType)
    self.defType = defType
    self:prepareAPIs(defType)
end

function Dummper:prepareAPIs(defType)

    if not sourcecode[defType] then
        print('Not find APIs with', defType)
        return
    end

    self.file = io.open(string.format([[%s.lua]], defType), 'w')

end

---@param defs table<string, Definition>
function Dummper:exec(defs)

    if not self.file then
        print('Not find APIs with', self.defType)
        return
    end

    local info = {'local u'}
    for id, def in pairs(defs) do
        local index = #info + 1
        local sub = {}
        for k, v in pairs(def.fields) do
            local api = sourcecode[self.defType][v.id]
            if not api then
                -- print('Miss API with', self.defType, def.id, v.id, v.value)
            else
                local value = v.value
                if type(value) == 'string' then
                    if value ~= '' then
                        value = '[[' .. value .. ']]'
                    else
                        value = '""'
                    end
                end
                if v.level and v.level > 0 then
                    table.insert(sub, string.format('u:%s(%s, %s)', api.func,
                                                     v.level, value))
                else
                    table.insert(sub, string.format('u:%s(%s)', api.func, value))
                end
            end
        end
        local cls = sourcecode[self.defType].super[def.superId or def.id]
        if cls then
            table.insert(info, index, string.format('\nu=%s:new("%s")', cls, def.id))
        else
            cls = sourcecode[self.defType].super["0"]
            table.insert(info, index, string.format('\nu=%s:new("%s", "%s")', cls, def.id, def.superId or def.id))
        end
        if #sub > 0 then
            table.insert(info, table.concat(sub, '\n'))
        end
    end

    table.insert(info, '\n')
    self.file:write(table.concat(info, '\n'))

end]=]

