DEFINITIONS = {}
---@type table<DefinitionType, table<string, Definition>>
TYPED_DEFINITIONS = setmetatable({}, {
    __index = function(t, k)
        t[k] = {}
        return t[k]
    end,
})

local DEFINITIONS = DEFINITIONS
local TYPED_DEFINITIONS = TYPED_DEFINITIONS
local CREATED_DEFINITIONS = {}

---@param defType string
---@param id string
---@param superId string
---@return ObjectDefinition
function createDefinition(defType, id, superId)
    if type(id) == 'number' then
        id = string.pack('>I', id)
    end
    if type(superId) == 'number' then
        superId = string.pack('>I', superId)
    end
    
    if CREATED_DEFINITIONS[id] then
        error(string.format('%s already exists', id), 2)
    end

    local def = DEFINITIONS[id]
    if def and (def.superId ~= superId or def.type ~= defType) then
        error(string.format([[%s's super id and define type must same as war3map object]], def.superId, superId,
                            def.type, defType), 2)
    end

    CREATED_DEFINITIONS[id] = true

    local obj = def and ObjectDefinition:new(def) or ObjectDefinition:new(defType, id, superId)

    DEFINITIONS[id] = def
    TYPED_DEFINITIONS[defType][id] = obj.def

    return obj
end

_G.FieldType = FieldType
_G.DefinitionType = DefinitionType]=]

P['vendor/assets/objediting/core/objectreader.lua'] = [[---@diagnostic disable: missing-fields, undefined-field
-- objectreader.lua
-- @Author : Dencer (tdaddon@163.com)
-- @Link   : https://dengsir.github.io
-- @Date   : 7/12/2019, 1:26:31 PM

---@class ObjectReader: object
ObjectReader = class('ObjectReader')

function ObjectReader:constructor(type, data)
    self.buffer = ReadBuffer:new(data)
    self.definitions = {}
    self.type = type
end

---@return table<string, Definition>
function ObjectReader:read()
    -- file version
    self.version = self.buffer:readInt()
    self:readDefinitions()
    self:readDefinitions()
    return self.definitions
end

function ObjectReader:readDefinitions()
    local n = self.buffer:readInt()
    for i = 1, n do
        ---@type Definition
        local def = {}
        def.type = self.type
        def.fields = {}

        local superId = self.buffer:readString(4)
        local id = self.buffer:readString(4)

        if id == '\0\0\0\0' then
            def.id = superId
        else
            def.id = id
            def.superId = superId
        end

        -- Reforged (file version >= 3) adds two extra ints in each object header:
        -- a "set count" (usually 1) and a reserved/zero int. Skip them so the
        -- field count and subsequent fields don't get misaligned.
        if self.version and self.version >= 3 then
            self.buffer:readInt()
            self.buffer:readInt()
        end

        local fieldCount = self.buffer:readInt()

        for j = 1, fieldCount do
            ---@type Filed
            local field = {}

            field.id = self.buffer:readString(4)
            field.type = self.buffer:readInt()

            if self.type == DefinitionType.Doodad or self.type == DefinitionType.Ability or self.type ==
                DefinitionType.Upgrade then
                field.level = self.buffer:readInt()
                field.column = self.buffer:readInt()
            end

            if field.type == FieldType.Int then
                field.value = self.buffer:readInt()
            elseif field.type == FieldType.Real or field.type == FieldType.Unreal then
                field.value = self.buffer:readFloat()
            elseif field.type == FieldType.String then
                field.value = self.buffer:readString()
            else
                assert(false)
            end

            self.buffer:readInt()

            def.fields[field.id .. (field.level or 'NONE') .. (field.column or 'NONE')] = field
        end

        self.definitions[def.id] = def
    end
end]]

P['vendor/assets/objediting/core/objectwriter.lua'] = [[---@diagnostic disable: inject-field, undefined-field, undefined-doc-param
-- objectwriter.lua
-- @Author : Dencer (tdaddon@163.com)
-- @Link   : https://dengsir.github.io
-- @Date   : 7/12/2019, 11:17:25 AM

--- WC3 object field IDs are fixed-width 4 bytes (e.g. "Crs" → "Crs\0").
---@param id string
---@return string
local function padFourCC(id)
    if #id >= 4 then
        return id:sub(1, 4)
    end
    return id .. string.rep("\0", 4 - #id)
end

---@class ObjectWriter: object
---@param type DefinitionType
ObjectWriter = class('ObjectWriter')

---@param type DefinitionType
---@param version integer|nil
function ObjectWriter:constructor(type, version)
    self.type = type
    self.version = version or 2
    self.buffer = WriteBuffer:new()

    -- file version
    self.buffer:addInt(self.version)
end

---@return string
function ObjectWriter:getBuffer()
    return self.buffer:getBuffer()
end

---@param defs table<any, Definition>
function ObjectWriter:write(defs)
    defs = table.values(defs)

    table.sort(defs, function(a, b)
        return a.id < b.id
    end)

    local original = table.filter(defs, function(def)
        return not def.superId
    end)
    local custom = table.filter(defs, function(def)
        return def.superId
    end)

    self.buffer:addInt(#original)
    for def in vipairs(original) do
        self:writeDefinition(def)
    end

    self.buffer:addInt(#custom)
    for def in vipairs(custom) do
        self:writeDefinition(def)
    end
end

---@param def Definition
function ObjectWriter:writeDefinition(def)
    if self.type ~= def.type then
        error('', 2)
    end

    if def.superId then
        self.buffer:addString(def.superId)
        self.buffer:addString(def.id)
    else
        self.buffer:addString(def.id)
        self.buffer:addInt(0)
    end

    -- Reforged (file version >= 3) writes two extra ints in each object header
    -- between the IDs and the field count.
    if self.version >= 3 then
        self.buffer:addInt(1)
        self.buffer:addInt(0)
    end

    local fields = table.values(def.fields)

    self.buffer:addInt(#fields)

    for _, field in spairs(fields) do
        self.buffer:addString(padFourCC(field.id))
        self.buffer:addInt(field.type)

        if self.type == DefinitionType.Doodad or self.type == DefinitionType.Ability or self.type ==
            DefinitionType.Upgrade then
            self.buffer:addInt(field.level or 0)
            self.buffer:addInt(field.column or 0)
        end

        if field.type == FieldType.Int then
            self.buffer:addInt(field.value)
        elseif field.type == FieldType.Real or field.type == FieldType.Unreal then
            self.buffer:addFloat(field.value)
        elseif field.type == FieldType.String then
            self.buffer:addString(field.value)
            self.buffer:addNullTerminator()
        end

        if def.superId then
            self.buffer:addInt(0)
        else
            self.buffer:addString(def.id)
        end
    end
end

return ObjectWriter]]

P['vendor/assets/objediting/core/readbuffer.lua'] = [[-- readbuffer.lua
-- @Author : Dencer (tdaddon@163.com)
-- @Link   : https://dengsir.github.io
-- @Date   : 7/10/2019, 10:17:42 PM

---@class ReadBuffer: object
ReadBuffer = class('ReadBuffer')

function ReadBuffer:constructor(buffer)
    self.buf = buffer
    self.offset = 1
end

function ReadBuffer:readRaw(n)
    local buf = self.buf:sub(self.offset, self.offset + n - 1)
    self.offset = self.offset + n
    return buf
end

function ReadBuffer:readInt()
    return string.unpack('i4<', self:readRaw(4))
end

function ReadBuffer:readShort()
    return string.unpack('i2<', self:readRaw(2))
end

function ReadBuffer:readFloat()
    return string.unpack('f<', self:readRaw(4))
end

function ReadBuffer:readString(n)
    if n then
        return self:readRaw(n)
    end
    local s = {}
    while true do
        local char = self:readRaw(1)
        if char == '\0' then
            break
        end
        s[#s + 1] = char
    end
    return table.concat(s)
end

function ReadBuffer:readByte()
    return self:readRaw(1):byte(1)
end

return ReadBuffer]]

P['vendor/assets/objediting/core/writebuffer.lua'] = [[-- writebuffer.lua
-- @Author : Dencer (tdaddon@163.com)
-- @Link   : https://dengsir.github.io
-- @Date   : 7/10/2019, 8:03:06 PM

---@class WriteBuffer: object
WriteBuffer = class('WriteBuffer')

function WriteBuffer:constructor()
    self.buf = {}
end

function WriteBuffer:add(value)
    table.insert(self.buf, value)
end

function WriteBuffer:addString(value)
    self:add(value)
end

function WriteBuffer:addNullTerminator()
    self:add('\0')
end

function WriteBuffer:addNewLine()
    self:add('\r\n')
end

function WriteBuffer:addChar(value)
    if #value ~= 1 then
        error('bad argument', 2)
    end
    self:add(value)
end

function WriteBuffer:addInt(value)
    self:add(string.pack('i4<', value))
end

function WriteBuffer:addShort(value)
    self:add(string.pack('i2<', value))
end

function WriteBuffer:addFloat(value)
    self:add(string.pack('f<', value))
end

function WriteBuffer:addByte(value)
    self:add(string.char(value))
end

function WriteBuffer:getBuffer()
    return table.concat(self.buf)
end

return WriteBuffer]]

