-- ===========================================================================

---@param trig trigger
---@param whichEvent playerunitevent
function TriggerRegisterAnyUnitEventBJ(trig, whichEvent)
	local index

	index = 0
	while true do
		TriggerRegisterPlayerUnitEvent(trig, Player(index), whichEvent, nil)

		index = index + 1
		if index == bj_MAX_PLAYER_SLOTS then
			break
		end
	end
end

