---@param duration number
---@param permanent boolean
---@param where location
---@param radius number
---@param depth number
---@return terraindeformation
function TerrainDeformationCraterBJ(duration, permanent, where, radius, depth)
	bj_lastCreatedTerrainDeformation =
		TerrainDeformCrater(GetLocationX(where), GetLocationY(where), radius, depth, R2I(duration * 1000), permanent)
	return bj_lastCreatedTerrainDeformation
end

-- ===========================================================================

---@param duration number
---@param limitNeg boolean
---@param where location
---@param startRadius number
---@param endRadius number
---@param depth number
---@param wavePeriod number
---@param waveWidth number
---@return terraindeformation
function TerrainDeformationRippleBJ(duration, limitNeg, where, startRadius, endRadius, depth, wavePeriod, waveWidth)
	local spaceWave
	local timeWave
	local radiusRatio

	if endRadius <= 0 or waveWidth <= 0 or wavePeriod <= 0 then
		return nil
	end

	timeWave = 2.0 * duration / wavePeriod
	spaceWave = 2.0 * endRadius / waveWidth
	radiusRatio = startRadius / endRadius

	bj_lastCreatedTerrainDeformation = TerrainDeformRipple(
		GetLocationX(where),
		GetLocationY(where),
		endRadius,
		depth,
		R2I(duration * 1000),
		1,
		spaceWave,
		timeWave,
		radiusRatio,
		limitNeg
	)
	return bj_lastCreatedTerrainDeformation
end

-- ===========================================================================

---@param duration number
---@param source location
---@param target location
---@param radius number
---@param depth number
---@param trailDelay number
---@return terraindeformation
function TerrainDeformationWaveBJ(duration, source, target, radius, depth, trailDelay)
	local distance
	local dirX
	local dirY
	local speed

	distance = DistanceBetweenPoints(source, target)
	if distance == 0 or duration <= 0 then
		return nil
	end

	dirX = (GetLocationX(target) - GetLocationX(source)) / distance
	dirY = (GetLocationY(target) - GetLocationY(source)) / distance
	speed = distance / duration

	bj_lastCreatedTerrainDeformation = TerrainDeformWave(
		GetLocationX(source),
		GetLocationY(source),
		dirX,
		dirY,
		distance,
		speed,
		radius,
		depth,
		R2I(trailDelay * 1000),
		1
	)
	return bj_lastCreatedTerrainDeformation
end

-- ===========================================================================

---@param duration number
---@param where location
---@param radius number
---@param minDelta number
---@param maxDelta number
---@param updateInterval number
---@return terraindeformation
function TerrainDeformationRandomBJ(duration, where, radius, minDelta, maxDelta, updateInterval)
	bj_lastCreatedTerrainDeformation = TerrainDeformRandom(
		GetLocationX(where),
		GetLocationY(where),
		radius,
		minDelta,
		maxDelta,
		R2I(duration * 1000),
		R2I(updateInterval * 1000)
	)
	return bj_lastCreatedTerrainDeformation
end

