---@param lb leaderboard
---@param toForce force
function ForceSetLeaderboardBJ(lb, toForce)
	local index
	local indexPlayer

	index = 0
	while true do
		indexPlayer = Player(index)
		if IsPlayerInForce(indexPlayer, toForce) then
			PlayerSetLeaderboard(indexPlayer, lb)
		end
		index = index + 1
		if index == bj_MAX_PLAYERS then
			break
		end
	end
end

