-- ===========================================================================

---@param mb multiboard
---@param col integer
---@param row integer
---@param showValue boolean
---@param showIcon boolean
function MultiboardSetItemStyleBJ(mb, col, row, showValue, showIcon)
	local curRow = 0
	local curCol = 0
	local numRows = MultiboardGetRowCount(mb)
	local numCols = MultiboardGetColumnCount(mb)
	local mbitem = nil

	--  Loop over rows, using 1-based index
	while true do
		curRow = curRow + 1
		if curRow > numRows then
			break
		end

		--  Apply setting to the requested row, or all rows (if row is 0)
		if row == 0 or row == curRow then
			--  Loop over columns, using 1-based index
			curCol = 0
			while true do
				curCol = curCol + 1
				if curCol > numCols then
					break
				end

				--  Apply setting to the requested column, or all columns (if col is 0)
				if col == 0 or col == curCol then
					mbitem = MultiboardGetItem(mb, curRow - 1, curCol - 1)
					MultiboardSetItemStyle(mbitem, showValue, showIcon)
					MultiboardReleaseItem(mbitem)
				end
			end
		end
	end
end

-- ===========================================================================

---@param mb multiboard
---@param col integer
---@param row integer
---@param val string
function MultiboardSetItemValueBJ(mb, col, row, val)
	local curRow = 0
	local curCol = 0
	local numRows = MultiboardGetRowCount(mb)
	local numCols = MultiboardGetColumnCount(mb)
	local mbitem = nil

	--  Loop over rows, using 1-based index
	while true do
		curRow = curRow + 1
		if curRow > numRows then
			break
		end

		--  Apply setting to the requested row, or all rows (if row is 0)
		if row == 0 or row == curRow then
			--  Loop over columns, using 1-based index
			curCol = 0
			while true do
				curCol = curCol + 1
				if curCol > numCols then
					break
				end

				--  Apply setting to the requested column, or all columns (if col is 0)
				if col == 0 or col == curCol then
					mbitem = MultiboardGetItem(mb, curRow - 1, curCol - 1)
					MultiboardSetItemValue(mbitem, val)
					MultiboardReleaseItem(mbitem)
				end
			end
		end
	end
end

