P['vendor/ext/LinkedList.lua'] = [=[do
    --[[
        Doubly-Linked List v1.3.0.0 by Wrda, Eikonium and Bribe
        ------------------------------------------------------------------------------
        A script that allows the possibility to create a sequence of any object
        linked together.
        ------------------------------------------------------------------------------
    API:
        LinkedList.create(head) -> LinkedList
        - Creates or resets a table as a LinkedList head.
        - Allows a user-specified head or generates a new one.

        list:insert([node_or_value, after]) -> listNode
        - Inserts *before* the given list/node unless "after" is true.
        - If a "node or value" is passed, the system will check if the node is
          a table. If the table isn't yet part of a LinkedList structure, it
          will be converted into the node that is returned at the end of this
          function. If the table is a part of the LinkedList structure, or a
          different type of value than a table, then it will be assigned as a
          generic "value" (mapped to node.value)
        - Returns the inserted node that was added to the list (if addition was successful).

        list:remove(node) -> boolean
        - Removes a node from whatever list it is a part of and calls self:onRemove().
        - Returns true if it was sucessful.

        for node in list:loop([backwards]) do [stuff] end
        - Iterates over all nodes in "list".

        fromList:merge(intoList[, backwardsFrom, backwardsInto])
        - Removes all nodes from one list and adds them into another.

        list:reset() -> boolean
        - Removes all nodes from the given linked list, calling node:onRemove() on each.
        - Returns true if sucessful.

        - readonly list.n : integer -> the number of nodes in the list.
    ]]
    ---@class LinkedList:table
    ---@field head LinkedList
    ---@field next listNode|LinkedList
    ---@field prev listNode|LinkedList
    ---@field n integer
    LinkedList = {}
    LinkedList.__index = LinkedList

    ---@class listNode:LinkedList
    ---@field value? any
    ---@field remove fun(node:listNode)->boolean
    ---@field onRemove fun(self:listNode)

    ---Creates or resets a table as a LinkedList head.
    ---@param head? LinkedList allows a user-specified head or generates a new one.
    ---@return LinkedList?
    function LinkedList.create(head)
        if head and type(head) == "table" then
            local h = head.head
            if h then
                if h ~= head then
                    return nil --user passed an active ListNode. This is not allowed.
                end
                if h.n > 0 then --first empty any lists that still have nodes.
                    for node in head:loop() do
                        node:onRemove()
                    end
                end
            end
        else
            ---@diagnostic disable-next-line: missing-fields
            head = {}
        end
        setmetatable(head, LinkedList)
        head.next = head
        head.prev = head
        head.head = head
        head.n = 0
        return head
    end

    ---Node can be an existing table, or a new table will be created to represent the
    ---node. "list" can either be the head, or any point where you want the node to be
    ---inserted. It will insert *before* the given head/node, unless "backward" is true.
    ---@param list listNode|LinkedList
    ---@param node_or_value? any
    ---@param insertAfter? boolean
    ---@return listNode? node that was added to the list (if addition was successful)
    function LinkedList.insert(list, node_or_value, insertAfter)
        if not list then
            return nil
        end
        local head = list.head
        if not head then
            return nil
        end
        local node, value

        if node_or_value then
            if type(node_or_value) == "table" then
                if node_or_value.head then --table is already part of a linked list. Treat it as a "value"
                    value = node_or_value
                else
                    node = node_or_value --table will be transmuted into the linked list node itself.
                end
            else
                --User passed a non-table value.
                value = node_or_value
            end
        end
        if insertAfter then
            list = list.next
        end

        node = node or {} ---@type listNode
        setmetatable(node, LinkedList)
        list.prev.next = node
        node.prev = list.prev
        list.prev = node
        node.next = list
        node.head = head
        head.n = head.n + 1
        node.value = value
        node.onRemove = function()
            node.head = nil
        end
        return node
    end

    ---Removes a node from whatever list it is a part of. A node cannot be a part of
    ---more than one list at a time, so there is no need to pass the containing list as
    ---an argument.
    ---@param node listNode
    ---@return boolean wasRemoved
    function LinkedList:remove(node)
        node = node or self
        if node then
            local head = node.head
            if head and head ~= node then
                node.prev.next = node.next
                node.next.prev = node.prev
                head.n = head.n - 1
                node:onRemove()
                return true
            end
        end
        return false
    end

    ---Enables the generic for-loop for LinkedLists.
    ---Syntax: "for node in LinkedList.loop(list) do print(node) end"
    ---Alternative Syntax: "for node in list:loop() do print(node) end"
    ---@param list LinkedList
    ---@param backward? boolean
    function LinkedList.loop(list, backward)
        list = list.head
        local loopNode = list ---@type listNode
        local direction = backward and "prev" or "next"
        return function()
            loopNode = loopNode[direction]
            return loopNode ~= list and loopNode or nil
        end
    end

    ---Merges LinkedList "from" to another LinkedList "into"
    ---@param from LinkedList|listNode
    ---@param into LinkedList|listNode
    ---@param backwardFrom boolean
    ---@param backwardInto boolean
    function LinkedList.merge(from, into, backwardFrom, backwardInto)
        if from and from.head and into and into.head then
            local directionFrom = backwardFrom and "prev" or "next"
            local n, v
            local node = from[directionFrom]
            from = from.head
            while node ~= from do
                n, v = node[directionFrom], node.value
                node:remove()
                into:insert(node, backwardInto).value = v
                node = n
            end
        end
    end

    ---Removes all nodes from the given linked list.
    ---@param list LinkedList
    ---@return boolean was_reset
    function LinkedList.reset(list)
        return list:create() ~= nil
    end
end]=]

P['vendor/ext/Timed.lua'] = [=[--[[--------------------------------------------------------------------------------------
    Timed Call and Echo v2.0.1.0 by Bribe, special thanks to Eikonium and Jesus4Lyf

    Allows automatic timer tracking for the most common use cases (one-shot timers, and
    repeating timers that merge together for optimization).
----------------------------------------------------------------------------------------]]
do
    local _DEFAULT_ECHO_TIMEOUT = 0.03125
    local _EXIT_WHEN_FACTOR = 0.5 --Will potentially stop the echo before it has fully run
    --its course (via rounding). Set to 0 to disable. Can also override this from the Timed.echo 5th parameter.
    local zeroList, _ZERO_TIMER
    local timerLists = {}
    local insert = table.insert

    Timed = {
        --[[--------------------------------------------------------------------------------------
        Name: Timed.call
        Args: [delay, ]userFunc
        Desc: After "delay" seconds, call "userFunc". Delay defaults to 0 seconds.
    ----------------------------------------------------------------------------------------]]
        ---@overload fun(userFunc: function)
        ---@param delay? number|function
        ---@param userFunc? function
        ---@return (fun(doNotDestroy:boolean):number)?
        call = function(delay, userFunc)
            if type(delay) == "function" then
                userFunc, delay = delay, userFunc
            end
            if not delay or delay <= 0 then
                if zeroList then
                    insert(zeroList, userFunc)
                else
                    zeroList = { userFunc }
                    _ZERO_TIMER = _ZERO_TIMER or CreateTimer()
                    TimerStart(_ZERO_TIMER, 0, false, function()
                        local tempList = zeroList
                        zeroList = nil
                        for _, func in ipairs(tempList) do
                            func()
                        end
                    end)
                end
            else
                ---@type { handle: timer? }
                local timerRef = { handle = CreateTimer() }
                TimerStart(timerRef.handle, delay, false, function()
                    if timerRef.handle then
                        DestroyTimer(timerRef.handle)
                        timerRef.handle = nil
                    end
                    if userFunc then
                        userFunc()
                    end
                end)
                return function(doNotDestroy)
                    local result = 0
                    if timerRef.handle then
                        result = TimerGetRemaining(timerRef.handle)
                        if not doNotDestroy then
                            PauseTimer(timerRef.handle)
                            DestroyTimer(timerRef.handle)
                            timerRef.handle = nil
                        end
                    end
                    return result
                end
            end
            return nil
        end,

        --[[--------------------------------------------------------------------------------------
    Name: Timed.echo
    Args: [timeout, duration,] userFunc
    Desc: Calls userFunc every "timeout" seconds until userFunc returns true.
        -> will also stop calling userFunc if the duration is reached.
        -> Returns a function you can call to manually stop echoing the userFunc.
    --------------------------------------------------------------------------------------
    Note: This merges all matching timeouts together, so it is advisable only to use this
        for smaller numbers (e.g. <.3 seconds) where the difference is less noticeable.
    ----------------------------------------------------------------------------------------]]
        ---@overload fun(userFunc: fun():boolean)
        ---@param timeout? number|function
        ---@param duration? number|function
        ---@param userFunc? fun():boolean? -- if true, echo will stop
        ---@param onExpire? function     -- If the duration is specified and expiration occurs naturally, call this function.
        ---@param tolerance? number      -- Ranges from 0-1. If the duration is specified, the tolerance helps to measure the accuracy of the final tick.
        ---@return function remove_func
        echo = function(timeout, duration, userFunc, onExpire, tolerance)
            if type(timeout) == "function" then
                --parames align to original API of (function[,timeout])
                userFunc, timeout, duration = timeout, duration, userFunc
            elseif not userFunc then
                --params were (timeout,userFunc)
                userFunc, duration = duration, nil
                --else params were exactly as defined.
            end
            ---@type (fun():boolean?)?
            local cb = userFunc
            local wrapper = function()
                return not cb or cb() --this wrapper function allows manual removal to be understood and processed accordingly.
            end
            timeout = timeout or _DEFAULT_ECHO_TIMEOUT
            if duration then
                local old = wrapper
                local exitwhen = timeout * (tolerance or _EXIT_WHEN_FACTOR)
                wrapper = function() --this wrapper function enables automatic removal once the duration is reached.
                    if not old() then
                        duration = duration - timeout
                        if duration >= exitwhen then
                            return
                        elseif onExpire then
                            print(duration, exitwhen)
                            onExpire()
                        end
                    end
                    return true
                end
            else
                duration = 0
            end
            local timerList = timerLists[timeout]
            if timerList then
                local remaining = TimerGetRemaining(timerList.timer)
                if remaining >= timeout * 0.50 then
                    duration = duration + timeout --The delay is large enough to execute on the next tick, therefore increase the duration to avoid double-deducting.
                    insert(timerList, wrapper)
                elseif timerList.queue then
                    insert(timerList.queue, wrapper)
                else
                    timerList.queue = { wrapper }
                end
                duration = duration - remaining --decrease the duration to compensate for the extra remaining time before the next tick.
            else
                timerList = { wrapper }
                timerLists[timeout] = timerList
                timerList.timer = CreateTimer()
                TimerStart(timerList.timer, timeout, true, function()
                    local top = #timerList
                    for i = top, 1, -1 do
                        if timerList[i]() then --The userFunc is to be removed:
                            if i ~= top then
                                timerList[i] = timerList[top]
                            end
                            timerList[top] = nil
                            top = top - 1
                        end
                    end
                    if timerList.queue then --Now we can add the queued items to the main list
                        for i, func in ipairs(timerList.queue) do
                            timerList[top + i] = func
                        end
                        timerList.queue = nil
                    elseif top == 0 then --list is empty; clear its data.
                        timerLists[timeout] = nil
                        PauseTimer(timerList.timer)
                        DestroyTimer(timerList.timer)
                    end
                end)
            end
            return function(doNotDestroy)
                if not doNotDestroy then
                    cb = nil
                end
                return duration
            end
        end,
    }
end]=]

P['vendor/ext/TotalInitialization.lua'] = [=[if Debug then
    Debug.beginFile("TotalInitialization")
end
--[[——————————————————————————————————————————————————————
    Total Initialization version 5.3.1
    Created by: Bribe
    Contributors: Eikonium, HerlySQR, Tasyen, Luashine, Forsakn
    Inspiration: Almia, ScorpioT1000, Troll-Brain
    Hosted at: https://github.com/BribeFromTheHive/Lua/blob/master/TotalInitialization.lua
    Debug library hosted at: https://www.hiveworkshop.com/threads/debug-utils-ingame-console-etc.330758/
————————————————————————————————————————————————————————————]]

---Calls the user's initialization function during the map's loading process. The first argument should either be the init function,
---or it should be the string to give the initializer a name (works similarly to a module name/identically to a vJass library name).
---
---To use requirements, call `Require.strict 'LibraryName'` or `Require.optional 'LibraryName'`. Alternatively, the OnInit callback
---function can take the `Require` table as a single parameter: `OnInit(function(import) import.strict 'ThisIsTheSameAsRequire' end)`.
---
-- - `OnInit.global` or just `OnInit` is called after InitGlobals and is the standard point to initialize.
-- - `OnInit.trig` is called after InitCustomTriggers, and is useful for removing hooks that should only apply to GUI events.
-- - `OnInit.map` is the last point in initialization before the loading screen is completed.
-- - `OnInit.final` occurs immediately after the loading screen has disappeared, and the game has started.
---@class OnInit
--
--Simple Initialization without declaring a library name:
---@overload async fun(initCallback: Initializer.Callback)
--
--Advanced initialization with a library name and an optional third argument to signal to Eikonium's DebugUtils that the file has ended.
---@overload async fun(libraryName: string, initCallback: Initializer.Callback, debugLineNum?: integer)
--
--A way to yield your library to allow other libraries in the same initialization sequence to load, then resume once they have loaded.
---@overload async fun(customInitializerName: string)
OnInit = {}

---@alias Initializer.Callback fun(require?: Requirement | {[string]: Requirement}):...?

---@alias Requirement async fun(reqName: string, source?: table): unknown

-- `Require` will yield the calling `OnInit` initialization function until the requirement (referenced as a string) exists. It will check the
-- global API (for example, does 'GlobalRemap' exist) and then check for any named OnInit resources which might use that same string as its name.
--
-- Due to the way Sumneko's syntax highlighter works, the return value will only be linted for defined @class objects (and doesn't work for regular
-- globals like `TimerStart`). I tried to request the functionality here: https://github.com/sumneko/lua-language-server/issues/1792 , however it
-- was closed. Presumably, there are other requests asking for it, but I wouldn't count on it.
--
-- To declare a requirement, use: `Require.strict 'SomeLibrary'` or (if you don't care about the missing linting functionality) `Require 'SomeLibrary'`
--
-- To optionally require something, use any other suffix (such as `.optionally` or `.nonstrict`): `Require.optional 'SomeLibrary'`
--
---@class Require: { [string]: Requirement }
---@overload async fun(reqName: string, source?: table): string
Require = {}
do
    local library = {} --You can change this to false if you don't use `Require` nor the `OnInit.library` API.

    --CONFIGURABLE LEGACY API FUNCTION:
    ---@param _ENV table
    ---@param OnInit any
    local function assignLegacyAPI(_ENV, OnInit)
        OnGlobalInit = OnInit
        OnTrigInit = OnInit.trig
        OnMapInit = OnInit.map
        OnGameStart = OnInit.final --Global Initialization Lite API
        --OnMainInit = OnInit.main; OnLibraryInit = OnInit.library; OnGameInit = OnInit.final                            --short-lived experimental API
        --onGlobalInit = OnInit; onTriggerInit = OnInit.trig; onInitialization = OnInit.map; onGameStart = OnInit.final  --original Global Initialization API
        --OnTriggerInit = OnInit.trig; OnInitialization = OnInit.map                                                     --Forsakn's Ordered Indices API
    end
    --END CONFIGURABLES

    local _G, rawget, insert = _G, rawget, table.insert

    local initFuncQueue = {}

    ---@param name string
    ---@param continue? function
    local function runInitializers(name, continue)
        --print('running:', name, tostring(initFuncQueue[name]))
        if initFuncQueue[name] then
            for _, func in ipairs(initFuncQueue[name]) do
                coroutine.wrap(func)(Require)
            end
            initFuncQueue[name] = nil
        end
        if library then
            library:resume()
        end
        if continue then
            continue()
        end
    end

    local function initEverything()
        ---@param hookName string
        ---@param continue? function
        local function hook(hookName, continue)
            local hookedFunc = rawget(_G, hookName)
            if hookedFunc then
                rawset(_G, hookName, function()
                    hookedFunc()
                    runInitializers(hookName, continue)
                end)
            else
                runInitializers(hookName, continue)
            end
        end

        hook("InitGlobals", function()
            hook("InitCustomTriggers", function()
                hook("RunInitializationTriggers")
            end)
        end)

        hook("MarkGameStarted", function()
            if library then
                for _, func in ipairs(library.queuedInitializerList) do
                    func(nil, true) --run errors for missing requirements.
                end
                for _, func in pairs(library.yieldedModuleMatrix) do
                    func(true) --run errors for modules that aren't required.
                end
            end
            OnInit = nil
            Require = nil
        end)
    end

    ---@param initName       string
    ---@param libraryName    string | Initializer.Callback
    ---@param func?          Initializer.Callback
    ---@param debugLineNum?  integer
    ---@param incDebugLevel? boolean
    local function addUserFunc(initName, libraryName, func, debugLineNum, incDebugLevel)
        if not func then
            ---@cast libraryName Initializer.Callback
            func = libraryName
        else
            assert(type(libraryName) == "string")
            if debugLineNum and Debug then
                Debug.beginFile(libraryName, incDebugLevel and 3 or 2)
                Debug.data.sourceMap[#Debug.data.sourceMap].lastLine = debugLineNum
            end
            if library then
                func = library:create(libraryName, func)
            end
        end
        assert(type(func) == "function")

        --print('adding user func: ' , initName , libraryName, debugLineNum, incDebugLevel)

        initFuncQueue[initName] = initFuncQueue[initName] or {}
        insert(initFuncQueue[initName], func)

        if initName == "root" or initName == "module" then
            runInitializers(initName)
        end
    end

    ---@param name string
    local function createInit(name)
        ---@async
        ---@param libraryName string                --Assign your callback a unique name, allowing other OnInit callbacks can use it as a requirement.
        ---@param userInitFunc Initializer.Callback --Define a function to be called at the chosen point in the initialization process. It can optionally take the `Require` object as a parameter. Its optional return value(s) are passed to a requiring library via the `Require` object (defaults to `true`).
        ---@param debugLineNum? integer             --If the Debug library is present, you can call Debug.getLine() for this parameter (which should coincide with the last line of your script file). This will neatly tie-in with OnInit's built-in Debug library functionality to define a starting line and an ending line for your module.
        ---@overload async fun(userInitFunc: Initializer.Callback)
        return function(libraryName, userInitFunc, debugLineNum)
            addUserFunc(name, libraryName, userInitFunc, debugLineNum)
        end
    end
    OnInit.global = createInit("InitGlobals") -- Called after InitGlobals, and is the standard point to initialize.
    OnInit.trig = createInit("InitCustomTriggers") -- Called after InitCustomTriggers, and is useful for removing hooks that should only apply to GUI events.
    OnInit.map = createInit("RunInitializationTriggers") -- Called last in the script's loading screen sequence. Runs after the GUI "Map Initialization" events have run.
    OnInit.final = createInit("MarkGameStarted") -- Called immediately after the loading screen has disappeared, and the game has started.

    do
        ---@param self table
        ---@param libraryNameOrInitFunc function | string
        ---@param userInitFunc function
        ---@param debugLineNum number
        local function __call(self, libraryNameOrInitFunc, userInitFunc, debugLineNum)
            if userInitFunc or type(libraryNameOrInitFunc) == "function" then
                addUserFunc(
                    "InitGlobals", --Calling OnInit directly defaults to OnInit.global (AKA OnGlobalInit)
                    libraryNameOrInitFunc,
                    userInitFunc,
                    debugLineNum,
                    true
                )
            elseif library then
                library:declare(libraryNameOrInitFunc) --API handler for OnInit "Custom initializer"
            else
                error("Bad OnInit args: " .. tostring(libraryNameOrInitFunc) .. ", " .. tostring(userInitFunc))
            end
        end
        setmetatable(OnInit --[[@as table]], { __call = __call })
    end

    do --if you don't need the initializers for 'root', 'config' and 'main', you can delete this do...end block.
        local gmt = getmetatable(_G) or getmetatable(setmetatable(_G, {}))

        local rawIndex = gmt.__newindex or rawset

        local hookMainAndConfig
        ---@param _G table
        ---@param key string
        ---@param fnOrDiscard unknown
        function hookMainAndConfig(_G, key, fnOrDiscard)
            if key == "main" or key == "config" then
                ---@cast fnOrDiscard function
                if key == "main" then
                    runInitializers("root")
                end
                rawIndex(_G, key, function()
                    if key == "config" then
                        fnOrDiscard()
                    elseif gmt.__newindex == hookMainAndConfig then
                        gmt.__newindex = rawIndex --restore the original __newindex if no further hooks on __newindex exist.
                    end
                    runInitializers(key)
                    if key == "main" then
                        fnOrDiscard()
                    end
                end)
            else
                rawIndex(_G, key, fnOrDiscard)
            end
        end
        gmt.__newindex = hookMainAndConfig
        OnInit.root = createInit("root") -- Runs immediately during the Lua root, but is yieldable (allowing requirements) and pcalled.
        OnInit.config = createInit("config") -- Runs when `config` is called. Credit to @Luashine: https://www.hiveworkshop.com/threads/inject-main-config-from-we-trigger-code-like-jasshelper.338201/
        OnInit.main = createInit("main") -- Runs when `main` is called. Idea from @Tasyen: https://www.hiveworkshop.com/threads/global-initialization.317099/post-3374063
    end
    if library then
        library.queuedInitializerList = {}
        library.customDeclarationList = {}
        library.yieldedModuleMatrix = {}
        library.moduleValueMatrix = {}

        function library:pack(name, ...)
            self.moduleValueMatrix[name] = table.pack(...)
        end

        function library:resume()
            if self.queuedInitializerList[1] then
                local continue, tempQueue, forceOptional

                ::initLibraries::
                repeat
                    continue = false
                    self.queuedInitializerList, tempQueue = {}, self.queuedInitializerList

                    for _, func in ipairs(tempQueue) do
                        if func(forceOptional) then
                            continue = true --Something was initialized; therefore further systems might be able to initialize.
                        else
                            insert(self.queuedInitializerList, func) --If the queued initializer returns false, that means its requirement wasn't met, so we re-queue it.
                        end
                    end
                until not continue or not self.queuedInitializerList[1]

                if self.customDeclarationList[1] then
                    self.customDeclarationList, tempQueue = {}, self.customDeclarationList
                    for _, func in ipairs(tempQueue) do
                        func() --unfreeze any custom initializers.
                    end
                elseif not forceOptional then
                    forceOptional = true
                else
                    return
                end
                goto initLibraries
            end
        end
        local function declareName(name, initialValue)
            assert(type(name) == "string")
            assert(library.moduleValueMatrix[name] == nil)
            library.moduleValueMatrix[name] = initialValue and { true, n = 1 }
        end
        function library:create(name, userFunc)
            assert(type(userFunc) == "function")
            declareName(name, false) --declare itself as a non-loaded library.
            return function()
                self:pack(name, userFunc(Require)) --pack return values to allow multiple values to be communicated.
                if self.moduleValueMatrix[name].n == 0 then
                    self:pack(name, true) --No values were returned; therefore simply package the value as `true`
                end
            end
        end

        ---@async
        function library:declare(name)
            declareName(name, true) --declare itself as a loaded library.

            local co = coroutine.running()

            insert(self.customDeclarationList, function()
                coroutine.resume(co)
            end)
            coroutine.yield() --yields the calling function until after all currently-queued initializers have run.
        end

        local processRequirement

        ---@async
        function processRequirement(optional, requirement, explicitSource)
            if type(optional) == "string" then
                optional, requirement, explicitSource = true, optional, requirement --optional requirement (processed by the __index method)
            else
                optional = false --strict requirement (processed by the __call method)
            end
            local source = explicitSource or _G

            assert(type(source) == "table")
            assert(type(requirement) == "string")

            ::reindex::
            local subSource, subReq = requirement:match("([\x25w_]+)\x25.(.+)") --Check if user is requiring using "table.property" syntax
            if subSource and subReq then
                source, requirement =
                    processRequirement(subSource, source), --If the container is nil, yield until it is not.
                    subReq

                if type(source) == "table" then
                    explicitSource = source
                    goto reindex --check for further nested properties ("table.property.subProperty.anyOthers").
                else
                    return --The source table for the requirement wasn't found, so disregard the rest (this only happens with optional requirements).
                end
            end
            local function loadRequirement(unpack)
                local package = rawget(source, requirement) --check if the requirement exists in the host table.
                if not package and not explicitSource then
                    if library.yieldedModuleMatrix[requirement] then
                        library.yieldedModuleMatrix[requirement]() --load module if it exists
                    end
                    package = library.moduleValueMatrix[requirement] --retrieve the return value from the module.
                    if unpack and type(package) == "table" then
                        return table.unpack(package, 1, package.n) --using unpack allows any number of values to be returned by the required library.
                    end
                end
                return package
            end

            local co, loaded

            local function checkReqs(forceOptional, printErrors)
                if not loaded then
                    loaded = loadRequirement()
                    loaded = loaded or optional and (loaded == nil or forceOptional)
                    if loaded then
                        if co then
                            coroutine.resume(co)
                        end --resume only if it was yielded in the first place.
                        return loaded
                    elseif printErrors then
                        coroutine.resume(co, true)
                    end
                end
            end

            if not checkReqs() then --only yield if the requirement doesn't already exist.
                co = coroutine.running()
                insert(library.queuedInitializerList, checkReqs)
                if coroutine.yield() then
                    error("Missing Requirement: " .. requirement) --handle the error within the user's function to get an accurate stack trace via the `try` function.
                end
            end

            return loadRequirement(true)
        end

        ---@type Requirement
        function Require.strict(name, explicitSource)
            return processRequirement(nil, name, explicitSource)
        end

        setmetatable(Require --[[@as table]], {
            __call = processRequirement,
            __index = function()
                return processRequirement
            end,
        })

        local module = createInit("module")

        --- `OnInit.module` will only call the OnInit function if the module is required by another resource, rather than being called at a pre-
        --- specified point in the loading process. It works similarly to Go, in that including modules in your map that are not actually being
        --- required will throw an error message.
        ---@param name          string
        ---@param func          fun(require?: Initializer.Callback):any
        ---@param debugLineNum? integer
        OnInit.module = function(name, func, debugLineNum)
            if func then
                local userFunc = func
                func = function(require)
                    local co = coroutine.running()

                    library.yieldedModuleMatrix[name] = function(failure)
                        library.yieldedModuleMatrix[name] = nil
                        coroutine.resume(co, failure)
                    end

                    if coroutine.yield() then
                        error("Module declared but not required: " .. name)
                    end

                    return userFunc(require)
                end
            end
            module(name, func, debugLineNum)
        end
    end

    if assignLegacyAPI then --This block handles legacy code.
        ---Allows packaging multiple requirements into one table and queues the initialization for later.
        ---@deprecated
        ---@param initList string | table
        ---@param userFunc function
        function OnInit.library(initList, userFunc)
            local typeOf = type(initList)

            assert(typeOf == "table" or typeOf == "string")
            assert(type(userFunc) == "function")

            local function caller(use)
                if typeOf == "string" then
                    use(initList)
                else
                    for _, initName in ipairs(initList) do
                        use(initName)
                    end
                    if initList.optional then
                        for _, initName in ipairs(initList.optional) do
                            use.lazily(initName)
                        end
                    end
                end
            end
            if initList.name then
                OnInit(initList.name, caller)
            else
                OnInit(caller)
            end
        end

        local legacyTable = {}

        assignLegacyAPI(legacyTable, OnInit)

        for key, func in pairs(legacyTable) do
            rawset(_G, key, func)
        end

        OnInit.final(function()
            for key in pairs(legacyTable) do
                rawset(_G, key, nil)
            end
        end)
    end

    initEverything()
end
if Debug then
    Debug.endFile()
end]=]

P['vendor/ext/WarcraftStudioCode/AsyncControlHandler.lua'] = [=[if Debug then
    Debug.beginFile("AsyncControlHandler")
end
---@version 1.0
if not AsyncControl then
    --[[
    =============================================================================================================================================================
                                                                    Async Control Handler
                                                                        by Antares
                                                                           v1.0

                                    Requires:
                                    AsyncControlHandler

    =============================================================================================================================================================
                                                                        C O N F I G
    =============================================================================================================================================================
    ]]

    local INTERVAL = 0.01

    --[[
    =============================================================================================================================================================
                                                                           A P I
    =============================================================================================================================================================

    AsyncControl.Register(eventData) -> event           Registers an asynchronous control from the provided data table. The data table can hold the following fields:

                                                        oskey? oskeytype
                                                        mouseButton? mousebuttontype
                                                        metakey? integer | integer[]
                                                        exactMetakey? boolean
                                                        onPress? function
                                                        onRelease? function
                                                        whilePressed? function
                                                        delay? number
                                                        interval? number

                                                        Either oskey or mouseButton must be set. Metakey controls which modifier keys (Shift, Ctrl, Alt, Win) must be
                                                        pressed for the event to activate. The integer value should be set to the sum of all metakeys that must be
                                                        pressed, for example METAKEY_SHIFT + METAKEY_CTRL. If metakey is a table, all metakey values in that table are
                                                        allowed. exactMetakey controls whether additional metakeys are allowed or if exactly that combination needs to
                                                        be pressed. onPress is called when the key or mouse button is first pressed, onRelease when it is released,
                                                        and whilePressed is periodically called while the key is pressed, either at the specified interval or at the
                                                        minimum interval set in the config. The delay parameter controls how long the key must be pressed for the
                                                        whilePressed event to first fire.

    AsyncControl.Remove(whichEvent)                     Disables an AsyncControl returned by AsyncControl.Register.

    =============================================================================================================================================================
    ]]

    local oskeyChecksOfMetakey = setmetatable({}, {
        __index = function(self, key)
            self[key] = {}
            return self[key]
        end,
    })
    local eventsOfKeyAndMetakey = setmetatable({}, {
        __index = function(self, key)
            self[key] = {}
            return self[key]
        end,
    })
    local mouseChecksOfMetakey = setmetatable({}, {
        __index = function(self, key)
            self[key] = {}
            return self[key]
        end,
    })
    local eventsOfMouseAndMetakey = setmetatable({}, {
        __index = function(self, key)
            self[key] = {}
            return self[key]
        end,
    })
    local activeEvents = {}

    local timeElapsed = 0

    local function MainLoop()
        MouseScreenX = BlzPixelToFrameX(BlzGetMouseScreenPosX())
        MouseScreenY = BlzPixelToFrameY(BlzGetMouseScreenPosY())

        local metakey = (BlzIsMetaKeyPressed(METAKEY_SHIFT) and METAKEY_SHIFT or 0)
            + (BlzIsMetaKeyPressed(METAKEY_CTRL) and METAKEY_CTRL or 0)
            + (BlzIsMetaKeyPressed(METAKEY_ALT) and METAKEY_ALT or 0)
            + (BlzIsMetaKeyPressed(METAKEY_WINKEYS) and METAKEY_WINKEYS or 0)

        local events, event

        timeElapsed = timeElapsed + INTERVAL

        for oskey, __ in next, oskeyChecksOfMetakey[metakey] do
            if BlzIsKeyPressed(oskey) then
                events = eventsOfKeyAndMetakey[metakey][oskey]
                for i = 1, #events do
                    event = events[i]
                    if not event.isActive then
                        event.isActive = true
                        event.timeOfPress = timeElapsed
                        event.lastPeriodic = timeElapsed
                        activeEvents[#activeEvents + 1] = event
                        if event.onPress then
                            event.onPress()
                        end
                    elseif
                        event.whilePressed
                        and (not event.delay or timeElapsed >= event.timeOfPress + event.delay)
                        and (
                            not event.interval and timeElapsed > event.lastPeriodic
                            or timeElapsed >= event.lastPeriodic + event.interval
                        )
                    then
                        event.whilePressed(timeElapsed - event.timeOfPress)
                        event.lastPeriodic = timeElapsed
                    end
                    event.lastCheck = timeElapsed
                end
            end
        end

        for mouseButton, __ in next, mouseChecksOfMetakey[metakey] do
            if BlzIsMouseButtonPressed(mouseButton) then
                events = eventsOfMouseAndMetakey[metakey][mouseButton]
                for i = 1, #events do
                    event = events[i]
                    if not event.isActive then
                        event.isActive = true
                        event.timeOfPress = timeElapsed
                        event.lastPeriodic = timeElapsed
                        activeEvents[#activeEvents + 1] = event
                        if event.onPress then
                            event.onPress()
                        end
                    elseif
                        event.whilePressed
                        and (not event.delay or timeElapsed >= event.timeOfPress + event.delay)
                        and (
                            not event.interval and timeElapsed > event.lastPeriodic
                            or timeElapsed >= event.lastPeriodic + event.interval
                        )
                    then
                        event.whilePressed(timeElapsed - event.timeOfPress)
                        event.lastPeriodic = timeElapsed
                    end
                    event.lastCheck = timeElapsed
                end
            end
        end

        for i = #activeEvents, 1, -1 do
            if activeEvents[i].lastCheck < timeElapsed then
                if activeEvents[i].onRelease then
                    activeEvents[i].onRelease(timeElapsed - activeEvents[i].timeOfPress)
                end
                activeEvents[i].isActive = false
                table.remove(activeEvents, i)
            end
        end
    end

    AsyncControl = {
        ---Registers an asynchronous control from the provided data table. The data table can hold the following fields:
        -- - oskey? oskeytype
        -- - mouseButton? mousebuttontype
        -- - metakey? integer | integer[]
        -- - exactMetakey? boolean
        -- - onPress? function
        -- - onRelease? function
        -- - whilePressed? function
        -- - delay? number
        -- - interval? number
        ---
        ---Either oskey or mouseButton must be set. Metakey controls which modifier keys (Shift, Ctrl, Alt, Win) must be pressed for the event to activate. The integer value should be set to the sum of all metakeys that must be pressed, for example METAKEY_SHIFT + METAKEY_CTRL. If metakey is a table, all metakey values in that table are allowed. exactMetakey controls whether additional metakeys are allowed or if exactly that combination needs to be pressed. onPress is called when the key or mouse button is first pressed, onRelease when it is released, and whilePressed is periodically called while the key is pressed, either at the specified interval or at the minimum interval set in the config. The delay parameter controls how long the key must be pressed for the whilePressed event to first fire.
        ---@param eventData table
        ---@return table
        Register = function(eventData)
            local self = {
                oskey = eventData.oskey,
                mouseButton = eventData.mouseButton,
                metakeys = {},
                onPress = type(eventData.onPress) == "string" and eventData[eventData.onPress] or eventData.onPress,
                onRelease = type(eventData.onRelease) == "string" and eventData[eventData.onRelease]
                    or eventData.onRelease,
                whilePressed = type(eventData.whilePressed) == "string" and eventData[eventData.whilePressed]
                    or eventData.whilePressed,
                delay = eventData.delay,
                interval = eventData.interval,
                isActive = false,
            }

            local eventTable, checkTable, button
            if eventData.oskey then
                eventTable = eventsOfKeyAndMetakey
                checkTable = oskeyChecksOfMetakey
                button = self.oskey
            elseif eventData.mouseButton then
                eventTable = eventsOfMouseAndMetakey
                checkTable = mouseChecksOfMetakey
                button = self.mouseButton
            else
                error("eventData is missing either oskey or mouseButton field.")
            end

            if type(eventData.metakey) == "number" then
                if eventData.exactMetakey or eventData.metakey == 0 then
                    checkTable[eventData.metakey][button] = true
                    eventTable[eventData.metakey][button] = eventTable[eventData.metakey][button] or {}
                    eventTable[eventData.metakey][button][#eventTable[eventData.metakey][button] + 1] = self
                    self.metakeys[1] = eventData.metakey
                else
                    for i = 0, 15 do
                        if i & eventData.metakey > 0 then
                            checkTable[i][button] = true
                            eventTable[i][button] = eventTable[i][button] or {}
                            eventTable[i][button][#eventTable[i][button] + 1] = self
                            self.metakeys[#self.metakeys + 1] = i
                        end
                    end
                end
            elseif type(eventData.metakey) == "table" then
                for i = 1, #eventData.metakey do
                    checkTable[eventData.metakey[i]][button] = true
                    eventTable[eventData.metakey[i]][button] = eventTable[eventData.metakey[i]][button] or {}
                    eventTable[eventData.metakey[i]][button][#eventTable[eventData.metakey[i]][button] + 1] = self
                    self.metakeys[#self.metakeys + 1] = eventData.metakey[i]
                end
            else
                for i = 0, 15 do
                    checkTable[i][button] = true
                    eventTable[i][button] = eventTable[i][button] or {}
                    eventTable[i][button][#eventTable[i][button] + 1] = self
                    self.metakeys[#self.metakeys + 1] = i
                end
            end

            return self
        end,

        ---@param whichEvent table
        Remove = function(whichEvent)
            local eventTable, checkTable
            local button
            if whichEvent.oskey then
                eventTable = eventsOfKeyAndMetakey
                checkTable = oskeyChecksOfMetakey
                button = whichEvent.oskey
            else
                eventTable = eventsOfMouseAndMetakey
                checkTable = mouseChecksOfMetakey
                button = whichEvent.mouseButton
            end

            local event
            for __, metakey in ipairs(whichEvent.metakeys) do
                for i = 1, #eventTable[metakey][button] do
                    event = eventTable[metakey][button][i]
                    if event == whichEvent then
                        table.remove(eventTable[metakey][button], i)
                        if #eventTable[metakey][button] == 0 then
                            checkTable[metakey][button] = nil
                        end
                        break
                    end
                end
            end

            if whichEvent.isActive then
                for j = 1, #activeEvents do
                    if activeEvents[j] == whichEvent then
                        table.remove(activeEvents, j)
                        return
                    end
                end
            end
        end,
    }

    local old = InitGlobals
    InitGlobals = function()
        old()
        TimerStart(CreateTimer(), INTERVAL, true, MainLoop)
    end
end]=]

P['vendor/ext/WarcraftStudioCode/FileIO.lua'] = [=[if Debug then
    Debug.beginFile("FileIO")
end
--[[
    FileIO v2

    Author: Trokkin
    Updated by Antares

    Provides functionality to read and write files, optimized with lua functionality in mind.

    API:

        FileIO.Save(filename, data)
            - Write string data to a file

        FileIO.Load(filename) -> string?
            - Read string data from a file. Returns nil if file doesn't exist.

        FileIO.SaveAsserted(filename, data, onFail?) -> bool
            - Saves the file and checks that it was saved successfully.
              If it fails, passes (filename, data, loadResult) to onFail.

    Optional requirements:
        DebugUtils by Eikonium                          @ https://www.hiveworkshop.com/threads/330758/

    Inspired by:
        - TriggerHappy's Codeless Save and Load         @ https://www.hiveworkshop.com/threads/278664/
        - ScrewTheTrees's Codeless Save/Sync concept    @ https://www.hiveworkshop.com/threads/325749/
        - Luashine's LUA variant of TH's FileIO         @ https://www.hiveworkshop.com/threads/307568/post-3519040
        - HerlySQR's LUA variant of TH's Save/Load      @ https://www.hiveworkshop.com/threads/331536/post-3565884

    Updated: 15 June 2025
--]]
do
    local RAW_PREFIX = "]]i([["
    local RAW_SUFFIX = "]])--[["
    local RAW_SIZE = 255 - #RAW_PREFIX - #RAW_SUFFIX
    local LOAD_ABILITY = FourCC("ANdc")
    local LOAD_EMPTY_KEY = "!@#$, empty data"

    local name

    local function open(filename)
        name = filename
        PreloadGenClear()
        Preload('")\nendfunction\n//!beginusercode\nlocal p={} local i=function(s) table.insert(p,s) end--[[')
    end

    local function write(s)
        --Avoid ]] in string.
        s = s:gsub("\x25]", "!]")
        --Repeated backslash literals are not processed correctly by the Preload natives.
        s = s:gsub("\\", "!\\")
        local i = 1
        local size = #s
        local pos, __, num, str
        repeat
            pos = i + RAW_SIZE - 1
            str = s:sub(i, pos)
            --Backslashes increase preload string size in file, causing the suffix to get swallowed, which in turn causes a crash.
            __, num = str:gsub("\\", "")
            pos = pos - num
            --A ] at the end of a preload string will crash the game. A newline character at the beginning will be swallowed.
            while s:sub(pos, pos) == "]" or s:sub(pos + 1, pos + 1) == "\n" do
                pos = pos - 1
            end
            Preload(RAW_PREFIX .. s:sub(i, pos) .. RAW_SUFFIX)
            i = pos + 1
        until i > size
    end

    local function close()
        Preload(
            "]]BlzSetAbilityTooltip("
                .. LOAD_ABILITY
                .. ", table.concat(p), 0)\n//!endusercode\nfunction a takes nothing returns nothing\n//"
        )
        PreloadGenEnd(name)
        name = nil
    end

    ---@param filename string
    ---@param data string
    local function savefile(filename, data)
        open(filename)
        write(data)
        close()
    end

    ---@param filename string
    ---@return string?
    local function loadfile(filename)
        local s = BlzGetAbilityTooltip(LOAD_ABILITY, 0)
        BlzSetAbilityTooltip(LOAD_ABILITY, LOAD_EMPTY_KEY, 0)
        Preloader(filename)
        local loaded = BlzGetAbilityTooltip(LOAD_ABILITY, 0)
        BlzSetAbilityTooltip(LOAD_ABILITY, s, 0)
        if loaded == LOAD_EMPTY_KEY then
            return nil
        end
        Preloader("")
        loaded = loaded:gsub("!\x25]", "]"):gsub("!\\\\", "\\")
        return loaded
    end

    ---@param filename string
    ---@param data string
    ---@param onFail function?
    ---@return boolean
    local function saveAsserted(filename, data, onFail)
        savefile(filename, data)
        local res = loadfile(filename)
        if res == data then
            return true
        end
        if onFail then
            onFail(filename, data, res)
        end
        return false
    end

    FileIO = {
        Save = savefile,
        Load = loadfile,
        SaveAsserted = saveAsserted,
    }
end]=]

P['vendor/ext/WarcraftStudioCode/HandleType.lua'] = [=[if Debug then
    Debug.beginFile("HandleType")
end
do
    --[[
    ===============================================================================================================================================================
                                                                        Handle Type
                                                                        by Antares
    ===============================================================================================================================================================
    
    Determine the type of a Wacraft 3 object (handle). The result is stored in a table on the first execution to increase performance.

    HandleType[whichHandle]     -> string           Returns an empty string if variable is not a handle.
    IsHandle[whichHandle]       -> boolean
    IsWidget[whichHandle]       -> boolean
    IsUnit[whichHandle]         -> boolean

    These can also be called as a function, which has a nil-check, but is slower than the table-lookup

    ===============================================================================================================================================================
    ]]

    local widgetTypes = {
        unit = true,
        destructable = true,
        item = true,
    }

    HandleType = setmetatable({}, {
        __mode = "k",
        __index = function(self, key)
            if type(key) == "userdata" then
                local str = tostring(key)
                self[key] = str:sub(1, (str:find(":", nil, true) or 0) - 1)
                return self[key]
            else
                self[key] = ""
                return ""
            end
        end,
        __call = function(self, key)
            if key then
                return self[key]
            else
                return ""
            end
        end,
    })

    IsHandle = setmetatable({}, {
        __mode = "k",
        __index = function(self, key)
            self[key] = HandleType[key] ~= ""
            return self[key]
        end,
        __call = function(self, key)
            if key then
                return self[key]
            else
                return false
            end
        end,
    })

    IsWidget = setmetatable({}, {
        __mode = "k",
        __index = function(self, key)
            self[key] = widgetTypes[HandleType[key]] == true
            return self[key]
        end,
        __call = function(self, key)
            if key then
                return self[key]
            else
                return false
            end
        end,
    })

    IsUnit = setmetatable({}, {
        __mode = "k",
        __index = function(self, key)
            self[key] = HandleType[key] == "unit"
            return self[key]
        end,
        __call = function(self, key)
            if key then
                return self[key]
            else
                return false
            end
        end,
    })
end
if Debug then
    Debug.endFile()
end]=]

P['vendor/ext/WarcraftStudioCode/WSCodeConfig.lua'] = [[if Debug then
    Debug.beginFile("WSCodeConfig")
end
do
    WSCodeConfig = {
        compiler = {
            --Disables the editor and all code alterations. Overwrites all settings below.
            RELEASE_VERSION = false
            --If enabled, WSCode will wrap coroutines around everything, allowing it to yield from the parent function on a breakpoint insteayd of just the function that
            --was added to the debugger. This means that if an external function calls a function that is being debugged, the parent function will not continue executing
            --when the function being debugged is halted. In addition, the complete traceback will be available on an error. This feature slows down code execution, even
            --with all WSCode wrappers removed, so set it to false for your release version. WARNING: This option breaks GUI waits.
,
            WRAP_ALL_LUA_ENTRY_POINTS = true
            --If WRAP_ALL_LUA_ENTRY_POINTS is enabled, GUI waits will break unless this option is also enabled. Enabling this will heavily slow down trigger actions.
,
            DO_NOT_BREAK_GUI_WAITS = false
            --Overwrites all OnInit functions with the corresponding WSCode init funtions. The Require function is not supported and must be replaced with @require
            -- tokens manually. OnInit.root, OnInit.module, and OnInit.config must be removed if TotalInitialization is removed from the map script. If TotalInitialization
            --is kept in the map script, it should be placed above WSCode.
,
            OVERWRITE_TOTAL_INITIALIZATION = false
            --Enable to allow the WSCode.Parse function to split GUI triggers into files. May sometimes cause scripts to be parsed incorrectly. To set up a wrap that
            --includes GUI triggers, you must create a GUI trigger at the very bottom with the custom script line "end ]===]) do" in it.
,
            PARSE_GUI_TRIGGERS = true
            --Allows you to save the map script with changes made in-game to a file, then restart the map and load the modified map script. This is a powerful feature that
            --enables you to iterate your map much quicker. However, this option necessitates that the map script is suspended until main is called, even when the map is
            --launched regularly, which may have side effects. Only works if map script is wrapped by WSCode.Parse function. Recommended to use WSCode initializers when
            --using this feature.
,
            ENABLE_QUICK_RESTART = false
            --Always load the map script from the preload file in the CustomMapData directory if it exists. The map script should be compiled externally before launching
            -- the map. Requires ENABLE_QUICK_RESTART.
,
            ALWAYS_QUICK_RESTART = false
            --Enables debug mode across all parsed files. May drastically increase map loading time and reduce performance. Use with caution!
,
            GLOBAL_DEBUG = false
            --Tracks the script and linenumber at which each handle is created and displays it in the variable viewer when selecting it. In addition, counts all handles
            --created and not destroyed at each position in the code, detecting possible memory leaks. To show the report, type -leakreport. -leakreport X will print the
            --top X contributors to floating handles (default 10). leakreport X-Y will print positions X to Y. The function creating the handle must be listed in
            --editor.CREATOR_DESTRUCTOR_PAIRS.
,
            STORE_HANDLE_ORIGIN = true
            --If enabled, the traceback is preserved on TriggerExecute and TriggerEvaluate calls. Causes memory leaks.
,
            STORE_TRIGGER_TRACEBACK = false
            --Automatically pauses a script that was compiled in debug mode if more than this many lines have been executed during one game tick. Set to nil to disable.
,
            EXECUTION_LIMIT = 1e7
            --Writes a transformed map script to the WSCodeMapScript.txt file. This map script can be used to replace all script files in the Trigger Editor. This step is
            --necessary to remove WSCode from the map if the WSCode initializers are used. You have access to map optimization and script obfuscation options in the
            --finalizer section. The MAP_SCRIPT_PREFIX will be added to the beginning of the map script. After exporting the script, you need to do various string
            --replacements before it is ready. Remove the preload prefix and suffix, then replace (without quotation marks):
            --'   call Preload( "' -> '', and '" \)\n' -> '\n' (to keep line breaks), or '" \)\n' -> '' (to remove line breaks). Make sure regular expressions are enabled.
            --If you keep line breaks, you now have to do additional replacements:
            --' --- @TODO START OF LONG LINE - CONCATENATE MULTILINES YOURSELF AND REMOVE THIS: ---\n(.*)\n--- @TODO END OF LONG LINE. REMOVE THIS TOO. ---' -> '$1'
            --This will remove all multilines exactly two lines long. To remove all multilines three lines long, you add another (.*)\n in the center, and change the
            --replacement string to '$1$2'. Keep adding lines this way until all multilines are removed.
,
            FINALIZE_MAP_SCRIPT = false,
        },

        diagnostics = {
            --Throw a warning when a WSCode.Init function is called outside of the Parse wrapper. This may happen by accident when scripts or folders are moved around.
            INIT_OUTSIDE_OF_WRAP_WARNING = false
            --If enabled, writes the name of the last file being parsed by WSCode.Parse into the file WSCodeInitDump.txt, so that you gain information about which script
            --causes a crash on map initialization. Will not catch crashes occuring in TotalInitialization init functions. Only works if map script is wrapped by
            --WSCode.Parse function.
,
            INIT_DUMP = false
            --Prints the total initialization time of the map script and the individual contributions of the most expensive libraries.
,
            PROFILE_INIT = false
            --Writes the transpiled scripts of files in debug mode into the file WSCodeTranspiled<FileName>.txt, so that you can check what the transpiler is actually
            --doing.
,
            DUMP_TRANSPILED_SCRIPTS = false,
        },

        editor = {
            --Enables the editor for the players with these names. Uses substring, therefore #XXXX not required and an empty string enables it for all players.
            MAP_CREATORS = { ---@constant string[]
                "",
            }
,
            NEXT_LINE_HOTKEY = "F3", ---@constant string | nil
            CONTINUE_HOTKEY = "F3", ---@constant string | nil
            TOGGLE_HIDE_EDITOR_HOTKEY = "F1"            --0 = None, 1 = Shift, 2 = Ctrl, 3 = Shift + Ctrl
, ---@constant string | nil
            NEXT_LINE_METAKEY = 0, ---@constant integer
            CONTINUE_METAKEY = 2, ---@constant integer
            TOGGLE_HIDE_EDITOR_METAKEY = 2
            --Replaces the standard Friz Quadrata font with Consolas. This will ensure that all tab spaces remain aligned. Requires Consolas.ttf.
, ---@constant integer
            USE_MONOSPACE_FONT = true
            --Enable automatic export of script files into text files to be saved or imported again on a later session. Requires FileIO.
,
            ENABLE_SAVE_AND_LOAD = true
            --The folder to which all text files are exported. The complete path is Warcraft III\CustomMapData\Subfolder\.
,
            EXPORT_SUBFOLDER = "WSCode" .. (MapName and ("_" .. MapName) or "")
,
            ASSET_SUBFOLDER = "WSCodeAssets"
            --Automatically loads into the editor scripts that have been parsed by WSCode.Parse, but are not currently being debugged, when they produce an error.
,
            LOAD_EXTERNAL_SCRIPTS_ON_ERROR = true
            --Always halt the ALICE cycle when stopping at a breakpoint. If disabled, it will only stop if halted within an ALICE function.
,
            ALWAYS_HALT_ALICE_ON_BREAKPOINT = true
            --This function is called when the editor is shown or enabled.
,
            ON_ENABLE = function()
                ToggleUIIfNecessary()
                BlzEnableCursor(true)
                if RallyeUI then
                    RallyeUI.ShowDriverStandings(false)
                end
                if CinematicStudio then
                    CinematicStudio.BlackScreen(false)
                end
            end
            --This function is called when the editor is hidden.
,
            ON_DISABLE = function()
                ToggleUIIfNecessary()
                if RallyeUI then
                    RallyeUI.ShowDriverStandings(true)
                end
            end
            --This function is called when the editor is expanded.
,
            ON_EXPAND = function()
                ClearTextMessages()
            end
            --This function is called when the editor is collapsed.
,
            ON_COLLAPSE = function() end
            --This function is called when the script execution halts at a breakpoint.
,
            ON_BREAK = function(scriptName)
                if CinematicStudio then
                    CinematicStudio.BlackScreen(false)
                end
                if ALICE_Initialized then
                    ALICE_ForAllObjectsDo(PauseUnit, "unit", nil, true)
                end
                WSCode.LockEditor(false)
                ShowInterface(true, 0)
                EnableUserControl(true)
            end
            --This function is called when the script execution resumes from a breakpoint.
,
            ON_RESUME = function(scriptName)
                if ALICE_Initialized then
                    ALICE_ForAllObjectsDo(PauseUnit, "unit", nil, false)
                end
            end
            --This function is called when a script encounters an error.
,
            ON_ERROR = function(scriptName)
                if CinematicStudio then
                    CinematicStudio.BlackScreen(false)
                    if CinematicStudio.IsInCinematic() then
                        CinematicStudio.Abort()
                    end
                end
                EnableUserControl(true)
                ShowInterface(true, 0)
                WSCode.LockEditor(false)
            end
            --This function is called when the editor text window is focused.
,
            ON_FOCUS = function() end
            --This function is called when the editor text window is defocused.
,
            ON_DEFOCUS = function() end
            --This function is called when a world object is viewed in the variable editor.
,
            ON_OBJECT_VIEW = function(whichObject, x, y)
                if EditorCameraEnabled then
                    if HandleType[whichObject] == "camerasetup" then
                        EditorCamera.Set(CinematicStudio.ConvertCameraSetup(whichObject))
                    elseif FreeCameraEnabled and CinematicStudio then
                        CinematicStudio.GameCamera.x = x
                        CinematicStudio.GameCamera.y = y
                        EditorCamera.Set(EditorCamera.ConvertToFreeCamera(CinematicStudio.GameCamera))
                    else
                        if CinematicStudio then
                            CinematicStudio.GameCamera.x = x
                            CinematicStudio.GameCamera.y = y
                            EditorCamera.Set(CinematicStudio.GameCamera)
                        end
                        if type(whichObject) == "table" then
                            EditorCamera.Set(whichObject)
                        else
                            EditorCamera.Set({ x = x, y = y })
                        end
                    end
                elseif HandleType[whichObject] == "camerasetup" then
                    CameraSetupApply(whichObject, true, true)
                else
                    ResetToGameCamera(0)
                    SetCameraPosition(x, y)
                    if
                        CinematicStudio
                        and type(whichObject) == "table"
                        and rawget(whichObject, "aoa")
                        and rawget(whichObject, "rot")
                    then
                        local setup = CinematicStudio.ConvertCameraData(whichObject)
                        CameraSetupApply(setup, true, true)
                    end
                end
            end
            --This function is called when the back button is clicked while viewing a world object in the variable editor.
,
            ON_OBJECT_UNVIEW = function(whichObject) end
            --Setting a list of legal characters protects you from messing up your code by accidently pressing the key of a character that cannot be displayed,
            --leading to compile errors from seemingly valid code. This list contains all utf8 1-byte characters except the grave accents. Set to nil to disable.
,
            LEGAL_CHARACTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!$&()[]=?:;,._#*~/{}<>^+-|'\"\\@% 1234567890\t"
            --If the user presses no key for this long, a new undo step is created.
,
            MIN_TIME_BETWEEN_UNDO_STEPS = 1.0
,
            GET_PARENT = function()
                if FullScreenParent then
                    local parent = BlzCreateFrameByType("FRAME", "", FullScreenParent, "", 0)
                    BlzFrameSetLevel(parent, 6)
                    return parent
                end
                return BlzGetFrameByName("ConsoleUIBackdrop", 0)
            end
            --These parameter control the layout of the code editor.
,
            COLLAPSED_X = 0.567,
            Y_TOP = 0.57,
            EXPANDED_X = 0.14,
            LINE_SPACING = 0.0085,
