        end

        EnumDestructablesInRect = function(r, filter, actionFunc)
            if actionFunc then
                return originals.enumDestructables(r, filter, function()
                    return coroutine.resume(getCoroutine(getTryWrapper(actionFunc)))
                end)
            else
