            BlzFrameSetText(nameDialog.title, "|cffffcc00Enter Expression|r")

            local lines
            if selection.hasSelection then
                lines = ConvertSelectionToLines()
            end

            BlzFrameSetText(nameDialog.textField, lines and #lines == 1 and lines[1] or "")
        end

