            BlzFrameSetTexture(BlzFrameGetChild(buttons["Traceback"], 2), "ReplaceableTextures\\CommandButtonsDisabled\\DISBTNHealingWave.blp", 0, true)
            BlzFrameSetEnable(buttons["Traceback"], false)
