            BlzFrameSetPoint(closeButton, FRAMEPOINT_TOPRIGHT, tabNavigator.frames[tabs.names[t]], FRAMEPOINT_TOPRIGHT, -tabNavigator.CLOSE_BUTTON_INSET, -tabNavigator.CLOSE_BUTTON_INSET)
