        BlzFrameSetPoint(tabs.addTabFrame, FRAMEPOINT_BOTTOMLEFT, tabNavigator.frames[tabs.names[tabs.amount]], FRAMEPOINT_BOTTOMRIGHT, -tabNavigator.OVERLAP, 0)
